_PACKAGES.add('ui')
_SOURCES['ui.block_picker_dialog'] = '"""\nSélecteur de bloc (PATCH 30).\n\nBoîte de dialogue listant tous les blocs du document (aperçu via\n`core.block_preview.preview_for_block`) pour choisir la cible d\'un\nlien interne. Le bloc source est exclu de la liste (se lier à\nsoi-même n\'a pas de sens).\n"""\nfrom __future__ import annotations\n\nfrom typing import Optional\n\nfrom PySide6.QtCore import Qt\nfrom PySide6.QtWidgets import QDialog, QListWidget, QListWidgetItem, QVBoxLayout\n\nfrom core.block_preview import preview_for_block\nfrom core.document import Document\n\n# Réutilise les libellés lisibles du menu "/" (PATCH 25) plutôt que\n# de les dupliquer.\nfrom ui.command_registry import COMMANDS\n\n_TYPE_LABELS: dict[str, str] = {command["id"]: command["label"] for command in COMMANDS}\n\n\nclass BlockPickerDialog(QDialog):\n    """Fenêtre de choix d\'un bloc du document (pour un lien interne)."""\n\n    def __init__(\n        self,\n        document: Document,\n        exclude_block_id: Optional[str] = None,\n        parent=None,\n    ) -> None:\n        super().__init__(parent)\n        self._document = document\n        self.selected_block_id: Optional[str] = None\n\n        self.setWindowTitle("Lier vers un bloc")\n        self.resize(440, 400)\n\n        layout = QVBoxLayout(self)\n\n        self._list = QListWidget(self)\n        self._list.itemActivated.connect(self._on_item_activated)\n        layout.addWidget(self._list)\n\n        for block in document.blocks:\n            if block.id == exclude_block_id:\n                continue\n            type_label = _TYPE_LABELS.get(block.type, block.type)\n            item = QListWidgetItem(f"[{type_label}] {preview_for_block(block)}")\n            item.setData(Qt.UserRole, block.id)\n            self._list.addItem(item)\n\n    def _on_item_activated(self, item: QListWidgetItem) -> None:\n        self.selected_block_id = item.data(Qt.UserRole)\n        self.accept()\n'
_SOURCES['ui.blocks'] = ''
_PACKAGES.add('ui.blocks')
_SOURCES['ui.blocks.bar_chart_block_widget'] = '"""\nWidget graphique du bloc "Graphique en bâtonnets" (PATCH 47, révisé PATCH 49).\n\nBarre pleine bleue = "Prévu". Marqueur en pointillés = "Réel" (rouge\nen dépassement de budget, vert sinon), si renseigné.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtCore import Qt\nfrom PySide6.QtGui import QColor, QPainter, QPen\nfrom PySide6.QtWidgets import (\n    QDoubleSpinBox,\n    QGridLayout,\n    QHBoxLayout,\n    QLabel,\n    QLineEdit,\n    QPushButton,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom blocks.bar_chart_block import BarChartBlock, budget_marker_color\n\n_MARGIN = 30\n\n\nclass _BarChartCanvas(QWidget):\n    def __init__(self, parent=None) -> None:\n        super().__init__(parent)\n        self._bars: list[dict] = []\n        self._y_axis_label = ""\n        self.setMinimumHeight(220)\n\n    def set_data(self, bars: list[dict], y_axis_label: str) -> None:\n        self._bars = bars\n        self._y_axis_label = y_axis_label\n        self.update()\n\n    def paintEvent(self, event) -> None:  # noqa: N802\n        painter = QPainter(self)\n        painter.setRenderHint(QPainter.Antialiasing)\n\n        w, h = self.width(), self.height()\n        plot_w, plot_h = w - 2 * _MARGIN, h - 2 * _MARGIN\n\n        if self._y_axis_label:\n            painter.save()\n            painter.translate(12, h / 2)\n            painter.rotate(-90)\n            painter.drawText(-plot_h / 2, 0, plot_h, 16, Qt.AlignCenter, self._y_axis_label)\n            painter.restore()\n\n        painter.drawLine(_MARGIN, h - _MARGIN, w - _MARGIN, h - _MARGIN)\n\n        if not self._bars:\n            painter.drawText(self.rect(), Qt.AlignCenter, "Aucune barre à afficher.")\n            painter.end()\n            return\n\n        max_value = max(\n            (max(abs(b["value"]), abs(b["actual"] or 0)) for b in self._bars), default=1.0\n        ) or 1.0\n        slot_w = plot_w / len(self._bars)\n        bar_w = slot_w * 0.6\n\n        for i, bar in enumerate(self._bars):\n            bar_h = abs(bar["value"]) / max_value * plot_h\n            x = _MARGIN + i * slot_w + (slot_w - bar_w) / 2\n            y = h - _MARGIN - bar_h\n            # Barre "Prévu" pleine, toujours bleue.\n            painter.fillRect(int(x), int(y), int(bar_w), int(bar_h), QColor(bar["color"]))\n            painter.drawText(int(x - 10), h - _MARGIN + 2, int(bar_w + 20), 16, Qt.AlignCenter, bar["label"])\n            painter.drawText(int(x - 10), int(y) - 16, int(bar_w + 20), 16, Qt.AlignCenter, str(bar["value"]))\n\n            # Marqueur "Réel" en pointillés (rouge si dépassement, vert sinon).\n            marker_color = budget_marker_color(bar)\n            if marker_color is not None:\n                actual_h = abs(bar["actual"]) / max_value * plot_h\n                actual_y = h - _MARGIN - actual_h\n                pen = QPen(QColor(marker_color), 2, Qt.DashLine)\n                painter.setPen(pen)\n                painter.drawLine(int(x), int(actual_y), int(x + bar_w), int(actual_y))\n                painter.drawText(\n                    int(x - 10), int(actual_y) - 16, int(bar_w + 20), 16, Qt.AlignCenter, str(bar["actual"])\n                )\n                painter.setPen(QPen(QColor("#000000")))\n\n        painter.end()\n\n\nclass BarChartBlockWidget(QWidget):\n    """Widget d\'un BarChartBlock : titre, barres éditables (Prévu + Réel), graphique."""\n\n    def __init__(self, block: BarChartBlock, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n\n        layout = QVBoxLayout(self)\n        layout.setContentsMargins(0, 0, 0, 0)\n\n        header = QHBoxLayout()\n        self._title_edit = QLineEdit(block.title, self)\n        self._title_edit.setPlaceholderText("Titre")\n        self._title_edit.setFrame(False)\n        self._title_edit.setStyleSheet(\n            "QLineEdit { border: none; background: transparent; font-weight: bold; font-size: 15pt; }"\n        )\n        self._title_edit.textChanged.connect(self._on_title_changed)\n        header.addWidget(self._title_edit, 1)\n        self._y_label_edit = QLineEdit(block.y_axis_label, self)\n        self._y_label_edit.setPlaceholderText("Axe Y")\n        self._y_label_edit.setFrame(False)\n        self._y_label_edit.setStyleSheet(\n            "QLineEdit { border: none; background: transparent; color: #666666; }"\n        )\n        self._y_label_edit.textChanged.connect(self._on_y_label_changed)\n        header.addWidget(self._y_label_edit, 1)\n        layout.addLayout(header)\n\n        self._canvas = _BarChartCanvas(self)\n        layout.addWidget(self._canvas)\n\n        self._bars_area = QGridLayout()\n        self._bars_area.addWidget(QLabel("<b>Phase</b>", self), 0, 0)\n        self._bars_area.addWidget(QLabel("<b>Prévu</b>", self), 0, 1)\n        self._bars_area.addWidget(QLabel("<b>Réel</b>", self), 0, 2)\n        layout.addLayout(self._bars_area)\n\n        add_button = QPushButton("+ Ajouter une barre", self)\n        add_button.clicked.connect(self._on_add_bar)\n        layout.addWidget(add_button)\n\n        self._rebuild_bar_rows()\n        self._refresh_canvas()\n\n    @property\n    def block(self) -> BarChartBlock:\n        return self._block\n\n    def _rebuild_bar_rows(self) -> None:\n        # Conserve la ligne d\'en-tête (ligne 0), vide seulement les lignes de données.\n        for row_index in range(1, self._bars_area.rowCount()):\n            for col in range(4):\n                item = self._bars_area.itemAtPosition(row_index, col)\n                if item is not None and item.widget() is not None:\n                    item.widget().deleteLater()\n\n        for row_index, bar in enumerate(self._block.bars, start=1):\n            label_edit = QLineEdit(bar["label"], self)\n            label_edit.textChanged.connect(lambda text, bid=bar["id"]: self._on_bar_label_changed(bid, text))\n            self._bars_area.addWidget(label_edit, row_index, 0)\n\n            value_spin = QDoubleSpinBox(self)\n            value_spin.setRange(-1000000, 1000000)\n            value_spin.setValue(bar["value"])\n            value_spin.valueChanged.connect(lambda v, bid=bar["id"]: self._on_bar_value_changed(bid, v))\n            self._bars_area.addWidget(value_spin, row_index, 1)\n\n            actual_spin = QDoubleSpinBox(self)\n            actual_spin.setRange(-1000000, 1000000)\n            actual_spin.setValue(bar["actual"] if bar["actual"] is not None else 0.0)\n            actual_spin.valueChanged.connect(lambda v, bid=bar["id"]: self._on_bar_actual_changed(bid, v))\n            self._bars_area.addWidget(actual_spin, row_index, 2)\n\n            remove_button = QPushButton("×", self)\n            remove_button.clicked.connect(lambda _, bid=bar["id"]: self._on_remove_bar(bid))\n            self._bars_area.addWidget(remove_button, row_index, 3)\n\n    def _refresh_canvas(self) -> None:\n        self._canvas.set_data(self._block.bars, self._block.y_axis_label)\n\n    # -- Callbacks --------------------------------------------------------\n\n    def _on_title_changed(self, text: str) -> None:\n        self._block.title = text\n\n    def _on_y_label_changed(self, text: str) -> None:\n        self._block.y_axis_label = text\n        self._refresh_canvas()\n\n    def _on_add_bar(self) -> None:\n        self._block.add_bar(label=f"Phase {len(self._block.bars) + 1}", value=0)\n        self._rebuild_bar_rows()\n        self._refresh_canvas()\n\n    def _on_remove_bar(self, bar_id: str) -> None:\n        self._block.remove_bar(bar_id)\n        self._rebuild_bar_rows()\n        self._refresh_canvas()\n\n    def _on_bar_label_changed(self, bar_id: str, text: str) -> None:\n        self._block.set_bar_label(bar_id, text)\n        self._refresh_canvas()\n\n    def _on_bar_value_changed(self, bar_id: str, value: float) -> None:\n        self._block.set_bar_value(bar_id, value)\n        self._refresh_canvas()\n\n    def _on_bar_actual_changed(self, bar_id: str, value: float) -> None:\n        self._block.set_bar_actual(bar_id, value)\n        self._refresh_canvas()\n'
_SOURCES['ui.blocks.block_container'] = '"""\nConteneur générique de bloc (PATCH 13, menu contextuel PATCH 26, icône\nde type PATCH 34).\n\nAjoute une poignée de glisser-déposer (« ⠿ ») et une icône\nreprésentative du type de bloc à gauche de n\'importe quel widget de\nbloc, pour permettre de réordonner et d\'identifier au premier coup\nd\'œil tous les types de blocs (texte, titres, checklists, images,\ntableaux...) de la même façon dans le document. Le clic droit ouvre\nun menu contextuel complet (dupliquer, supprimer, déplacer, convertir),\ndélégué à la fenêtre principale via un callback.\n"""\nfrom __future__ import annotations\n\nfrom typing import Callable, Optional\n\nfrom PySide6.QtCore import QMimeData, QPoint, Qt\nfrom PySide6.QtGui import QContextMenuEvent, QDrag, QMouseEvent\nfrom PySide6.QtWidgets import QHBoxLayout, QLabel, QWidget\n\n# Type MIME privé transportant l\'ID du bloc glissé.\nBLOCK_MIME_TYPE = "application/x-notion-lite-block-id"\n\n\nclass _DragHandle(QLabel):\n    """Poignée : point de départ du glisser-déposer d\'un bloc."""\n\n    def __init__(self, block_id: str, parent: QWidget | None = None) -> None:\n        super().__init__("⠿", parent)\n        self._block_id = block_id\n        self.setCursor(Qt.OpenHandCursor)\n        self.setFixedWidth(18)\n        self.setAlignment(Qt.AlignCenter)\n        self._drag_start: QPoint | None = None\n\n    def mousePressEvent(self, event: QMouseEvent) -> None:\n        if event.button() == Qt.LeftButton:\n            self._drag_start = event.position().toPoint()\n        super().mousePressEvent(event)\n\n    def mouseMoveEvent(self, event: QMouseEvent) -> None:\n        if self._drag_start is None or not (event.buttons() & Qt.LeftButton):\n            return\n        if (event.position().toPoint() - self._drag_start).manhattanLength() < 10:\n            return  # en dessous du seuil : pas encore un vrai glisser\n\n        mime_data = QMimeData()\n        mime_data.setData(BLOCK_MIME_TYPE, self._block_id.encode("utf-8"))\n        drag = QDrag(self)\n        drag.setMimeData(mime_data)\n        drag.exec(Qt.MoveAction)\n        self._drag_start = None\n\n\nclass BlockContainer(QWidget):\n    """Enveloppe un widget de bloc avec sa poignée de déplacement et\n    son clic droit (PATCH 26).\n\n    ``content`` reste accessible via l\'attribut du même nom, pour que\n    la fenêtre principale puisse continuer à interagir directement\n    avec le widget métier du bloc (focus, texte, etc.).\n    """\n\n    def __init__(\n        self,\n        content: QWidget,\n        block_id: str,\n        on_context_menu_requested: Optional[Callable[[str, QPoint], None]] = None,\n        icon: str = "",\n        extra_top_margin: int = 0,\n        parent: QWidget | None = None,\n    ) -> None:\n        super().__init__(parent)\n        self.content = content\n        self.block_id = block_id\n        self._on_context_menu_requested = on_context_menu_requested\n\n        layout = QHBoxLayout(self)\n        layout.setContentsMargins(0, extra_top_margin, 0, 0)\n        layout.addWidget(_DragHandle(block_id, self))\n        if icon:\n            icon_label = QLabel(icon, self)\n            icon_label.setFixedWidth(22)\n            icon_label.setAlignment(Qt.AlignCenter)\n            layout.addWidget(icon_label)\n        layout.addWidget(content, stretch=1)\n\n    def contextMenuEvent(self, event: QContextMenuEvent) -> None:\n        """PATCH 26 — Clic droit complet : délégué à la fenêtre principale."""\n        if self._on_context_menu_requested is None:\n            return\n        self._on_context_menu_requested(self.block_id, event.globalPos())\n        event.accept()\n'
_SOURCES['ui.blocks.checklist_block_widget'] = '"""\nWidget graphique du bloc Checklist.\n\nChaque élément est affiché comme une ligne : case à cocher + champ\nde texte éditable + bouton de suppression. Toute modification est\nimmédiatement répercutée dans le ChecklistBlock associé, en utilisant\nl\'id de l\'élément (et non sa position) comme référence stable.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtWidgets import (\n    QCheckBox,\n    QHBoxLayout,\n    QLineEdit,\n    QPushButton,\n    QToolButton,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom blocks.checklist_block import ChecklistBlock\n\n\nclass _ChecklistItemRow(QWidget):\n    """Une ligne de la checklist : case à cocher + texte + suppression."""\n\n    def __init__(\n        self, item_id: str, text: str, checked: bool, owner: "ChecklistBlockWidget"\n    ) -> None:\n        super().__init__(owner)\n        self._owner = owner\n        self.item_id = item_id\n\n        layout = QHBoxLayout(self)\n        layout.setContentsMargins(0, 0, 0, 0)\n\n        self.checkbox = QCheckBox(self)\n        self.checkbox.setChecked(checked)\n        self.checkbox.toggled.connect(self._on_toggled)\n        layout.addWidget(self.checkbox)\n\n        self.line_edit = QLineEdit(self)\n        self.line_edit.setText(text)\n        self.line_edit.setPlaceholderText("Élément de la liste...")\n        self.line_edit.textChanged.connect(self._on_text_changed)\n        self.line_edit.returnPressed.connect(self._on_return_pressed)\n        layout.addWidget(self.line_edit, 1)\n\n        remove_button = QToolButton(self)\n        remove_button.setText("×")\n        remove_button.setToolTip("Supprimer cet élément")\n        remove_button.clicked.connect(lambda: self._owner.remove_row(self))\n        layout.addWidget(remove_button)\n\n    def _on_toggled(self, checked: bool) -> None:\n        self._owner.on_item_checked_changed(self, checked)\n\n    def _on_text_changed(self, text: str) -> None:\n        self._owner.on_item_text_changed(self, text)\n\n    def _on_return_pressed(self) -> None:\n        """PATCH 49 — Entrée dans le champ ajoute un nouvel élément,\n        comme le bouton "+ Ajouter un élément", et donne le focus au\n        nouveau champ."""\n        self._owner.insert_row_after(self)\n\n\nclass ChecklistBlockWidget(QWidget):\n    """Représentation graphique éditable d\'un ChecklistBlock."""\n\n    def __init__(self, block: ChecklistBlock, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n        self._rows: list[_ChecklistItemRow] = []\n\n        self._layout = QVBoxLayout(self)\n        self._layout.setContentsMargins(0, 0, 0, 0)\n\n        # PATCH 11 : la checklist s\'affiche toujours triée (non cochées\n        # d\'abord), y compris juste après un chargement de fichier.\n        self._block.sort_by_status()\n        for item in block.items:\n            self._append_row(item)\n\n        self._add_button = QPushButton("+ Ajouter un élément", self)\n        self._add_button.clicked.connect(self._on_add_clicked)\n        self._layout.addWidget(self._add_button)\n\n    @property\n    def block(self) -> ChecklistBlock:\n        return self._block\n\n    def _append_row(self, item: dict) -> _ChecklistItemRow:\n        row = _ChecklistItemRow(\n            item["id"], item.get("text", ""), item.get("checked", False), self\n        )\n        # Toujours insérée juste avant le bouton "+ Ajouter" (en dernier).\n        self._layout.insertWidget(len(self._rows), row)\n        self._rows.append(row)\n        return row\n\n    def _rebuild_rows(self, focus_item_id: str | None = None) -> None:\n        """Reconstruit toutes les lignes dans l\'ordre courant du bloc (PATCH 11).\n\n        L\'utilisateur ne déplace jamais une ligne manuellement : c\'est\n        toujours le tri du bloc qui pilote l\'ordre affiché.\n        """\n        for row in self._rows:\n            self._layout.removeWidget(row)\n            row.deleteLater()\n        self._rows = []\n\n        focus_row: _ChecklistItemRow | None = None\n        for item in self._block.items:\n            row = self._append_row(item)\n            if focus_item_id is not None and item["id"] == focus_item_id:\n                focus_row = row\n        if focus_row is not None:\n            focus_row.line_edit.setFocus()\n\n    def _on_add_clicked(self) -> None:\n        item = self._block.add_item()\n        row = self._append_row(item)\n        row.line_edit.setFocus()\n\n    def insert_row_after(self, row: "_ChecklistItemRow") -> None:\n        """PATCH 49 — Ajoute un nouvel élément (identique au bouton\n        "+ Ajouter un élément") suite à un appui sur Entrée dans une\n        ligne existante, et donne le focus au nouveau champ."""\n        item = self._block.add_item()\n        new_row = self._append_row(item)\n        new_row.line_edit.setFocus()\n\n    def remove_row(self, row: "_ChecklistItemRow") -> None:\n        self._block.remove_item(row.item_id)\n        self._rows.remove(row)\n        self._layout.removeWidget(row)\n        row.deleteLater()\n\n    def on_item_text_changed(self, row: "_ChecklistItemRow", text: str) -> None:\n        self._block.set_item_text(row.item_id, text)\n\n    def on_item_checked_changed(self, row: "_ChecklistItemRow", checked: bool) -> None:\n        """Coche/décoche puis re-trie automatiquement (PATCH 11)."""\n        self._block.set_item_checked(row.item_id, checked)\n        self._block.sort_by_status()\n        self._rebuild_rows(focus_item_id=row.item_id)\n'
_SOURCES['ui.blocks.code_block_widget'] = '"""\nWidget graphique du bloc Code (PATCH 22).\n\nQTextEdit en texte brut, police monospace (Consolas/Courier New selon\nla plateforme) et fond légèrement grisé pour se distinguer du texte\nnormal. La coloration syntaxique n\'est pas incluse (amélioration\nfuture prévue par le plan du projet).\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtGui import QFont, QPalette\nfrom PySide6.QtWidgets import QTextEdit\n\nfrom blocks.code_block import CodeBlock\n\n_MONOSPACE_FAMILY = "Consolas"\n\n\nclass CodeBlockWidget(QTextEdit):\n    """Représentation graphique éditable d\'un CodeBlock."""\n\n    def __init__(self, block: CodeBlock, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n\n        self.setAcceptRichText(False)\n        self.setPlainText(block.content)\n        self.setPlaceholderText("// Code...")\n        self.setFrameStyle(0)\n\n        font = QFont(_MONOSPACE_FAMILY)\n        font.setStyleHint(QFont.Monospace)\n        self.setFont(font)\n        # Fond/bordure dérivés de la palette courante (claire ou sombre,\n        # PATCH 32) plutôt que des couleurs fixes.\n        alt_bg = self.palette().color(QPalette.AlternateBase).name()\n        border_color = self.palette().color(QPalette.Mid).name()\n        self.setStyleSheet(\n            f"QTextEdit {{ background-color: {alt_bg}; border: 1px solid {border_color}; padding: 8px; }}"\n        )\n\n        self.textChanged.connect(self._on_text_changed)\n\n    @property\n    def block(self) -> CodeBlock:\n        return self._block\n\n    def _on_text_changed(self) -> None:\n        self._block.content = self.toPlainText()\n'
_SOURCES['ui.blocks.dependency_gantt_block_widget'] = '"""\nWidget graphique du bloc "Gantt (dépendances)" (PATCH 46, révisé PATCH 49).\n\nUne ligne par personne assignée à au moins une sous-tâche ; chaque\nsous-tâche est dessinée comme une barre (couleur = risque) sur la\nligne de chaque personne qui lui est assignée, sous un axe temporel\ngradué. Le retard (noir) ou l\'avance (bleu) déclaré sur une\nsous-tâche est visible directement sur sa barre.\n\nPATCH 49 :\n    - Axe temporel gradué en haut du graphique.\n    - L\'écart (retard/avance) se règle via une pop-up qui s\'ouvre au\n      clic sur le bâtonnet concerné, et s\'écrit dans la colonne\n      "Ecarts" du tableau source (sélectionnée comme les autres\n      colonnes) plutôt que stockée dans le bloc.\n    - Sélecteur d\'unité "Jours" / "Mois" : change l\'échelle de l\'axe\n      et l\'affichage des valeurs chiffrées (l\'écart saisi et les\n      graduations), sans jamais changer le stockage interne, qui\n      reste toujours en jours (voir DAYS_PER_MONTH côté bloc).\n"""\nfrom __future__ import annotations\n\nimport math\n\nfrom PySide6.QtCore import QRect, QTimer, Qt\nfrom PySide6.QtGui import QColor, QPainter, QPalette, QPen\nfrom PySide6.QtWidgets import (\n    QComboBox,\n    QDialog,\n    QDialogButtonBox,\n    QDoubleSpinBox,\n    QHBoxLayout,\n    QLabel,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom blocks.dependency_gantt_block import (\n    DAYS_PER_MONTH,\n    UNIT_DAYS,\n    UNIT_MONTHS,\n    DependencyGanttBlock,\n    available_delta_columns,\n    available_dependency_columns,\n    available_duration_columns,\n    available_label_columns,\n    available_person_columns,\n    available_risk_columns,\n    compute_schedule,\n    find_source_table,\n)\nfrom blocks.table_block import TableBlock\n\n_REFRESH_INTERVAL_MS = 500\n_ROW_HEIGHT = 30\n_AXIS_HEIGHT = 24\n_LABEL_WIDTH = 120\n_DELAY_COLOR = QColor("#1a1a1a")\n_ADVANCE_COLOR = QColor("#2196f3")\n\n_UNIT_LABELS = {UNIT_DAYS: "Jours", UNIT_MONTHS: "Mois"}\n\n\ndef _nice_axis_step(max_value: float) -> float:\n    """Choisit un pas d\'axe "rond" et toujours entier (1, 2, 5, 10, 20,\n    50, 100, ...), qui grandit avec `max_value` (dézoomer donne des\n    graduations plus espacées : 1, 5, 10, 20 J...), quelle que soit\n    l\'unité d\'affichage (jours ou mois — jamais de graduation\n    fractionnaire comme "0.1")."""\n    raw_step = max(max_value / 8, 1.0)\n    magnitude = 10 ** math.floor(math.log10(raw_step))\n    for factor in (1, 2, 5, 10):\n        step = factor * magnitude\n        if step >= raw_step:\n            return step\n    return magnitude * 10\n\n\nclass _DependencyGanttCanvas(QWidget):\n    """Zone de dessin : axe temporel + une ligne par personne, une barre\n    par sous-tâche assignée. Cliquer sur une barre ouvre la pop-up\n    d\'écart (retard/avance) via le callback `on_bar_clicked`."""\n\n    def __init__(self, parent=None) -> None:\n        super().__init__(parent)\n        self._people: list[str] = []\n        self._tasks_by_person: dict[str, list[dict]] = {}\n        self._bar_rects: list[tuple[QRect, dict]] = []\n        self._time_unit = UNIT_DAYS\n        self.on_bar_clicked = None\n        self.setMinimumHeight(_ROW_HEIGHT + _AXIS_HEIGHT)\n\n    def set_time_unit(self, unit: str) -> None:\n        self._time_unit = unit\n        self.update()\n\n    def set_schedule(self, schedule: list[dict]) -> None:\n        people: list[str] = []\n        tasks_by_person: dict[str, list[dict]] = {}\n        for task in schedule:\n            for name in task["person_names"] or ["(non assigné)"]:\n                if name not in tasks_by_person:\n                    tasks_by_person[name] = []\n                    people.append(name)\n                tasks_by_person[name].append(task)\n        self._people = people\n        self._tasks_by_person = tasks_by_person\n        self.setMinimumHeight(max(_ROW_HEIGHT, _ROW_HEIGHT * len(people)) + _AXIS_HEIGHT)\n        self.update()\n\n    def mousePressEvent(self, event) -> None:  # noqa: N802\n        if self.on_bar_clicked is not None:\n            for rect, task in reversed(self._bar_rects):\n                if rect.contains(event.pos()):\n                    self.on_bar_clicked(task)\n                    return\n        super().mousePressEvent(event)\n\n    def paintEvent(self, event) -> None:  # noqa: N802\n        painter = QPainter(self)\n        painter.setRenderHint(QPainter.Antialiasing)\n        self._bar_rects = []\n\n        if not self._people:\n            painter.setPen(QPen(self.palette().color(QPalette.WindowText)))\n            painter.drawText(self.rect(), Qt.AlignCenter, "Aucune donnée à afficher.")\n            painter.end()\n            return\n\n        max_x_days = max(\n            (max(t["resolution"], t["end"]) for tasks in self._tasks_by_person.values() for t in tasks),\n            default=1.0,\n        ) or 1.0\n\n        chart_width = max(self.width() - _LABEL_WIDTH - 10, 20)\n\n        def to_x(day: float) -> int:\n            return _LABEL_WIDTH + int(day / max_x_days * chart_width)\n\n        # -- Axe temporel (PATCH 49), gradué dans l\'unité choisie -------\n        divisor = DAYS_PER_MONTH if self._time_unit == UNIT_MONTHS else 1.0\n        max_x_display = max_x_days / divisor\n        step_display = _nice_axis_step(max_x_display)\n        unit_suffix = "M" if self._time_unit == UNIT_MONTHS else "J"\n\n        painter.setPen(QPen(QColor("#888888"), 1))\n        painter.drawLine(_LABEL_WIDTH, _AXIS_HEIGHT, self.width(), _AXIS_HEIGHT)\n        tick_display = 0.0\n        while tick_display <= max_x_display + step_display / 2:\n            x = to_x(tick_display * divisor)\n            painter.drawLine(x, _AXIS_HEIGHT - 4, x, _AXIS_HEIGHT)\n            painter.drawText(x - 20, 0, 40, _AXIS_HEIGHT - 4, Qt.AlignCenter, f"{unit_suffix}{tick_display:g}")\n            tick_display += step_display\n\n        for i, name in enumerate(self._people):\n            y = _AXIS_HEIGHT + i * _ROW_HEIGHT\n            painter.setPen(QPen(self.palette().color(QPalette.WindowText)))\n            painter.drawText(0, y, _LABEL_WIDTH, _ROW_HEIGHT, Qt.AlignVCenter, name)\n            for task in self._tasks_by_person[name]:\n                start, end, resolution = task["start"], task["end"], task["resolution"]\n                color = QColor(task["color"])\n                x_start, x_end = to_x(start), to_x(end)\n                bar_rect = QRect(x_start, y + 5, max(x_end - x_start, 2), _ROW_HEIGHT - 10)\n                painter.fillRect(bar_rect, color)\n                hit_rect = QRect(bar_rect)\n\n                if task["delta"] > 0:\n                    # Retard : prolongement noir jusqu\'au point de résolution.\n                    x_resolution = to_x(resolution)\n                    extra = QRect(x_end, y + 5, max(x_resolution - x_end, 2), _ROW_HEIGHT - 10)\n                    painter.fillRect(extra, _DELAY_COLOR)\n                    hit_rect = hit_rect.united(extra)\n                elif task["delta"] < 0:\n                    # Avance : le temps gagné (fin de la barre normale) en bleu.\n                    x_resolution = to_x(resolution)\n                    extra = QRect(x_resolution, y + 5, max(x_end - x_resolution, 2), _ROW_HEIGHT - 10)\n                    painter.fillRect(extra, _ADVANCE_COLOR)\n\n                self._bar_rects.append((hit_rect, task))\n\n        painter.end()\n\n\nclass _DeltaDialog(QDialog):\n    """Pop-up d\'édition de l\'écart (retard/avance) d\'une sous-tâche.\n\n    La valeur est saisie et affichée dans l\'unité choisie pour le\n    Gantt (jours ou mois), mais toujours convertie en jours avant\n    d\'être renvoyée via value_in_days().\n    """\n\n    def __init__(self, task_label: str, current_delta_days: float, unit: str, parent=None) -> None:\n        super().__init__(parent)\n        self.setWindowTitle(f"Écart — {task_label}")\n        self._unit = unit\n        divisor = DAYS_PER_MONTH if unit == UNIT_MONTHS else 1.0\n\n        layout = QVBoxLayout(self)\n        unit_label = _UNIT_LABELS.get(unit, "Jours").lower()\n        layout.addWidget(\n            QLabel(f"Retard (positif) ou avance (négatif), en {unit_label} :", self)\n        )\n        self._spin = QDoubleSpinBox(self)\n        self._spin.setRange(-999, 999)\n        self._spin.setDecimals(2)\n        self._spin.setValue(current_delta_days / divisor)\n        layout.addWidget(self._spin)\n\n        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel, self)\n        buttons.accepted.connect(self.accept)\n        buttons.rejected.connect(self.reject)\n        layout.addWidget(buttons)\n\n    def value_in_days(self) -> float:\n        divisor = DAYS_PER_MONTH if self._unit == UNIT_MONTHS else 1.0\n        return self._spin.value() * divisor\n\n\nclass DependencyGanttBlockWidget(QWidget):\n    """Widget d\'un DependencyGanttBlock : sélecteurs de source + graphique."""\n\n    def __init__(self, block: DependencyGanttBlock, document, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n        self._document = document\n        self._syncing = False\n\n        layout = QVBoxLayout(self)\n        layout.setContentsMargins(0, 0, 0, 0)\n\n        selectors = QHBoxLayout()\n        self._combos: dict[str, QComboBox] = {}\n        for key, label in (\n            ("table", "Tableau"),\n            ("label", "Sous-tâches"),\n            ("person", "Personnes"),\n            ("duration", "Durée"),\n            ("risk", "Risques"),\n            ("dependency", "Dépendances"),\n            ("delta", "Ecarts"),\n        ):\n            selectors.addWidget(QLabel(f"{label} :", self))\n            combo = QComboBox(self)\n            combo.currentIndexChanged.connect(self._on_source_changed)\n            selectors.addWidget(combo, 1)\n            self._combos[key] = combo\n        layout.addLayout(selectors)\n\n        unit_row = QHBoxLayout()\n        unit_row.addWidget(QLabel("Unité :", self))\n        self._unit_combo = QComboBox(self)\n        self._unit_combo.addItem("Jours", UNIT_DAYS)\n        self._unit_combo.addItem("Mois", UNIT_MONTHS)\n        index = self._unit_combo.findData(self._block.time_unit)\n        self._unit_combo.setCurrentIndex(index if index >= 0 else 0)\n        self._unit_combo.currentIndexChanged.connect(self._on_unit_changed)\n        unit_row.addWidget(self._unit_combo)\n        unit_row.addStretch(1)\n        layout.addLayout(unit_row)\n\n        self._canvas = _DependencyGanttCanvas(self)\n        self._canvas.on_bar_clicked = self._on_bar_clicked\n        self._canvas.set_time_unit(self._block.time_unit)\n        layout.addWidget(self._canvas)\n\n        self._populate_table_combo()\n\n        self._timer = QTimer(self)\n        self._timer.setInterval(_REFRESH_INTERVAL_MS)\n        self._timer.timeout.connect(self.refresh)\n        self._timer.start()\n        self.refresh()\n\n    @property\n    def block(self) -> DependencyGanttBlock:\n        return self._block\n\n    # -- Sélection de la source -----------------------------------------\n\n    def _table_blocks(self) -> list[TableBlock]:\n        return [b for b in self._document.blocks if isinstance(b, TableBlock)]\n\n    def _populate_table_combo(self) -> None:\n        self._syncing = True\n        combo = self._combos["table"]\n        combo.clear()\n        combo.addItem("(aucun)", None)\n        for table in self._table_blocks():\n            title = f"Tableau ({table.columns[0][\'name\']}...)" if table.columns else "Tableau"\n            combo.addItem(title, table.id)\n        index = combo.findData(self._block.table_block_id)\n        combo.setCurrentIndex(index if index >= 0 else 0)\n        self._syncing = False\n        self._populate_column_combos()\n\n    def _populate_column_combos(self) -> None:\n        self._syncing = True\n        table = find_source_table(self._document, self._block)\n        specs = (\n            ("label", available_label_columns, self._block.label_column_id),\n            ("person", available_person_columns, self._block.person_column_id),\n            ("duration", available_duration_columns, self._block.duration_column_id),\n            ("risk", available_risk_columns, self._block.risk_column_id),\n            ("dependency", available_dependency_columns, self._block.dependency_column_id),\n            ("delta", available_delta_columns, self._block.delta_column_id),\n        )\n        for key, getter, current_id in specs:\n            combo = self._combos[key]\n            combo.clear()\n            combo.addItem("(aucune)", None)\n            if table is not None:\n                for column in getter(table):\n                    combo.addItem(column["name"] or "(sans nom)", column["id"])\n            index = combo.findData(current_id)\n            combo.setCurrentIndex(index if index >= 0 else 0)\n        self._syncing = False\n\n    def _on_source_changed(self) -> None:\n        if self._syncing:\n            return\n        if self.sender() is self._combos["table"]:\n            self._block.set_source(self._combos["table"].currentData())\n            self._populate_column_combos()\n        else:\n            self._block.set_source(\n                self._block.table_block_id,\n                self._combos["label"].currentData(),\n                self._combos["person"].currentData(),\n                self._combos["duration"].currentData(),\n                self._combos["risk"].currentData(),\n                self._combos["dependency"].currentData(),\n                self._combos["delta"].currentData(),\n            )\n        self.refresh()\n\n    def _on_unit_changed(self) -> None:\n        if self._syncing:\n            return\n        self._block.time_unit = self._unit_combo.currentData()\n        self._canvas.set_time_unit(self._block.time_unit)\n        self.refresh()\n\n    # -- Édition de l\'écart via pop-up (PATCH 49) ------------------------\n\n    def _on_bar_clicked(self, task: dict) -> None:\n        dialog = _DeltaDialog(task["label"], task["delta"], self._block.time_unit, parent=self)\n        if dialog.exec() != QDialog.Accepted:\n            return\n        value_days = dialog.value_in_days()\n\n        table = find_source_table(self._document, self._block)\n        delta_column_id = self._block.delta_column_id\n        if table is not None and delta_column_id is not None:\n            table.set_cell(task["row_id"], delta_column_id, str(value_days))\n        else:\n            # Aucune colonne "Ecarts" configurée : repli sur l\'ancien\n            # stockage propre au bloc (voir DependencyGanttBlock.set_delta).\n            self._block.set_delta(task["row_id"], value_days)\n        self.refresh()\n\n    # -- Rafraîchissement -------------------------------------------------\n\n    def refresh(self) -> None:\n        self._canvas.set_schedule(compute_schedule(self._document, self._block))\n'
_SOURCES['ui.blocks.formula_block_widget'] = '"""\nWidget graphique du bloc "Résultat calculé" (PATCH 45).\n\nMême principe que GanttBlockWidget : aucune donnée propre conservée\ncôté widget, relecture périodique du TableBlock référencé.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtCore import QTimer\nfrom PySide6.QtWidgets import QComboBox, QHBoxLayout, QLabel, QLineEdit, QVBoxLayout, QWidget\n\nfrom blocks.formula_block import (\n    FormulaBlock,\n    available_boolean_columns,\n    available_number_columns,\n    compute_formula_result,\n    find_source_table,\n    format_formula_text,\n)\nfrom blocks.table_block import TableBlock\n\n_REFRESH_INTERVAL_MS = 500\n\n\nclass FormulaBlockWidget(QWidget):\n    """Widget d\'un FormulaBlock : sélecteurs de source + résultat affiché."""\n\n    def __init__(self, block: FormulaBlock, document, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n        self._document = document\n        self._syncing = False\n\n        layout = QVBoxLayout(self)\n        layout.setContentsMargins(0, 0, 0, 0)\n\n        selectors = QHBoxLayout()\n        selectors.addWidget(QLabel("Libellé :", self))\n        self._label_edit = QLineEdit(block.label, self)\n        self._label_edit.textChanged.connect(self._on_label_changed)\n        selectors.addWidget(self._label_edit, 1)\n\n        selectors.addWidget(QLabel("Tableau :", self))\n        self._table_combo = QComboBox(self)\n        self._table_combo.currentIndexChanged.connect(self._on_table_changed)\n        selectors.addWidget(self._table_combo, 1)\n\n        selectors.addWidget(QLabel("Points :", self))\n        self._number_combo = QComboBox(self)\n        self._number_combo.currentIndexChanged.connect(self._on_number_column_changed)\n        selectors.addWidget(self._number_combo, 1)\n\n        selectors.addWidget(QLabel("État :", self))\n        self._boolean_combo = QComboBox(self)\n        self._boolean_combo.currentIndexChanged.connect(self._on_boolean_column_changed)\n        selectors.addWidget(self._boolean_combo, 1)\n        layout.addLayout(selectors)\n\n        self._result_label = QLabel(self)\n        font = self._result_label.font()\n        font.setBold(True)\n        self._result_label.setFont(font)\n        layout.addWidget(self._result_label)\n\n        self._populate_table_combo()\n\n        self._timer = QTimer(self)\n        self._timer.setInterval(_REFRESH_INTERVAL_MS)\n        self._timer.timeout.connect(self.refresh)\n        self._timer.start()\n        self.refresh()\n\n    @property\n    def block(self) -> FormulaBlock:\n        return self._block\n\n    # -- Sélection de la source -----------------------------------------\n\n    def _table_blocks(self) -> list[TableBlock]:\n        return [b for b in self._document.blocks if isinstance(b, TableBlock)]\n\n    def _populate_table_combo(self) -> None:\n        self._syncing = True\n        self._table_combo.clear()\n        self._table_combo.addItem("(aucun)", None)\n        for table in self._table_blocks():\n            title = f"Tableau ({table.columns[0][\'name\']}...)" if table.columns else "Tableau"\n            self._table_combo.addItem(title, table.id)\n        index = self._table_combo.findData(self._block.table_block_id)\n        self._table_combo.setCurrentIndex(index if index >= 0 else 0)\n        self._syncing = False\n        self._populate_column_combos()\n\n    def _populate_column_combos(self) -> None:\n        self._syncing = True\n        self._number_combo.clear()\n        self._boolean_combo.clear()\n\n        table = find_source_table(self._document, self._block)\n        if table is not None:\n            for column in available_number_columns(table):\n                self._number_combo.addItem(column["name"] or "(sans nom)", column["id"])\n            for column in available_boolean_columns(table):\n                self._boolean_combo.addItem(column["name"] or "(sans nom)", column["id"])\n\n        number_index = self._number_combo.findData(self._block.number_column_id)\n        self._number_combo.setCurrentIndex(number_index if number_index >= 0 else 0)\n        boolean_index = self._boolean_combo.findData(self._block.boolean_column_id)\n        self._boolean_combo.setCurrentIndex(boolean_index if boolean_index >= 0 else 0)\n        self._syncing = False\n\n    def _on_table_changed(self) -> None:\n        if self._syncing:\n            return\n        self._block.set_source(self._table_combo.currentData(), None, None)\n        self._populate_column_combos()\n        self.refresh()\n\n    def _on_number_column_changed(self) -> None:\n        if self._syncing:\n            return\n        self._block.set_source(\n            self._block.table_block_id, self._number_combo.currentData(), self._block.boolean_column_id\n        )\n        self.refresh()\n\n    def _on_boolean_column_changed(self) -> None:\n        if self._syncing:\n            return\n        self._block.set_source(\n            self._block.table_block_id, self._block.number_column_id, self._boolean_combo.currentData()\n        )\n        self.refresh()\n\n    def _on_label_changed(self, text: str) -> None:\n        self._block.label = text\n        self.refresh()\n\n    # -- Rafraîchissement -------------------------------------------------\n\n    def refresh(self) -> None:\n        result = compute_formula_result(self._document, self._block)\n        self._result_label.setText(format_formula_text(self._block, result))\n'
_SOURCES['ui.blocks.gantt_block_widget'] = '"""\nWidget graphique du bloc Gantt (PATCH 19).\n\nLe widget ne conserve aucune copie des données du tableau : à chaque\nrafraîchissement (changement de sélection, ou minuterie périodique),\nil appelle `compute_gantt_rows` qui relit directement le TableBlock\nréférencé dans le document. Toute modification du tableau (cellule,\najout/suppression de ligne...) apparaît donc automatiquement, sans\naction de synchronisation explicite.\n"""\nfrom __future__ import annotations\n\nfrom datetime import date\n\nfrom PySide6.QtCore import QTimer, Qt\nfrom PySide6.QtGui import QPainter, QColor\nfrom PySide6.QtWidgets import QComboBox, QHBoxLayout, QLabel, QVBoxLayout, QWidget\n\nfrom blocks.gantt_block import (\n    GanttBlock,\n    available_date_columns,\n    compute_gantt_rows,\n    find_source_table,\n)\nfrom blocks.table_block import TableBlock\n\n_REFRESH_INTERVAL_MS = 500\n_ROW_HEIGHT = 28\n_BAR_COLOR = QColor("#4db6ac")\n\n\ndef _parse_iso(value: str | None) -> date | None:\n    if not value:\n        return None\n    try:\n        return date.fromisoformat(value)\n    except ValueError:\n        return None\n\n\nclass _GanttCanvas(QWidget):\n    """Zone de dessin : une ligne par tâche, une barre proportionnelle aux dates."""\n\n    def __init__(self, parent=None) -> None:\n        super().__init__(parent)\n        self._rows: list[dict] = []\n        self.setMinimumHeight(_ROW_HEIGHT)\n\n    def set_rows(self, rows: list[dict]) -> None:\n        self._rows = rows\n        self.setMinimumHeight(max(_ROW_HEIGHT, _ROW_HEIGHT * len(rows)))\n        self.update()\n\n    def paintEvent(self, event) -> None:  # noqa: N802 (nom imposé par Qt)\n        painter = QPainter(self)\n        painter.setRenderHint(QPainter.Antialiasing)\n\n        if not self._rows:\n            painter.drawText(self.rect(), Qt.AlignCenter, "Aucune donnée à afficher.")\n            painter.end()\n            return\n\n        dated = [\n            (r, _parse_iso(r["start"]), _parse_iso(r["end"]))\n            for r in self._rows\n        ]\n        valid_dates = [d for _, s, e in dated for d in (s, e) if d is not None]\n        min_date = min(valid_dates) if valid_dates else None\n        max_date = max(valid_dates) if valid_dates else None\n        span_days = max((max_date - min_date).days, 1) if min_date and max_date else 1\n\n        label_width = 140\n        chart_width = max(self.width() - label_width - 10, 20)\n\n        for i, (row, start, end) in enumerate(dated):\n            y = i * _ROW_HEIGHT\n            painter.drawText(0, y, label_width, _ROW_HEIGHT, Qt.AlignVCenter, row["label"] or "(sans titre)")\n\n            if start is None:\n                continue\n            end = end or start\n            x_start = label_width + int((start - min_date).days / span_days * chart_width)\n            x_end = label_width + int(max((end - min_date).days, 0) / span_days * chart_width) + 6\n            painter.fillRect(x_start, y + 4, max(x_end - x_start, 6), _ROW_HEIGHT - 8, _BAR_COLOR)\n\n        painter.end()\n\n\nclass GanttBlockWidget(QWidget):\n    """Widget d\'un GanttBlock : sélecteurs de source + zone de dessin."""\n\n    def __init__(self, block: GanttBlock, document, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n        self._document = document\n        self._syncing = False\n\n        layout = QVBoxLayout(self)\n        layout.setContentsMargins(0, 0, 0, 0)\n\n        selectors = QHBoxLayout()\n        selectors.addWidget(QLabel("Tableau :", self))\n        self._table_combo = QComboBox(self)\n        self._table_combo.currentIndexChanged.connect(self._on_table_changed)\n        selectors.addWidget(self._table_combo, 1)\n\n        selectors.addWidget(QLabel("Libellé :", self))\n        self._label_combo = QComboBox(self)\n        self._label_combo.currentIndexChanged.connect(self._on_label_column_changed)\n        selectors.addWidget(self._label_combo, 1)\n\n        selectors.addWidget(QLabel("Dates :", self))\n        self._date_combo = QComboBox(self)\n        self._date_combo.currentIndexChanged.connect(self._on_date_column_changed)\n        selectors.addWidget(self._date_combo, 1)\n        layout.addLayout(selectors)\n\n        self._canvas = _GanttCanvas(self)\n        layout.addWidget(self._canvas)\n\n        self._populate_table_combo()\n\n        self._timer = QTimer(self)\n        self._timer.setInterval(_REFRESH_INTERVAL_MS)\n        self._timer.timeout.connect(self.refresh)\n        self._timer.start()\n        self.refresh()\n\n    @property\n    def block(self) -> GanttBlock:\n        return self._block\n\n    # -- Sélection de la source -----------------------------------------\n\n    def _table_blocks(self) -> list[TableBlock]:\n        return [b for b in self._document.blocks if isinstance(b, TableBlock)]\n\n    def _populate_table_combo(self) -> None:\n        self._syncing = True\n        self._table_combo.clear()\n        self._table_combo.addItem("(aucun)", None)\n        for table in self._table_blocks():\n            title = f"Tableau ({table.columns[0][\'name\']}...)" if table.columns else "Tableau"\n            self._table_combo.addItem(title, table.id)\n        index = self._table_combo.findData(self._block.table_block_id)\n        self._table_combo.setCurrentIndex(index if index >= 0 else 0)\n        self._syncing = False\n        self._populate_column_combos()\n\n    def _populate_column_combos(self) -> None:\n        self._syncing = True\n        self._label_combo.clear()\n        self._date_combo.clear()\n\n        table = find_source_table(self._document, self._block)\n        if table is not None:\n            for column in table.columns:\n                self._label_combo.addItem(column["name"] or "(sans nom)", column["id"])\n            for column in available_date_columns(table):\n                self._date_combo.addItem(column["name"] or "(sans nom)", column["id"])\n\n        label_index = self._label_combo.findData(self._block.label_column_id)\n        self._label_combo.setCurrentIndex(label_index if label_index >= 0 else 0)\n        date_index = self._date_combo.findData(self._block.date_column_id)\n        self._date_combo.setCurrentIndex(date_index if date_index >= 0 else 0)\n        self._syncing = False\n\n    def _on_table_changed(self) -> None:\n        if self._syncing:\n            return\n        self._block.set_source(self._table_combo.currentData(), None, None)\n        self._populate_column_combos()\n        self.refresh()\n\n    def _on_label_column_changed(self) -> None:\n        if self._syncing:\n            return\n        self._block.set_source(\n            self._block.table_block_id, self._label_combo.currentData(), self._block.date_column_id\n        )\n        self.refresh()\n\n    def _on_date_column_changed(self) -> None:\n        if self._syncing:\n            return\n        self._block.set_source(\n            self._block.table_block_id, self._block.label_column_id, self._date_combo.currentData()\n        )\n        self.refresh()\n\n    # -- Rafraîchissement -------------------------------------------------\n\n    def refresh(self) -> None:\n        """Relit le tableau source et redessine (PATCH 19 : aucune donnée\n        propre au Gantt, tout est recalculé à partir du document)."""\n        rows = compute_gantt_rows(self._document, self._block)\n        self._canvas.set_rows(rows)\n'
_SOURCES['ui.blocks.heading_block_widget'] = '"""\nWidget graphique des blocs Titre.\n\nUtilise QLineEdit : édition libre sur une seule ligne, avec une\npolice dont la taille dépend du niveau du titre (H1 > H2 > H3).\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtGui import QFont\nfrom PySide6.QtWidgets import QLineEdit\n\nfrom blocks.heading_block import HeadingBlock\n\n# Taille de police par niveau de titre.\n_FONT_SIZES = {1: 28, 2: 22, 3: 18}\n\n\nclass HeadingBlockWidget(QLineEdit):\n    """Représentation graphique éditable d\'un HeadingBlock."""\n\n    def __init__(self, block: HeadingBlock, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n\n        self.setText(block.content)\n        self.setPlaceholderText(f"Titre {block.level}")\n        self.setFrame(False)\n\n        font = QFont()\n        font.setPointSize(_FONT_SIZES.get(block.level, 16))\n        font.setBold(True)\n        self.setFont(font)\n\n        self.textChanged.connect(self._on_text_changed)\n\n    @property\n    def block(self) -> HeadingBlock:\n        return self._block\n\n    def _on_text_changed(self, text: str) -> None:\n        """Synchronise le contenu du widget vers le bloc de données."""\n        self._block.content = text\n'
_SOURCES['ui.blocks.image_block_widget'] = '"""\nWidget graphique du bloc Image.\n\nAffiche l\'image décodée depuis le base64 du bloc, permet de la\nredimensionner (largeur ; hauteur recalculée au ratio d\'origine),\nde la déplacer dans le document (haut/bas) et de la supprimer.\n"""\nfrom __future__ import annotations\n\nimport base64\nfrom typing import Callable, Optional\n\nfrom PySide6.QtCore import Qt\nfrom PySide6.QtGui import QPixmap\nfrom PySide6.QtWidgets import (\n    QHBoxLayout,\n    QLabel,\n    QPushButton,\n    QSpinBox,\n    QToolButton,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom blocks.image_block import ImageBlock\n\n_MIN_WIDTH = 50\n_MAX_WIDTH = 2000\n\n\nclass ImageBlockWidget(QWidget):\n    """Représentation graphique éditable d\'un ImageBlock."""\n\n    def __init__(\n        self,\n        block: ImageBlock,\n        on_move_up: Optional[Callable[[], None]] = None,\n        on_move_down: Optional[Callable[[], None]] = None,\n        on_delete: Optional[Callable[[], None]] = None,\n        parent=None,\n    ) -> None:\n        super().__init__(parent)\n        self._block = block\n        self._on_move_up = on_move_up\n        self._on_move_down = on_move_down\n        self._on_delete = on_delete\n        self._source_pixmap = self._decode_pixmap(block)\n\n        outer = QVBoxLayout(self)\n        outer.setContentsMargins(0, 0, 0, 0)\n\n        self._image_label = QLabel(self)\n        self._image_label.setAlignment(Qt.AlignLeft)\n        outer.addWidget(self._image_label)\n\n        controls = QHBoxLayout()\n\n        controls.addWidget(QLabel("Largeur :", self))\n        self._width_spin = QSpinBox(self)\n        self._width_spin.setRange(_MIN_WIDTH, _MAX_WIDTH)\n        self._width_spin.setSingleStep(10)\n        self._width_spin.setValue(self._initial_width())\n        self._width_spin.valueChanged.connect(self._on_width_changed)\n        controls.addWidget(self._width_spin)\n\n        controls.addStretch(1)\n\n        up_button = QToolButton(self)\n        up_button.setText("↑")\n        up_button.setToolTip("Déplacer vers le haut")\n        up_button.clicked.connect(lambda: self._on_move_up() if self._on_move_up else None)\n        controls.addWidget(up_button)\n\n        down_button = QToolButton(self)\n        down_button.setText("↓")\n        down_button.setToolTip("Déplacer vers le bas")\n        down_button.clicked.connect(lambda: self._on_move_down() if self._on_move_down else None)\n        controls.addWidget(down_button)\n\n        delete_button = QPushButton("Supprimer", self)\n        delete_button.clicked.connect(lambda: self._on_delete() if self._on_delete else None)\n        controls.addWidget(delete_button)\n\n        outer.addLayout(controls)\n\n        # Applique la largeur initiale (native ou déjà enregistrée) à l\'affichage.\n        self._apply_width(self._width_spin.value())\n\n    @property\n    def block(self) -> ImageBlock:\n        return self._block\n\n    @staticmethod\n    def _decode_pixmap(block: ImageBlock) -> QPixmap:\n        pixmap = QPixmap()\n        if block.image_base64:\n            try:\n                raw_bytes = base64.b64decode(block.image_base64)\n            except (ValueError, TypeError):\n                return pixmap\n            pixmap.loadFromData(raw_bytes)\n        return pixmap\n\n    def _initial_width(self) -> int:\n        if self._block.width:\n            return max(_MIN_WIDTH, min(_MAX_WIDTH, self._block.width))\n        if not self._source_pixmap.isNull():\n            return max(_MIN_WIDTH, min(_MAX_WIDTH, self._source_pixmap.width()))\n        return _MIN_WIDTH\n\n    def _on_width_changed(self, value: int) -> None:\n        self._block.width = value\n        self._apply_width(value)\n\n    def _apply_width(self, width: int) -> None:\n        if self._source_pixmap.isNull():\n            self._image_label.setText("(image illisible)")\n            return\n        scaled = self._source_pixmap.scaledToWidth(width, Qt.SmoothTransformation)\n        self._image_label.setPixmap(scaled)\n'
_SOURCES['ui.blocks.line_chart_block_widget'] = '"""\nWidget graphique du bloc "Courbes" (PATCH 47, révisé PATCH 52).\n\nPATCH 52 :\n    - Titre et noms d\'axes éditables directement au clic (comme un\n      titre), sans préfixe "Titre :" / "Axe X :" — un champ vide\n      affiche un texte de substitution ("Titre", "Axe X", "Axe Y").\n    - Le graphique n\'est plus limité à un carré fixe : la hauteur\n      reste "carrée" (échelle de référence de la droite "idéal"),\n      mais la largeur s\'élargit pour que les droites de pentes\n      différentes se terminent à des abscisses différentes (voir\n      compute_line_series), formant un rectangle plutôt qu\'un carré.\n    - Les étiquettes de série sont placées à droite de la fin de\n      chaque droite (jamais au-dessus), avec un anti-chevauchement\n      simple qui les décale verticalement si elles se recouvrent.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtCore import QRect, QTimer, Qt\nfrom PySide6.QtGui import QColor, QPainter, QPen\nfrom PySide6.QtWidgets import (\n    QComboBox,\n    QDoubleSpinBox,\n    QGridLayout,\n    QHBoxLayout,\n    QLabel,\n    QLineEdit,\n    QPushButton,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom blocks.dependency_gantt_block import DependencyGanttBlock\nfrom blocks.line_chart_block import (\n    SLOPE_MODE_CONSTANT,\n    SLOPE_MODE_EFFICIENCY,\n    LineChartBlock,\n    compute_line_series,\n)\n\n_REFRESH_INTERVAL_MS = 500\n_MARGIN = 30\n_PLOT_HEIGHT = 220\n_LABEL_GUTTER = 140\n_LABEL_WIDTH = 130\n_LABEL_HEIGHT = 16\n\n_TITLE_STYLE = "QLineEdit { border: none; background: transparent; font-weight: bold; font-size: 15pt; }"\n_AXIS_STYLE = "QLineEdit { border: none; background: transparent; color: #666666; }"\n\n\nclass _LineChartCanvas(QWidget):\n    def __init__(self, parent=None) -> None:\n        super().__init__(parent)\n        self._series: list[dict] = []\n        self.setFixedSize(_PLOT_HEIGHT + 2 * _MARGIN, _PLOT_HEIGHT + 2 * _MARGIN)\n\n    def set_series(self, series: list[dict]) -> None:\n        self._series = series\n        y_scale = max((s["y1"] for s in series), default=1.0) or 1.0\n        max_x1 = max((s["x1"] for s in series), default=1.0) or 1.0\n        # PATCH 52 — largeur proportionnelle à l\'abscisse la plus lointaine\n        # (jamais moins que la hauteur, qui reste la référence "carrée").\n        plot_w = max(_PLOT_HEIGHT, _PLOT_HEIGHT * (max_x1 / y_scale))\n        width = int(_MARGIN * 2 + plot_w + _LABEL_GUTTER)\n        height = _PLOT_HEIGHT + 2 * _MARGIN\n        self.setFixedSize(width, height)\n        self.update()\n\n    def paintEvent(self, event) -> None:  # noqa: N802\n        painter = QPainter(self)\n        painter.setRenderHint(QPainter.Antialiasing)\n\n        h = self.height()\n        plot_w = self.width() - 2 * _MARGIN - _LABEL_GUTTER\n        plot_h = _PLOT_HEIGHT\n\n        y_scale = max((s["y1"] for s in self._series), default=1.0) or 1.0\n        max_x1 = max((s["x1"] for s in self._series), default=1.0) or 1.0\n\n        def to_px(x: float, y: float) -> tuple[int, int]:\n            px = _MARGIN + int(x / max_x1 * plot_w)\n            py = h - _MARGIN - int(y / y_scale * plot_h)\n            return px, py\n\n        # Axes.\n        painter.setPen(QPen(QColor("#888888"), 1))\n        painter.drawLine(_MARGIN, h - _MARGIN, _MARGIN + plot_w, h - _MARGIN)\n        painter.drawLine(_MARGIN, h - _MARGIN, _MARGIN, _MARGIN)\n\n        placed_label_rects: list[QRect] = []\n        for s in self._series:\n            pen = QPen(QColor(s["color"]), 2)\n            painter.setPen(pen)\n            x0, y0 = to_px(s["x0"], s["y0"])\n            x1, y1 = to_px(s["x1"], s["y1"])\n            painter.drawLine(x0, y0, x1, y1)\n            self._draw_label(painter, x1, y1, s["name"], QColor(s["color"]), placed_label_rects)\n\n        painter.end()\n\n    def _draw_label(\n        self, painter: QPainter, x1: int, y1: int, text: str, color: QColor, placed: list[QRect]\n    ) -> None:\n        """PATCH 52 — étiquette à droite de la fin de la droite (jamais\n        au-dessus ni tronquée), décalée verticalement si elle\n        chevaucherait une étiquette déjà placée."""\n        rect = QRect(x1 + 8, y1 - _LABEL_HEIGHT // 2, _LABEL_WIDTH, _LABEL_HEIGHT)\n        moved = True\n        while moved:\n            moved = False\n            for other in placed:\n                if rect.intersects(other):\n                    rect.moveTop(other.bottom() + 2)\n                    moved = True\n        placed.append(QRect(rect))\n        painter.setPen(QPen(color))\n        painter.drawText(rect, Qt.AlignLeft | Qt.AlignVCenter, text)\n\n\nclass _TitleLikeLineEdit(QLineEdit):\n    """Champ éditable façon "titre" (PATCH 52) : pas de préfixe visible,\n    texte de substitution quand vide, style discret sans bordure."""\n\n    def __init__(self, text: str, placeholder: str, style: str, parent=None) -> None:\n        super().__init__(text, parent)\n        self.setPlaceholderText(placeholder)\n        self.setFrame(False)\n        self.setStyleSheet(style)\n\n\nclass LineChartBlockWidget(QWidget):\n    """Widget d\'un LineChartBlock : titre, axes, échelle, séries éditables, courbes."""\n\n    def __init__(self, block: LineChartBlock, document, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n        self._document = document\n        self._syncing = False\n\n        layout = QVBoxLayout(self)\n        layout.setContentsMargins(0, 0, 0, 0)\n\n        header = QHBoxLayout()\n        self._title_edit = _TitleLikeLineEdit(block.title, "Titre", _TITLE_STYLE, self)\n        self._title_edit.textChanged.connect(self._on_title_changed)\n        header.addWidget(self._title_edit, 1)\n        header.addWidget(QLabel("Échelle :", self))\n        self._x_max_spin = QDoubleSpinBox(self)\n        self._x_max_spin.setRange(0.01, 100000)\n        self._x_max_spin.setValue(block.x_max)\n        self._x_max_spin.valueChanged.connect(self._on_x_max_changed)\n        header.addWidget(self._x_max_spin)\n        layout.addLayout(header)\n\n        self._y_axis_edit = _TitleLikeLineEdit(block.y_axis_label, "Axe Y", _AXIS_STYLE, self)\n        self._y_axis_edit.textChanged.connect(self._on_y_axis_changed)\n        layout.addWidget(self._y_axis_edit)\n\n        self._canvas = _LineChartCanvas(self)\n        layout.addWidget(self._canvas, 0, Qt.AlignLeft)\n\n        self._x_axis_edit = _TitleLikeLineEdit(block.x_axis_label, "Axe X", _AXIS_STYLE, self)\n        self._x_axis_edit.textChanged.connect(self._on_x_axis_changed)\n        layout.addWidget(self._x_axis_edit)\n\n        self._series_area = QGridLayout()\n        layout.addLayout(self._series_area)\n\n        add_button = QPushButton("+ Ajouter une droite", self)\n        add_button.clicked.connect(self._on_add_series)\n        layout.addWidget(add_button)\n\n        self._rebuild_series_rows()\n\n        self._timer = QTimer(self)\n        self._timer.setInterval(_REFRESH_INTERVAL_MS)\n        self._timer.timeout.connect(self.refresh)\n        self._timer.start()\n        self.refresh()\n\n    @property\n    def block(self) -> LineChartBlock:\n        return self._block\n\n    def _gantt_blocks(self) -> list[DependencyGanttBlock]:\n        return [b for b in self._document.blocks if isinstance(b, DependencyGanttBlock)]\n\n    def _rebuild_series_rows(self) -> None:\n        while self._series_area.count():\n            item = self._series_area.takeAt(0)\n            widget = item.widget()\n            if widget is not None:\n                widget.deleteLater()\n\n        self._syncing = True\n        for row_index, s in enumerate(self._block.series):\n            name_edit = QLineEdit(s["name"], self)\n            name_edit.textChanged.connect(lambda text, sid=s["id"]: self._on_series_name_changed(sid, text))\n            self._series_area.addWidget(name_edit, row_index, 0)\n\n            mode_combo = QComboBox(self)\n            mode_combo.addItem("Constante", SLOPE_MODE_CONSTANT)\n            mode_combo.addItem("Vélocité réelle (planning)", SLOPE_MODE_EFFICIENCY)\n            mode_combo.setCurrentIndex(0 if s["mode"] == SLOPE_MODE_CONSTANT else 1)\n            self._series_area.addWidget(mode_combo, row_index, 1)\n\n            slope_spin = QDoubleSpinBox(self)\n            slope_spin.setRange(-1000, 1000)\n            slope_spin.setSingleStep(0.1)\n            slope_spin.setValue(s["slope"])\n            slope_spin.setEnabled(s["mode"] == SLOPE_MODE_CONSTANT)\n            slope_spin.valueChanged.connect(lambda v, sid=s["id"]: self._on_series_slope_changed(sid, v))\n            self._series_area.addWidget(slope_spin, row_index, 2)\n\n            source_combo = QComboBox(self)\n            source_combo.addItem("(aucun planning)", None)\n            for gantt in self._gantt_blocks():\n                source_combo.addItem(f"Planning {gantt.id[:8]}", gantt.id)\n            source_index = source_combo.findData(s.get("source_block_id"))\n            source_combo.setCurrentIndex(source_index if source_index >= 0 else 0)\n            source_combo.setEnabled(s["mode"] == SLOPE_MODE_EFFICIENCY)\n            self._series_area.addWidget(source_combo, row_index, 3)\n\n            mode_combo.currentIndexChanged.connect(\n                lambda _, sid=s["id"], mc=mode_combo, sc=source_combo, ss=slope_spin: self._on_series_mode_changed(\n                    sid, mc, sc, ss\n                )\n            )\n            source_combo.currentIndexChanged.connect(\n                lambda _, sid=s["id"], mc=mode_combo, sc=source_combo: self._on_series_source_changed(sid, mc, sc)\n            )\n\n            remove_button = QPushButton("×", self)\n            remove_button.clicked.connect(lambda _, sid=s["id"]: self._on_remove_series(sid))\n            self._series_area.addWidget(remove_button, row_index, 4)\n        self._syncing = False\n\n    # -- Callbacks --------------------------------------------------------\n\n    def _on_title_changed(self, text: str) -> None:\n        self._block.title = text\n\n    def _on_x_axis_changed(self, text: str) -> None:\n        self._block.x_axis_label = text\n\n    def _on_y_axis_changed(self, text: str) -> None:\n        self._block.y_axis_label = text\n\n    def _on_x_max_changed(self, value: float) -> None:\n        self._block.x_max = value\n        self.refresh()\n\n    def _on_add_series(self) -> None:\n        self._block.add_series(name=f"Droite {len(self._block.series) + 1}")\n        self._rebuild_series_rows()\n        self.refresh()\n\n    def _on_remove_series(self, series_id: str) -> None:\n        self._block.remove_series(series_id)\n        self._rebuild_series_rows()\n        self.refresh()\n\n    def _on_series_name_changed(self, series_id: str, text: str) -> None:\n        if self._syncing:\n            return\n        self._block.set_series_name(series_id, text)\n        self.refresh()\n\n    def _on_series_slope_changed(self, series_id: str, value: float) -> None:\n        if self._syncing:\n            return\n        self._block.set_series_slope(series_id, value)\n        self.refresh()\n\n    def _on_series_mode_changed(self, series_id: str, mode_combo, source_combo, slope_spin) -> None:\n        if self._syncing:\n            return\n        mode = mode_combo.currentData()\n        slope_spin.setEnabled(mode == SLOPE_MODE_CONSTANT)\n        source_combo.setEnabled(mode == SLOPE_MODE_EFFICIENCY)\n        self._block.set_series_mode(series_id, mode, source_combo.currentData() if mode == SLOPE_MODE_EFFICIENCY else None)\n        self.refresh()\n\n    def _on_series_source_changed(self, series_id: str, mode_combo, source_combo) -> None:\n        if self._syncing:\n            return\n        if mode_combo.currentData() == SLOPE_MODE_EFFICIENCY:\n            self._block.set_series_mode(series_id, SLOPE_MODE_EFFICIENCY, source_combo.currentData())\n            self.refresh()\n\n    # -- Rafraîchissement -------------------------------------------------\n\n    def refresh(self) -> None:\n        self._canvas.set_series(compute_line_series(self._document, self._block))\n'
_SOURCES['ui.blocks.linked_checklist_block_widget'] = '"""\nWidget graphique du bloc "Checklists liées" (PATCH 44).\n\nDeux panneaux ("À faire" / "Faites") dans un QSplitter horizontal\n(séparateur ajustable, position mémorisée dans le bloc). Cocher un\nélément dans un panneau le déplace immédiatement dans l\'autre.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtCore import Qt\nfrom PySide6.QtWidgets import (\n    QCheckBox,\n    QHBoxLayout,\n    QLabel,\n    QLineEdit,\n    QPushButton,\n    QSplitter,\n    QToolButton,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom blocks.linked_checklist_block import LinkedChecklistBlock\n\n_SPLITTER_TOTAL = 1000\n\n\nclass _LinkedItemRow(QWidget):\n    """Une ligne : case à cocher + texte + suppression."""\n\n    def __init__(\n        self, item_id: str, text: str, checked: bool, owner: "LinkedChecklistBlockWidget"\n    ) -> None:\n        super().__init__(owner)\n        self._owner = owner\n        self.item_id = item_id\n\n        layout = QHBoxLayout(self)\n        layout.setContentsMargins(0, 0, 0, 0)\n\n        self.checkbox = QCheckBox(self)\n        self.checkbox.setChecked(checked)\n        self.checkbox.toggled.connect(self._on_toggled)\n        layout.addWidget(self.checkbox)\n\n        self.line_edit = QLineEdit(self)\n        self.line_edit.setText(text)\n        self.line_edit.setPlaceholderText("Élément...")\n        self.line_edit.textChanged.connect(self._on_text_changed)\n        self.line_edit.returnPressed.connect(self._on_return_pressed)\n        layout.addWidget(self.line_edit, 1)\n\n        remove_button = QToolButton(self)\n        remove_button.setText("×")\n        remove_button.setToolTip("Supprimer cet élément")\n        remove_button.clicked.connect(lambda: self._owner.remove_row(self))\n        layout.addWidget(remove_button)\n\n    def _on_toggled(self, checked: bool) -> None:\n        self._owner.on_item_checked_changed(self, checked)\n\n    def _on_text_changed(self, text: str) -> None:\n        self._owner.on_item_text_changed(self, text)\n\n    def _on_return_pressed(self) -> None:\n        """PATCH 49 — Entrée dans une ligne ajoute un nouvel élément\n        "à faire" (identique au bouton "+ Ajouter"), comme dans la\n        checklist simple."""\n        self._owner.insert_row_after(self)\n\n\nclass _ChecklistColumn(QWidget):\n    """Un panneau (gauche ou droite) : titre, lignes, bouton d\'ajout optionnel."""\n\n    def __init__(self, title: str, show_add_button: bool, owner: "LinkedChecklistBlockWidget") -> None:\n        super().__init__(owner)\n        self.layout_ = QVBoxLayout(self)\n        self.layout_.setContentsMargins(4, 0, 4, 0)\n        self.layout_.addWidget(QLabel(f"<b>{title}</b>", self))\n        self.rows: list[_LinkedItemRow] = []\n        self.add_button: QPushButton | None = None\n        if show_add_button:\n            self.add_button = QPushButton("+ Ajouter", self)\n            self.add_button.clicked.connect(owner._on_add_clicked)\n            self.layout_.addWidget(self.add_button)\n\n    def add_row(self, row: _LinkedItemRow) -> None:\n        # Insérée juste avant le bouton d\'ajout s\'il existe, sinon en fin.\n        index = len(self.rows) + 1\n        self.layout_.insertWidget(index, row)\n        self.rows.append(row)\n\n    def clear_rows(self) -> None:\n        for row in self.rows:\n            self.layout_.removeWidget(row)\n            row.deleteLater()\n        self.rows = []\n\n\nclass LinkedChecklistBlockWidget(QWidget):\n    """Représentation graphique éditable d\'un LinkedChecklistBlock."""\n\n    def __init__(self, block: LinkedChecklistBlock, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n\n        outer = QVBoxLayout(self)\n        outer.setContentsMargins(0, 0, 0, 0)\n\n        self._splitter = QSplitter(Qt.Horizontal, self)\n        self._splitter.setChildrenCollapsible(False)\n        self._splitter.splitterMoved.connect(self._on_splitter_moved)\n\n        self._todo_column = _ChecklistColumn("À faire", show_add_button=True, owner=self)\n        self._done_column = _ChecklistColumn("Faites", show_add_button=False, owner=self)\n        self._splitter.addWidget(self._todo_column)\n        self._splitter.addWidget(self._done_column)\n\n        outer.addWidget(self._splitter)\n\n        self._rebuild()\n        left = int(_SPLITTER_TOTAL * self._block.split)\n        self._splitter.setSizes([left, _SPLITTER_TOTAL - left])\n\n    @property\n    def block(self) -> LinkedChecklistBlock:\n        return self._block\n\n    def _rebuild(self, focus_item_id: str | None = None) -> None:\n        self._todo_column.clear_rows()\n        self._done_column.clear_rows()\n        focus_row: _LinkedItemRow | None = None\n        for item in self._block.items:\n            column = self._done_column if item.get("checked") else self._todo_column\n            row = _LinkedItemRow(item["id"], item.get("text", ""), item.get("checked", False), self)\n            column.add_row(row)\n            if focus_item_id is not None and item["id"] == focus_item_id:\n                focus_row = row\n        if focus_row is not None:\n            focus_row.line_edit.setFocus()\n\n    def _on_add_clicked(self) -> None:\n        item = self._block.add_item()\n        self._rebuild(focus_item_id=item["id"])\n\n    def insert_row_after(self, row: _LinkedItemRow) -> None:\n        """PATCH 49 — Ajoute un nouvel élément "à faire" suite à un appui\n        sur Entrée dans une ligne existante (comme le bouton "+ Ajouter"),\n        quel que soit le panneau où Entrée a été pressée."""\n        item = self._block.add_item()\n        self._rebuild(focus_item_id=item["id"])\n\n    def remove_row(self, row: _LinkedItemRow) -> None:\n        self._block.remove_item(row.item_id)\n        self._rebuild()\n\n    def on_item_text_changed(self, row: _LinkedItemRow, text: str) -> None:\n        self._block.set_item_text(row.item_id, text)\n\n    def on_item_checked_changed(self, row: _LinkedItemRow, checked: bool) -> None:\n        """Coche/décoche puis reconstruit : l\'élément change de panneau."""\n        self._block.set_item_checked(row.item_id, checked)\n        self._rebuild(focus_item_id=row.item_id)\n\n    def _on_splitter_moved(self, pos: int, index: int) -> None:\n        sizes = self._splitter.sizes()\n        total = sum(sizes) or 1\n        self._block.split = sizes[0] / total\n'
_SOURCES['ui.blocks.list_block_widget'] = '"""\nWidget graphique du bloc Liste (PATCH 23).\n\nUne ligne par élément : puce ou numéro (recalculé automatiquement\nselon la position) + champ de texte éditable + bouton de suppression.\nUn sélecteur permet de basculer entre liste à puces et numérotée.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtWidgets import (\n    QComboBox,\n    QHBoxLayout,\n    QLabel,\n    QLineEdit,\n    QPushButton,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom blocks.list_block import LIST_TYPE_BULLET, LIST_TYPE_NUMBERED, ListBlock\n\n_TYPE_LABELS = {LIST_TYPE_BULLET: "À puces", LIST_TYPE_NUMBERED: "Numérotée"}\n\n\nclass ListBlockWidget(QWidget):\n    """Représentation graphique éditable d\'un ListBlock."""\n\n    def __init__(self, block: ListBlock, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n        self._syncing = False\n\n        layout = QVBoxLayout(self)\n        layout.setContentsMargins(0, 0, 0, 0)\n\n        header = QHBoxLayout()\n        header.addWidget(QLabel("Style :", self))\n        self._type_combo = QComboBox(self)\n        for list_type, label in _TYPE_LABELS.items():\n            self._type_combo.addItem(label, list_type)\n        self._type_combo.currentIndexChanged.connect(self._on_type_changed)\n        header.addWidget(self._type_combo)\n        header.addStretch(1)\n        layout.addLayout(header)\n\n        self._items_layout = QVBoxLayout()\n        layout.addLayout(self._items_layout)\n\n        add_button = QPushButton("+ Élément", self)\n        add_button.clicked.connect(self._on_add_item)\n        layout.addWidget(add_button)\n\n        self._rebuild()\n\n    @property\n    def block(self) -> ListBlock:\n        return self._block\n\n    def _rebuild(self) -> None:\n        self._syncing = True\n        index = self._type_combo.findData(self._block.list_type)\n        self._type_combo.setCurrentIndex(index if index >= 0 else 0)\n        self._syncing = False\n\n        while self._items_layout.count():\n            taken = self._items_layout.takeAt(0)\n            if taken.widget():\n                taken.widget().deleteLater()\n\n        for position, item in enumerate(self._block.items):\n            self._items_layout.addWidget(self._build_row(item, position))\n\n    def _build_row(self, item: dict, position: int) -> QWidget:\n        row = QWidget(self)\n        row_layout = QHBoxLayout(row)\n        row_layout.setContentsMargins(0, 0, 0, 0)\n\n        marker_text = "•" if self._block.list_type == LIST_TYPE_BULLET else f"{position + 1}."\n        marker = QLabel(marker_text, row)\n        marker.setFixedWidth(24)\n        row_layout.addWidget(marker)\n\n        line_edit = QLineEdit(item.get("text", ""), row)\n        line_edit.textChanged.connect(lambda text, item_id=item["id"]: self._on_item_text_changed(item_id, text))\n        row_layout.addWidget(line_edit, 1)\n\n        remove_btn = QPushButton("×", row)\n        remove_btn.setFixedWidth(24)\n        remove_btn.clicked.connect(lambda _, item_id=item["id"]: self._on_remove_item(item_id))\n        row_layout.addWidget(remove_btn)\n\n        return row\n\n    # -- Événements ------------------------------------------------------\n\n    def _on_type_changed(self) -> None:\n        if self._syncing:\n            return\n        self._block.set_list_type(self._type_combo.currentData())\n        self._rebuild()\n\n    def _on_add_item(self) -> None:\n        self._block.add_item("")\n        self._rebuild()\n\n    def _on_remove_item(self, item_id: str) -> None:\n        self._block.remove_item(item_id)\n        self._rebuild()\n\n    def _on_item_text_changed(self, item_id: str, text: str) -> None:\n        self._block.set_item_text(item_id, text)\n'
_SOURCES['ui.blocks.quote_block_widget'] = '"""\nWidget graphique du bloc Citation (PATCH 21).\n\nQTextEdit en texte brut, avec une mise en forme dédiée (barre\nverticale à gauche, italique, gris) pour se distinguer visuellement\nd\'un TextBlock ordinaire.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtGui import QFont, QPalette\nfrom PySide6.QtWidgets import QTextEdit\n\nfrom blocks.quote_block import QuoteBlock\n\n\nclass QuoteBlockWidget(QTextEdit):\n    """Représentation graphique éditable d\'un QuoteBlock."""\n\n    def __init__(self, block: QuoteBlock, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n\n        self.setAcceptRichText(False)\n        self.setPlainText(block.content)\n        self.setPlaceholderText("Citation...")\n        self.setFrameStyle(0)\n\n        font = QFont()\n        font.setItalic(True)\n        self.setFont(font)\n        # Barre verticale dérivée de la palette courante (claire ou sombre,\n        # PATCH 32) plutôt qu\'une couleur fixe, pour rester lisible dans\n        # les deux thèmes.\n        border_color = self.palette().color(QPalette.Mid).name()\n        self.setStyleSheet(f"QTextEdit {{ border-left: 3px solid {border_color}; padding-left: 10px; }}")\n\n        self.textChanged.connect(self._on_text_changed)\n\n    @property\n    def block(self) -> QuoteBlock:\n        return self._block\n\n    def _on_text_changed(self) -> None:\n        self._block.content = self.toPlainText()\n'
_SOURCES['ui.blocks.separator_block_widget'] = '"""\nWidget graphique du bloc Séparateur (PATCH 20).\n\nSimple ligne horizontale, sans état ni interaction : reflète fidèlement\nle fait que SeparatorBlock ne porte aucune donnée éditable.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtWidgets import QFrame, QVBoxLayout, QWidget\n\nfrom blocks.separator_block import SeparatorBlock\n\n\nclass SeparatorBlockWidget(QWidget):\n    """Représentation graphique d\'un SeparatorBlock : une ligne horizontale."""\n\n    def __init__(self, block: SeparatorBlock, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n\n        layout = QVBoxLayout(self)\n        layout.setContentsMargins(0, 10, 0, 10)\n\n        line = QFrame(self)\n        line.setFrameShape(QFrame.HLine)\n        line.setFrameShadow(QFrame.Sunken)\n        layout.addWidget(line)\n\n    @property\n    def block(self) -> SeparatorBlock:\n        return self._block\n'
_SOURCES['ui.blocks.simple_table_block_widget'] = '"""\nWidget graphique du bloc Tableau simple (PATCH 24).\n\nQTableWidget minimal : cellules de texte brut uniquement, sans\ncolonnes typées ni options (voir SimpleTableBlock). Volontairement\nplus léger que TableBlockWidget (PATCH 14/15).\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtWidgets import (\n    QHBoxLayout,\n    QPushButton,\n    QTableWidget,\n    QTableWidgetItem,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom blocks.simple_table_block import SimpleTableBlock\n\n\nclass SimpleTableBlockWidget(QWidget):\n    """Représentation graphique éditable d\'un SimpleTableBlock."""\n\n    def __init__(self, block: SimpleTableBlock, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n        self._syncing = False\n\n        layout = QVBoxLayout(self)\n        layout.setContentsMargins(0, 0, 0, 0)\n\n        self._table = QTableWidget(self)\n        self._table.horizontalHeader().setVisible(False)\n        self._table.verticalHeader().setVisible(False)\n        self._table.itemChanged.connect(self._on_item_changed)\n        layout.addWidget(self._table)\n\n        buttons = QHBoxLayout()\n        for label, handler in (\n            ("+ Ligne", self._on_add_row),\n            ("+ Colonne", self._on_add_column),\n            ("- Ligne", self._on_delete_row),\n            ("- Colonne", self._on_delete_column),\n        ):\n            btn = QPushButton(label, self)\n            btn.clicked.connect(handler)\n            buttons.addWidget(btn)\n        buttons.addStretch(1)\n        layout.addLayout(buttons)\n\n        self._rebuild()\n\n    @property\n    def block(self) -> SimpleTableBlock:\n        return self._block\n\n    def _rebuild(self) -> None:\n        self._syncing = True\n        self._table.setRowCount(self._block.row_count)\n        self._table.setColumnCount(self._block.column_count)\n        for row_index, row in enumerate(self._block.rows):\n            for col_index, text in enumerate(row):\n                self._table.setItem(row_index, col_index, QTableWidgetItem(text))\n        self._syncing = False\n\n    def _on_item_changed(self, item: QTableWidgetItem) -> None:\n        if self._syncing:\n            return\n        self._block.set_cell(item.row(), item.column(), item.text())\n\n    def _on_add_row(self) -> None:\n        self._block.add_row()\n        self._rebuild()\n\n    def _on_add_column(self) -> None:\n        self._block.add_column()\n        self._rebuild()\n\n    def _on_delete_row(self) -> None:\n        current = self._table.currentRow()\n        if current >= 0:\n            self._block.remove_row(current)\n            self._rebuild()\n\n    def _on_delete_column(self) -> None:\n        current = self._table.currentColumn()\n        if current >= 0:\n            self._block.remove_column(current)\n            self._rebuild()\n'
_SOURCES['ui.blocks.table_block_widget'] = '"""\nWidget graphique du bloc Tableau (PATCH 14) + colonnes typées (PATCH 15).\n\nAffiche les colonnes/lignes du TableBlock dans un QTableWidget. Le\nwidget de cellule dépend du type de la colonne (texte libre, case à\ncocher, sélecteur de date, choix, ...). Toute édition est répercutée\ndans le bloc via les id (colonne/ligne), jamais via la position.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtCore import QDate, Qt\nfrom PySide6.QtWidgets import (\n    QAbstractScrollArea,\n    QCheckBox,\n    QComboBox,\n    QDateEdit,\n    QHBoxLayout,\n    QLabel,\n    QMenu,\n    QPushButton,\n    QSizePolicy,\n    QSpinBox,\n    QTableWidget,\n    QTableWidgetItem,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom blocks.table_block import (\n    COLUMN_TYPE_BOOLEAN,\n    COLUMN_TYPE_CHECKLIST,\n    COLUMN_TYPE_DATE,\n    COLUMN_TYPE_DURATION,\n    COLUMN_TYPE_LABELS,\n    COLUMN_TYPE_MULTI_SELECT,\n    COLUMN_TYPE_NUMBER,\n    COLUMN_TYPE_PERSON,\n    COLUMN_TYPE_SELECT,\n    COLUMN_TYPE_TEXT,\n    DURATION_UNITS,\n    TableBlock,\n)\nfrom core.duration import format_duration\nfrom ui.blocks.table_cell_dialogs import (\n    ask_column_definition,\n    edit_checklist_cell,\n    edit_multi_select,\n    edit_person_list,\n)\n\n\nclass TableBlockWidget(QWidget):\n    """Représentation graphique éditable d\'un TableBlock."""\n\n    def __init__(self, block: TableBlock, document, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n        self._document = document\n        self._syncing = False\n\n        layout = QVBoxLayout(self)\n        layout.setContentsMargins(0, 0, 0, 0)\n\n        self._table = QTableWidget(self)\n        self._table.itemChanged.connect(self._on_item_changed)\n        self._table.horizontalHeader().sectionDoubleClicked.connect(\n            self._on_header_double_clicked\n        )\n        # PATCH 49 — évite que le tableau soit comprimé dans une hauteur\n        # par défaut trop petite (avec sa propre scrollbar interne) :\n        # sa hauteur s\'ajuste au nombre de lignes (voir _adjust_table_height).\n        self._table.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)\n        self._table.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)\n        self._table.setSizeAdjustPolicy(QAbstractScrollArea.AdjustToContents)\n        self._table.setContextMenuPolicy(Qt.CustomContextMenu)\n        self._table.customContextMenuRequested.connect(self._on_cell_context_menu)\n        layout.addWidget(self._table)\n\n        buttons = QHBoxLayout()\n        add_row_btn = QPushButton("+ Ligne", self)\n        add_row_btn.clicked.connect(self._on_add_row)\n        buttons.addWidget(add_row_btn)\n\n        add_col_btn = QPushButton("+ Colonne", self)\n        add_col_btn.clicked.connect(self._on_add_column)\n        buttons.addWidget(add_col_btn)\n\n        del_row_btn = QPushButton("- Ligne", self)\n        del_row_btn.clicked.connect(self._on_delete_row)\n        buttons.addWidget(del_row_btn)\n\n        del_col_btn = QPushButton("- Colonne", self)\n        del_col_btn.clicked.connect(self._on_delete_column)\n        buttons.addWidget(del_col_btn)\n        buttons.addStretch(1)\n        layout.addLayout(buttons)\n\n        self._rebuild()\n\n    @property\n    def block(self) -> TableBlock:\n        return self._block\n\n    # -- Rendu -------------------------------------------------------\n\n    def _rebuild(self) -> None:\n        """Reconstruit entièrement la grille à partir du bloc."""\n        self._syncing = True\n        columns = self._block.columns\n        rows = self._block.rows\n\n        self._table.setColumnCount(len(columns))\n        self._table.setRowCount(len(rows))\n        self._table.setHorizontalHeaderLabels(\n            [\n                f"{column.get(\'name\') or f\'Colonne {i + 1}\'} "\n                f"({COLUMN_TYPE_LABELS[column[\'type\']]}"\n                f"{\' — début/fin\' if column.get(\'range\') else \'\'})"\n                for i, column in enumerate(columns)\n            ]\n        )\n\n        for row_index, row in enumerate(rows):\n            for col_index, column in enumerate(columns):\n                self._set_cell_display(row_index, col_index, row, column)\n\n        self._apply_merged_cells(columns, rows)\n        self._adjust_table_height()\n        self._syncing = False\n\n    def _apply_merged_cells(self, columns: list[dict], rows: list[dict]) -> None:\n        """PATCH 49 — fusionne visuellement les cellules consécutives d\'une\n        même colonne "Texte" qui ont la valeur identique (ex : plusieurs\n        lignes "Phase 1" à la suite), pour éviter la répétition inutile.\n        PATCH 51 — une colonne avec des groupes de fusion manuelle\n        (clic droit → "Fusionner...") utilise ces groupes à la place de\n        la détection automatique, quel que soit son type. Ne modifie\n        jamais les données du bloc, uniquement l\'affichage (setSpan) ;\n        refait à chaque _rebuild, donc une nouvelle ligne à la valeur\n        identique d\'un groupe déjà fusionné y est automatiquement\n        rattachée.\n        """\n        self._table.clearSpans()\n        row_index_by_id = {row["id"]: index for index, row in enumerate(rows)}\n        for col_index, column in enumerate(columns):\n            manual_groups = self._block.manual_merge_groups(column["id"])\n            if manual_groups:\n                for group in manual_groups:\n                    indices = sorted(\n                        row_index_by_id[row_id] for row_id in group if row_id in row_index_by_id\n                    )\n                    if len(indices) < 2:\n                        continue\n                    # Une fusion manuelle ne s\'applique que si les lignes\n                    # sont toujours contiguës dans l\'ordre actuel du\n                    # tableau (sinon, repli silencieux : pas de fusion).\n                    if indices == list(range(indices[0], indices[0] + len(indices))):\n                        self._table.setSpan(indices[0], col_index, len(indices), 1)\n                continue\n\n            if column["type"] != COLUMN_TYPE_TEXT:\n                continue\n            run_start = 0\n            while run_start < len(rows):\n                value = rows[run_start]["cells"].get(column["id"])\n                run_end = run_start + 1\n                while run_end < len(rows) and rows[run_end]["cells"].get(column["id"]) == value and value:\n                    run_end += 1\n                run_length = run_end - run_start\n                if run_length > 1:\n                    self._table.setSpan(run_start, col_index, run_length, 1)\n                run_start = run_end\n\n    def _on_cell_context_menu(self, pos) -> None:\n        """PATCH 51 — clic droit sur une cellule : fusion manuelle avec la\n        ligne au-dessus / en-dessous, ou annulation de la fusion."""\n        row_index = self._table.rowAt(pos.y())\n        col_index = self._table.columnAt(pos.x())\n        if row_index < 0 or col_index < 0:\n            return\n        columns = self._block.columns\n        rows = self._block.rows\n        if col_index >= len(columns) or row_index >= len(rows):\n            return\n        column = columns[col_index]\n        row_id = rows[row_index]["id"]\n        currently_merged = any(row_id in group for group in self._block.manual_merge_groups(column["id"]))\n\n        menu = QMenu(self)\n        merge_up_action = None\n        merge_down_action = None\n        if row_index > 0:\n            merge_up_action = menu.addAction("Fusionner avec la ligne au-dessus")\n        if row_index < len(rows) - 1:\n            merge_down_action = menu.addAction("Fusionner avec la ligne en dessous")\n        unmerge_action = menu.addAction("Annuler la fusion") if currently_merged else None\n        if merge_up_action is None and merge_down_action is None and unmerge_action is None:\n            return\n\n        chosen = menu.exec(self._table.viewport().mapToGlobal(pos))\n        if chosen is None:\n            return\n        if chosen is merge_up_action:\n            self._block.merge_cells(column["id"], [rows[row_index - 1]["id"], row_id])\n        elif chosen is merge_down_action:\n            self._block.merge_cells(column["id"], [row_id, rows[row_index + 1]["id"]])\n        elif chosen is unmerge_action:\n            self._block.unmerge_cell(column["id"], row_id)\n        self._rebuild()\n\n    def _adjust_table_height(self) -> None:\n        """PATCH 49 — dimensionne le tableau à son contenu réel (au lieu de\n        la hauteur par défaut de QTableWidget, qui le fait paraître\n        comprimé avec une scrollbar interne)."""\n        self._table.resizeRowsToContents()\n        header_height = self._table.horizontalHeader().height()\n        rows_height = sum(self._table.rowHeight(i) for i in range(self._table.rowCount()))\n        frame = 2 * self._table.frameWidth()\n        total_height = header_height + rows_height + frame + 4\n        self._table.setMinimumHeight(max(total_height, header_height + 40))\n        self._table.setMaximumHeight(max(total_height, header_height + 40))\n\n    def _set_cell_display(self, row_index: int, col_index: int, row: dict, column: dict) -> None:\n        """Place le widget/item adapté au type de `column` dans la grille."""\n        col_type = column["type"]\n        value = row["cells"].get(column["id"])\n\n        if col_type == COLUMN_TYPE_TEXT:\n            self._table.setCellWidget(row_index, col_index, None)\n            self._table.setItem(row_index, col_index, QTableWidgetItem(str(value or "")))\n            return\n\n        if col_type == COLUMN_TYPE_NUMBER:\n            self._table.setCellWidget(row_index, col_index, None)\n            self._table.setItem(row_index, col_index, QTableWidgetItem(str(value or "")))\n            return\n\n        self._table.setItem(row_index, col_index, QTableWidgetItem(""))\n\n        if col_type == COLUMN_TYPE_BOOLEAN:\n            self._table.setCellWidget(row_index, col_index, self._build_boolean_cell(row, column, value))\n        elif col_type == COLUMN_TYPE_DATE:\n            self._table.setCellWidget(row_index, col_index, self._build_date_cell(row, column, value))\n        elif col_type == COLUMN_TYPE_DURATION:\n            self._table.setCellWidget(row_index, col_index, self._build_duration_cell(row, column, value))\n        elif col_type == COLUMN_TYPE_SELECT:\n            self._table.setCellWidget(row_index, col_index, self._build_select_cell(row, column, value))\n        elif col_type == COLUMN_TYPE_PERSON:\n            self._table.setCellWidget(row_index, col_index, self._build_person_cell(row, column, value))\n        elif col_type == COLUMN_TYPE_MULTI_SELECT:\n            self._table.setCellWidget(row_index, col_index, self._build_multi_select_cell(row, column, value))\n        elif col_type == COLUMN_TYPE_CHECKLIST:\n            self._table.setCellWidget(row_index, col_index, self._build_checklist_cell(row, column, value))\n\n    def _refresh_cell(self, row_id: str, column_id: str) -> None:\n        """Redessine une seule cellule après une modification (sans tout reconstruire)."""\n        row_index = next((i for i, r in enumerate(self._block.rows) if r["id"] == row_id), None)\n        col_index = next((i for i, c in enumerate(self._block.columns) if c["id"] == column_id), None)\n        if row_index is None or col_index is None:\n            return\n        row = self._block.rows[row_index]\n        column = self._block.columns[col_index]\n        self._syncing = True\n        self._set_cell_display(row_index, col_index, row, column)\n        self._syncing = False\n\n    # -- Widgets de cellule par type -----------------------------------\n\n    def _build_boolean_cell(self, row: dict, column: dict, value) -> QWidget:\n        container = QWidget(self._table)\n        cell_layout = QHBoxLayout(container)\n        cell_layout.setContentsMargins(0, 0, 0, 0)\n        cell_layout.setAlignment(Qt.AlignCenter)\n        checkbox = QCheckBox(container)\n        checkbox.setChecked(bool(value))\n        checkbox.toggled.connect(lambda checked: self._block.set_cell(row["id"], column["id"], checked))\n        cell_layout.addWidget(checkbox)\n        return container\n\n    def _build_date_cell(self, row: dict, column: dict, value) -> QWidget:\n        if column.get("range"):\n            return self._build_date_range_cell(row, column, value)\n\n        date_edit = QDateEdit(self._table)\n        date_edit.setCalendarPopup(True)\n        date_edit.setDisplayFormat("yyyy-MM-dd")\n        date_edit.setSpecialValueText(" ")\n        qdate = QDate.fromString(value, "yyyy-MM-dd") if value else QDate()\n        date_edit.setMinimumDate(QDate(1900, 1, 1))\n        date_edit.setDate(qdate if qdate.isValid() else date_edit.minimumDate())\n\n        def _on_changed(new_date: QDate) -> None:\n            self._block.set_cell(row["id"], column["id"], new_date.toString("yyyy-MM-dd"))\n\n        date_edit.dateChanged.connect(_on_changed)\n        return date_edit\n\n    def _build_date_range_cell(self, row: dict, column: dict, value) -> QWidget:\n        """PATCH 18 — Cellule "Date" en mode plage : deux sélecteurs (début / fin)."""\n        value = value or {"start": "", "end": ""}\n        container = QWidget(self._table)\n        cell_layout = QHBoxLayout(container)\n        cell_layout.setContentsMargins(0, 0, 0, 0)\n\n        def _make_edit(field: str) -> QDateEdit:\n            edit = QDateEdit(container)\n            edit.setCalendarPopup(True)\n            edit.setDisplayFormat("yyyy-MM-dd")\n            edit.setMinimumDate(QDate(1900, 1, 1))\n            qdate = QDate.fromString(value.get(field, ""), "yyyy-MM-dd")\n            edit.setDate(qdate if qdate.isValid() else edit.minimumDate())\n            return edit\n\n        start_edit = _make_edit("start")\n        end_edit = _make_edit("end")\n        cell_layout.addWidget(QLabel("Du", container))\n        cell_layout.addWidget(start_edit)\n        cell_layout.addWidget(QLabel("au", container))\n        cell_layout.addWidget(end_edit)\n\n        def _push() -> None:\n            self._block.set_cell(\n                row["id"],\n                column["id"],\n                {\n                    "start": start_edit.date().toString("yyyy-MM-dd"),\n                    "end": end_edit.date().toString("yyyy-MM-dd"),\n                },\n            )\n\n        start_edit.dateChanged.connect(_push)\n        end_edit.dateChanged.connect(_push)\n        return container\n\n    def _build_duration_cell(self, row: dict, column: dict, value) -> QWidget:\n        value = value or {"amount": 0, "unit": DURATION_UNITS[1]}\n        container = QWidget(self._table)\n        cell_layout = QHBoxLayout(container)\n        cell_layout.setContentsMargins(0, 0, 0, 0)\n\n        amount_spin = QSpinBox(container)\n        amount_spin.setRange(0, 9999)\n        amount_spin.setValue(int(value.get("amount", 0)))\n        cell_layout.addWidget(amount_spin)\n\n        unit_combo = QComboBox(container)\n        unit_combo.addItems(DURATION_UNITS)\n        unit_combo.setCurrentText(value.get("unit", DURATION_UNITS[1]))\n        cell_layout.addWidget(unit_combo)\n\n        preview_label = QLabel(format_duration(value), container)\n        preview_label.setStyleSheet("color: gray;")\n        cell_layout.addWidget(preview_label, 1)\n\n        def _push() -> None:\n            new_value = {"amount": amount_spin.value(), "unit": unit_combo.currentText()}\n            self._block.set_cell(row["id"], column["id"], new_value)\n            preview_label.setText(format_duration(new_value))\n\n        amount_spin.valueChanged.connect(_push)\n        unit_combo.currentTextChanged.connect(_push)\n        return container\n\n    def _build_select_cell(self, row: dict, column: dict, value) -> QWidget:\n        combo = QComboBox(self._table)\n        combo.addItem("")\n        combo.addItems(column.get("options", []))\n        combo.setCurrentText(value or "")\n        combo.currentTextChanged.connect(lambda text: self._block.set_cell(row["id"], column["id"], text))\n        return combo\n\n    def _build_person_cell(self, row: dict, column: dict, value) -> QWidget:\n        person_ids = value or []\n        names = [\n            (self._document.find_person(pid) or {}).get("name", "?") for pid in person_ids\n        ]\n        container = QWidget(self._table)\n        cell_layout = QHBoxLayout(container)\n        cell_layout.setContentsMargins(0, 0, 0, 0)\n        label = QLabel(", ".join(names), container)\n        cell_layout.addWidget(label, 1)\n        edit_btn = QPushButton("...", container)\n        edit_btn.setFixedWidth(28)\n\n        def _on_click() -> None:\n            current = list(self._block.get_cell(row["id"], column["id"]) or [])\n            result = edit_person_list(self, self._document, current)\n            if result is not None:\n                self._block.set_cell(row["id"], column["id"], result)\n                self._refresh_cell(row["id"], column["id"])\n\n        edit_btn.clicked.connect(_on_click)\n        cell_layout.addWidget(edit_btn)\n        return container\n\n    def _build_multi_select_cell(self, row: dict, column: dict, value) -> QWidget:\n        selected = value or []\n        container = QWidget(self._table)\n        cell_layout = QHBoxLayout(container)\n        cell_layout.setContentsMargins(0, 0, 0, 0)\n        label = QLabel(", ".join(selected), container)\n        cell_layout.addWidget(label, 1)\n        edit_btn = QPushButton("...", container)\n        edit_btn.setFixedWidth(28)\n\n        def _on_click() -> None:\n            current = (self._block.get_cell(row["id"], column["id"]) or [])\n            result = edit_multi_select(self, column.get("options", []), list(current))\n            if result is not None:\n                self._block.set_cell(row["id"], column["id"], result)\n                self._refresh_cell(row["id"], column["id"])\n\n        edit_btn.clicked.connect(_on_click)\n        cell_layout.addWidget(edit_btn)\n        return container\n\n    def _build_checklist_cell(self, row: dict, column: dict, value) -> QWidget:\n        items = value or []\n        done = sum(1 for item in items if item.get("checked"))\n        container = QWidget(self._table)\n        cell_layout = QHBoxLayout(container)\n        cell_layout.setContentsMargins(0, 0, 0, 0)\n        label = QLabel(f"{done}/{len(items)}", container)\n        cell_layout.addWidget(label, 1)\n        edit_btn = QPushButton("...", container)\n        edit_btn.setFixedWidth(28)\n\n        def _on_click() -> None:\n            current = (self._block.get_cell(row["id"], column["id"]) or [])\n            result = edit_checklist_cell(self, list(current))\n            if result is not None:\n                self._block.set_cell(row["id"], column["id"], result)\n                self._refresh_cell(row["id"], column["id"])\n\n        edit_btn.clicked.connect(_on_click)\n        cell_layout.addWidget(edit_btn)\n        return container\n\n    # -- Colonnes ------------------------------------------------------\n\n    def _on_add_column(self) -> None:\n        result = ask_column_definition(self, name=f"Colonne {len(self._block.columns) + 1}")\n        if result is None:\n            return\n        name, col_type, options, date_range = result\n        self._block.add_column(name=name, col_type=col_type, options=options, date_range=date_range)\n        self._rebuild()\n\n    def _on_delete_column(self) -> None:\n        current_col = self._table.currentColumn()\n        if current_col < 0 or current_col >= len(self._block.columns):\n            return\n        column_id = self._block.columns[current_col]["id"]\n        self._block.remove_column(column_id)\n        self._rebuild()\n\n    def _on_header_double_clicked(self, section: int) -> None:\n        if section < 0 or section >= len(self._block.columns):\n            return\n        column = self._block.columns[section]\n        result = ask_column_definition(\n            self,\n            name=column.get("name", ""),\n            col_type=column["type"],\n            options=column.get("options", []),\n            date_range=column.get("range", False),\n        )\n        if result is None:\n            return\n        name, col_type, options, date_range = result\n        self._block.rename_column(column["id"], name)\n        if col_type == column["type"]:\n            self._block.set_column_options(column["id"], options)\n            if col_type == "date":\n                self._block.set_column_date_range(column["id"], date_range)\n        self._rebuild()\n\n    # -- Lignes --------------------------------------------------------\n\n    def _on_add_row(self) -> None:\n        self._block.add_row()\n        self._rebuild()\n\n    def _on_delete_row(self) -> None:\n        current_row = self._table.currentRow()\n        if current_row < 0 or current_row >= len(self._block.rows):\n            return\n        row_id = self._block.rows[current_row]["id"]\n        self._block.remove_row(row_id)\n        self._rebuild()\n\n    # -- Édition de cellule texte/nombre ----------------------------------\n\n    def _on_item_changed(self, item: QTableWidgetItem) -> None:\n        if self._syncing:\n            return\n        row_index, col_index = item.row(), item.column()\n        if row_index >= len(self._block.rows) or col_index >= len(self._block.columns):\n            return\n        row_id = self._block.rows[row_index]["id"]\n        column_id = self._block.columns[col_index]["id"]\n        self._block.set_cell(row_id, column_id, item.text())\n'
_SOURCES['ui.blocks.table_cell_dialogs'] = '"""\nBoîtes de dialogue d\'édition pour les types de cellules avancés du\nbloc Tableau (PATCH 15) : Personne, Liste multiple, Checklist, et\nchoix du type/nom/options à la création d\'une colonne.\n\nIsolées ici pour garder `table_block_widget.py` centré sur la grille.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtCore import Qt\nfrom PySide6.QtGui import QColor\nfrom PySide6.QtWidgets import (\n    QCheckBox,\n    QComboBox,\n    QDialog,\n    QDialogButtonBox,\n    QHBoxLayout,\n    QLabel,\n    QLineEdit,\n    QListWidget,\n    QListWidgetItem,\n    QPushButton,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom blocks.table_block import (\n    COLUMN_TYPE_DATE,\n    COLUMN_TYPE_LABELS,\n    COLUMN_TYPE_SELECT,\n    COLUMN_TYPE_MULTI_SELECT,\n    COLUMN_TYPES,\n)\n\n\ndef ask_column_definition(\n    parent,\n    name: str = "",\n    col_type: str = "text",\n    options: list[str] | None = None,\n    date_range: bool = False,\n) -> tuple[str, str, list[str], bool] | None:\n    """Dialogue de création/édition de colonne : nom, type, options, plage.\n\n    Retourne (name, col_type, options, date_range) ou None si annulé.\n    """\n    dialog = QDialog(parent)\n    dialog.setWindowTitle("Colonne")\n    layout = QVBoxLayout(dialog)\n\n    layout.addWidget(QLabel("Nom :"))\n    name_edit = QLineEdit(name, dialog)\n    layout.addWidget(name_edit)\n\n    layout.addWidget(QLabel("Type :"))\n    type_combo = QComboBox(dialog)\n    for type_key in COLUMN_TYPES:\n        type_combo.addItem(COLUMN_TYPE_LABELS[type_key], type_key)\n    type_combo.setCurrentIndex(max(0, COLUMN_TYPES.index(col_type) if col_type in COLUMN_TYPES else 0))\n    layout.addWidget(type_combo)\n\n    options_label = QLabel("Choix possibles (séparés par des virgules) :")\n    options_edit = QLineEdit(", ".join(options or []), dialog)\n    layout.addWidget(options_label)\n    layout.addWidget(options_edit)\n\n    range_checkbox = QCheckBox("Plage de dates (début / fin)", dialog)\n    range_checkbox.setChecked(date_range)\n    layout.addWidget(range_checkbox)\n\n    def _sync_visibility() -> None:\n        current_type = type_combo.currentData()\n        is_choice_type = current_type in (COLUMN_TYPE_SELECT, COLUMN_TYPE_MULTI_SELECT)\n        options_label.setVisible(is_choice_type)\n        options_edit.setVisible(is_choice_type)\n        range_checkbox.setVisible(current_type == COLUMN_TYPE_DATE)\n\n    type_combo.currentIndexChanged.connect(_sync_visibility)\n    _sync_visibility()\n\n    buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel, dialog)\n    buttons.accepted.connect(dialog.accept)\n    buttons.rejected.connect(dialog.reject)\n    layout.addWidget(buttons)\n\n    if dialog.exec() != QDialog.Accepted:\n        return None\n\n    parsed_options = [part.strip() for part in options_edit.text().split(",") if part.strip()]\n    return name_edit.text(), type_combo.currentData(), parsed_options, range_checkbox.isChecked()\n\n\ndef edit_person_list(parent, document, selected_ids: list[str]) -> list[str] | None:\n    """Dialogue d\'édition d\'une cellule "Personne" (PATCH 16).\n\n    Coche les personnes du registre partagé de `document` à assigner à\n    cette cellule. Permet aussi de créer une nouvelle personne à la\n    volée (elle rejoint alors le registre partagé, réutilisable dans\n    toutes les autres cellules "Personne" du document).\n    """\n    dialog = QDialog(parent)\n    dialog.setWindowTitle("Personnes assignées")\n    layout = QVBoxLayout(dialog)\n\n    list_widget = QListWidget(dialog)\n\n    def _populate() -> None:\n        list_widget.clear()\n        for person in document.people:\n            item = QListWidgetItem(person["name"])\n            item.setData(Qt.UserRole, person["id"])\n            item.setFlags(item.flags() | Qt.ItemIsUserCheckable)\n            item.setCheckState(Qt.Checked if person["id"] in selected_ids else Qt.Unchecked)\n            item.setForeground(QColor(person.get("color", "#000000")))\n            list_widget.addItem(item)\n\n    _populate()\n    layout.addWidget(list_widget)\n\n    add_row = QHBoxLayout()\n    name_edit = QLineEdit(dialog)\n    name_edit.setPlaceholderText("Nouvelle personne...")\n    add_row.addWidget(name_edit)\n\n    def _add_person() -> None:\n        text = name_edit.text().strip()\n        if not text:\n            return\n        person = document.add_person(text)\n        selected_ids.append(person["id"])\n        name_edit.clear()\n        _populate()\n\n    add_button = QPushButton("Ajouter", dialog)\n    add_button.clicked.connect(_add_person)\n    name_edit.returnPressed.connect(_add_person)\n    add_row.addWidget(add_button)\n    layout.addLayout(add_row)\n\n    buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel, dialog)\n    buttons.accepted.connect(dialog.accept)\n    buttons.rejected.connect(dialog.reject)\n    layout.addWidget(buttons)\n\n    if dialog.exec() != QDialog.Accepted:\n        return None\n    return [\n        list_widget.item(i).data(Qt.UserRole)\n        for i in range(list_widget.count())\n        if list_widget.item(i).checkState() == Qt.Checked\n    ]\n\n\ndef edit_multi_select(parent, options: list[str], selected: list[str]) -> list[str] | None:\n    """Dialogue de sélection multiple parmi les choix de la colonne."""\n    dialog = QDialog(parent)\n    dialog.setWindowTitle("Choix multiples")\n    layout = QVBoxLayout(dialog)\n\n    if not options:\n        layout.addWidget(QLabel("Aucun choix défini pour cette colonne."))\n\n    checkboxes: list[QCheckBox] = []\n    for option in options:\n        checkbox = QCheckBox(option, dialog)\n        checkbox.setChecked(option in selected)\n        layout.addWidget(checkbox)\n        checkboxes.append(checkbox)\n\n    buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel, dialog)\n    buttons.accepted.connect(dialog.accept)\n    buttons.rejected.connect(dialog.reject)\n    layout.addWidget(buttons)\n\n    if dialog.exec() != QDialog.Accepted:\n        return None\n    return [checkbox.text() for checkbox in checkboxes if checkbox.isChecked()]\n\n\ndef edit_checklist_cell(parent, items: list[dict]) -> list[dict] | None:\n    """Dialogue d\'édition d\'une mini-checklist stockée dans une cellule."""\n    import uuid\n\n    dialog = QDialog(parent)\n    dialog.setWindowTitle("Checklist")\n    layout = QVBoxLayout(dialog)\n\n    rows_container = QVBoxLayout()\n    layout.addLayout(rows_container)\n\n    working_items = [dict(item) for item in items]\n    row_widgets: list[tuple[QWidget, QCheckBox, QLineEdit]] = []\n\n    def _rebuild_rows() -> None:\n        while rows_container.count():\n            item = rows_container.takeAt(0)\n            if item.widget():\n                item.widget().deleteLater()\n        row_widgets.clear()\n        for entry in working_items:\n            row_widget = QWidget(dialog)\n            row_layout = QHBoxLayout(row_widget)\n            row_layout.setContentsMargins(0, 0, 0, 0)\n            checkbox = QCheckBox(row_widget)\n            checkbox.setChecked(entry.get("checked", False))\n            line_edit = QLineEdit(entry.get("text", ""), row_widget)\n            remove_btn = QPushButton("×", row_widget)\n            remove_btn.setFixedWidth(24)\n            row_layout.addWidget(checkbox)\n            row_layout.addWidget(line_edit, 1)\n            row_layout.addWidget(remove_btn)\n            rows_container.addWidget(row_widget)\n            row_widgets.append((row_widget, checkbox, line_edit))\n            remove_btn.clicked.connect(lambda _, e=entry: (working_items.remove(e), _rebuild_rows()))\n\n    _rebuild_rows()\n\n    add_button = QPushButton("+ Ajouter un élément", dialog)\n\n    def _add_item() -> None:\n        working_items.append({"id": str(uuid.uuid4()), "text": "", "checked": False})\n        _rebuild_rows()\n\n    add_button.clicked.connect(_add_item)\n    layout.addWidget(add_button)\n\n    buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel, dialog)\n    buttons.accepted.connect(dialog.accept)\n    buttons.rejected.connect(dialog.reject)\n    layout.addWidget(buttons)\n\n    if dialog.exec() != QDialog.Accepted:\n        return None\n\n    result = []\n    for entry, (_, checkbox, line_edit) in zip(working_items, row_widgets):\n        result.append({"id": entry["id"], "text": line_edit.text(), "checked": checkbox.isChecked()})\n    return result\n'
_SOURCES['ui.blocks.text_block_widget'] = '"""\nWidget graphique du bloc Texte.\n\nUtilise QTextEdit qui fournit nativement : édition libre, retour\nà la ligne, sélection, copier/coller (Ctrl+C / Ctrl+V / clic droit).\n\nLe contenu est conservé au format HTML dans le bloc de données afin\nde préserver toute la mise en forme (PATCH 6) : gras, italique,\nsouligné, barré, couleurs, alignement, listes, citations, code.\n"""\nfrom __future__ import annotations\n\nimport html as html_module\n\nfrom PySide6.QtCore import Qt, Signal\nfrom PySide6.QtGui import (\n    QColor,\n    QFont,\n    QTextCharFormat,\n    QTextCursor,\n    QTextListFormat,\n)\nfrom PySide6.QtWidgets import QTextEdit\n\nfrom blocks.text_block import TextBlock\nfrom core.emoji_data import resolve_trailing_shortcode\n\n_CODE_FONT_FAMILY = "Consolas"\n_QUOTE_INDENT = 24\n# PATCH 30 — Schéma d\'URL privé pour les liens internes (vers un autre bloc).\n_INTERNAL_LINK_SCHEME = "block://"\n\n\nclass TextBlockWidget(QTextEdit):\n    """Représentation graphique éditable d\'un TextBlock."""\n\n    focused = Signal(object)\n    # Entrée pressée : (self, texte_avant_curseur, texte_apres_curseur).\n    # MainWindow doit couper le bloc en deux (PATCH 7 - séparation).\n    split_requested = Signal(object, str, str)\n    # Retour arrière en début de bloc non vide : fusionner avec le\n    # bloc précédent (PATCH 7 - fusion).\n    merge_requested = Signal(object)\n    # Retour arrière sur un bloc vide : simplement le supprimer\n    # (PATCH 7 - suppression).\n    delete_requested = Signal(object)\n    # "/" tapé seul dans un bloc vide : ouvrir le menu de commandes\n    # (PATCH 25).\n    command_requested = Signal(object)\n    # PATCH 30 — Ctrl+Clic sur un lien interne : (id du bloc visé).\n    link_activated = Signal(str)\n\n    def __init__(self, block: TextBlock, parent=None) -> None:\n        super().__init__(parent)\n        self._block = block\n        self._applying_shortcode = False\n\n        self.setAcceptRichText(False)\n        # PATCH 27 : un seul historique Undo/Redo applicatif (MainWindow) ;\n        # l\'undo natif de QTextEdit interférerait sinon avec Ctrl+Z/Ctrl+Y.\n        self.setUndoRedoEnabled(False)\n        if block.html:\n            self.setHtml(block.html)\n        else:\n            self.setPlainText(block.content)\n        self.setPlaceholderText("Tapez du texte...")\n        self.setFrameStyle(0)\n        # PATCH 30 — Nécessaire pour changer le curseur au survol d\'un lien.\n        self.setMouseTracking(True)\n\n        self.textChanged.connect(self._on_text_changed)\n\n    @property\n    def block(self) -> TextBlock:\n        return self._block\n\n    def focusInEvent(self, event) -> None:\n        super().focusInEvent(event)\n        self.focused.emit(self)\n\n    def keyPressEvent(self, event) -> None:\n        """Intercepte Entrée et Retour arrière pour l\'expérience multi-blocs.\n\n        - Maj+Entrée : sépare le bloc en deux (Entrée seule garde le\n          comportement natif de retour à la ligne dans le même bloc).\n        - Retour arrière en tout début de bloc : fusionne avec le\n          bloc précédent (ou le supprime s\'il est vide).\n        """\n        is_split_enter = event.key() in (Qt.Key_Return, Qt.Key_Enter) and (\n            event.modifiers() & Qt.ShiftModifier\n        )\n        if is_split_enter:\n            cursor = self.textCursor()\n            full_text = self.toPlainText()\n            pos = cursor.position()\n            self.split_requested.emit(self, full_text[:pos], full_text[pos:])\n            event.accept()\n            return\n\n        is_backspace_at_start = (\n            event.key() == Qt.Key_Backspace\n            and not self.textCursor().hasSelection()\n            and self.textCursor().position() == 0\n        )\n        if is_backspace_at_start:\n            if self.toPlainText() == "":\n                self.delete_requested.emit(self)\n            else:\n                self.merge_requested.emit(self)\n            event.accept()\n            return\n\n        super().keyPressEvent(event)\n\n    def mouseMoveEvent(self, event) -> None:\n        """PATCH 30 — Curseur en forme de main au survol d\'un lien interne."""\n        anchor = self.anchorAt(event.pos())\n        self.viewport().setCursor(\n            Qt.PointingHandCursor if anchor.startswith(_INTERNAL_LINK_SCHEME) else Qt.IBeamCursor\n        )\n        super().mouseMoveEvent(event)\n\n    def mouseReleaseEvent(self, event) -> None:\n        """PATCH 30 — Ctrl+Clic sur un lien interne : navigue vers le bloc visé.\n\n        Le Ctrl évite qu\'un simple clic (pour positionner le curseur\n        d\'édition) ne déclenche accidentellement une navigation.\n        """\n        anchor = self.anchorAt(event.pos())\n        if (\n            event.button() == Qt.LeftButton\n            and event.modifiers() & Qt.ControlModifier\n            and anchor.startswith(_INTERNAL_LINK_SCHEME)\n        ):\n            self.link_activated.emit(anchor[len(_INTERNAL_LINK_SCHEME) :])\n            return\n        super().mouseReleaseEvent(event)\n\n    def insert_internal_link(self, block_id: str, label: str) -> None:\n        """PATCH 30 — Insère un lien interne vers `block_id` au curseur."""\n        safe_label = html_module.escape(label) or "(bloc)"\n        cursor = self.textCursor()\n        cursor.insertHtml(f\'<a href="{_INTERNAL_LINK_SCHEME}{block_id}">{safe_label}</a> \')\n\n    def _on_text_changed(self) -> None:\n        """Synchronise le texte brut et le HTML vers le bloc de données."""\n        if self._applying_shortcode:\n            return\n        self._block.content = self.toPlainText()\n        self._block.html = self.toHtml()\n        if self.toPlainText() == "/":\n            self.command_requested.emit(self)\n            return\n        self._maybe_convert_shortcode()\n\n    def _maybe_convert_shortcode(self) -> None:\n        """PATCH 35 — Convertit automatiquement un ":shortcode:" tout juste\n        tapé en emoji (façon Slack/Discord), uniquement quand le curseur\n        est en fin de texte (évite les surprises en édition ailleurs)."""\n        if not self.textCursor().atEnd():\n            return\n        resolved = resolve_trailing_shortcode(self.toPlainText())\n        if resolved is None:\n            return\n        new_text, _emoji = resolved\n\n        self._applying_shortcode = True\n        self.setPlainText(new_text)\n        cursor = self.textCursor()\n        cursor.movePosition(QTextCursor.End)\n        self.setTextCursor(cursor)\n        self._applying_shortcode = False\n\n        self._block.content = self.toPlainText()\n        self._block.html = self.toHtml()\n\n    def insert_emoji(self, emoji: str) -> None:\n        """PATCH 35 — Insère un emoji au curseur (depuis le sélecteur)."""\n        self.textCursor().insertText(emoji)\n\n    # -- Mise en forme caractère ----------------------------------------\n\n    def _merge_char_format(self, fmt: QTextCharFormat) -> None:\n        """Applique un format à la sélection, ou au prochain texte tapé."""\n        self.mergeCurrentCharFormat(fmt)\n\n    def toggle_bold(self) -> None:\n        is_bold = self.currentCharFormat().fontWeight() == QFont.Bold\n        fmt = QTextCharFormat()\n        fmt.setFontWeight(QFont.Normal if is_bold else QFont.Bold)\n        self._merge_char_format(fmt)\n\n    def toggle_italic(self) -> None:\n        fmt = QTextCharFormat()\n        fmt.setFontItalic(not self.currentCharFormat().fontItalic())\n        self._merge_char_format(fmt)\n\n    def toggle_underline(self) -> None:\n        fmt = QTextCharFormat()\n        fmt.setFontUnderline(not self.currentCharFormat().fontUnderline())\n        self._merge_char_format(fmt)\n\n    def toggle_strikethrough(self) -> None:\n        fmt = QTextCharFormat()\n        fmt.setFontStrikeOut(not self.currentCharFormat().fontStrikeOut())\n        self._merge_char_format(fmt)\n\n    def toggle_code(self) -> None:\n        is_code = self.currentCharFormat().fontFamily() == _CODE_FONT_FAMILY\n        fmt = QTextCharFormat()\n        fmt.setFontFamily("" if is_code else _CODE_FONT_FAMILY)\n        self._merge_char_format(fmt)\n\n    def set_text_color(self, color: QColor) -> None:\n        fmt = QTextCharFormat()\n        fmt.setForeground(color)\n        self._merge_char_format(fmt)\n\n    def set_font_size(self, size: int) -> None:\n        fmt = QTextCharFormat()\n        fmt.setFontPointSize(size)\n        self._merge_char_format(fmt)\n\n    # -- Mise en forme paragraphe -----------------------------------------\n\n    def set_alignment(self, alignment: Qt.AlignmentFlag) -> None:\n        self.setAlignment(alignment)\n\n    def toggle_quote(self) -> None:\n        cursor = self.textCursor()\n        block_fmt = cursor.blockFormat()\n        is_quote = block_fmt.leftMargin() > 0\n        block_fmt.setLeftMargin(0 if is_quote else _QUOTE_INDENT)\n        cursor.mergeBlockFormat(block_fmt)\n\n        char_fmt = QTextCharFormat()\n        char_fmt.setFontItalic(not is_quote)\n        char_fmt.setForeground(QColor("black") if is_quote else QColor("#555555"))\n        self._merge_char_format(char_fmt)\n\n    def _toggle_list(self, style: QTextListFormat.Style) -> None:\n        cursor = self.textCursor()\n        current_list = cursor.currentList()\n        if current_list is not None and current_list.format().style() == style:\n            current_list.remove(cursor.block())\n            block_fmt = cursor.blockFormat()\n            block_fmt.setIndent(0)\n            cursor.mergeBlockFormat(block_fmt)\n        else:\n            list_fmt = QTextListFormat()\n            list_fmt.setStyle(style)\n            cursor.createList(list_fmt)\n\n    def toggle_bullet_list(self) -> None:\n        self._toggle_list(QTextListFormat.ListDisc)\n\n    def toggle_numbered_list(self) -> None:\n        self._toggle_list(QTextListFormat.ListDecimal)\n'
_SOURCES['ui.blocks_area'] = '"""\nZone de dépôt des blocs (PATCH 13), clic droit sur zone vide (PATCH 26).\n\nWidget central qui accepte le glisser-déposer initié par une\n``_DragHandle`` (voir ``block_container.py``) et calcule la position\nd\'insertion à partir de la coordonnée Y du curseur au relâchement.\nLe clic droit sur une zone vide (sous le dernier bloc) délègue à la\nfenêtre principale, qui propose d\'y ajouter un nouveau bloc.\n"""\nfrom __future__ import annotations\n\nfrom typing import Callable, Optional\n\nfrom PySide6.QtCore import QPoint\nfrom PySide6.QtGui import QContextMenuEvent, QDragEnterEvent, QDragMoveEvent, QDropEvent\nfrom PySide6.QtWidgets import QVBoxLayout, QWidget\n\nfrom ui.blocks.block_container import BLOCK_MIME_TYPE\n\n\nclass BlocksArea(QWidget):\n    """Conteneur vertical des blocs du document, cible du drag & drop."""\n\n    def __init__(\n        self,\n        on_block_dropped: Callable[[str, int], None],\n        on_empty_context_menu: Optional[Callable[[QPoint], None]] = None,\n        parent: QWidget | None = None,\n    ) -> None:\n        super().__init__(parent)\n        self.setAcceptDrops(True)\n        self.blocks_layout = QVBoxLayout(self)\n        self._on_block_dropped = on_block_dropped\n        self._on_empty_context_menu = on_empty_context_menu\n\n    def dragEnterEvent(self, event: QDragEnterEvent) -> None:\n        if event.mimeData().hasFormat(BLOCK_MIME_TYPE):\n            event.acceptProposedAction()\n\n    def dragMoveEvent(self, event: QDragMoveEvent) -> None:\n        if event.mimeData().hasFormat(BLOCK_MIME_TYPE):\n            event.acceptProposedAction()\n\n    def dropEvent(self, event: QDropEvent) -> None:\n        mime = event.mimeData()\n        if not mime.hasFormat(BLOCK_MIME_TYPE):\n            return\n        block_id = bytes(mime.data(BLOCK_MIME_TYPE)).decode("utf-8")\n        target_index = self._index_for_y(event.position().y())\n        event.acceptProposedAction()\n        self._on_block_dropped(block_id, target_index)\n\n    def contextMenuEvent(self, event: QContextMenuEvent) -> None:\n        """PATCH 26 — Clic droit sur une zone vide : propose d\'ajouter un bloc.\n\n        N\'est déclenché que si le clic n\'est tombé sur aucun bloc\n        (chaque BlockContainer intercepte déjà son propre clic droit).\n        """\n        if self._on_empty_context_menu is not None:\n            self._on_empty_context_menu(event.globalPos())\n            event.accept()\n\n    def _index_for_y(self, y: float) -> int:\n        """Index d\'insertion : juste avant le premier bloc dont le\n        milieu se trouve sous la position Y du dépôt."""\n        for i in range(self.blocks_layout.count()):\n            item = self.blocks_layout.itemAt(i)\n            widget = item.widget() if item else None\n            if widget is None:\n                continue\n            mid_y = widget.geometry().y() + widget.geometry().height() / 2\n            if y < mid_y:\n                return i\n        return self.blocks_layout.count()\n'
_SOURCES['ui.command_menu'] = '"""\nPopup du menu de commandes "/" (PATCH 25).\n\nFenêtre flottante sans bordure (Qt.Popup) listant les commandes\ndisponibles, filtrables en tapant après le "/". Se ferme sur\nsélection, Échap, ou perte de focus.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtCore import Qt, Signal\nfrom PySide6.QtWidgets import QLineEdit, QListWidget, QListWidgetItem, QVBoxLayout, QWidget\n\nfrom ui.command_registry import filter_commands\n\n\nclass CommandMenu(QWidget):\n    """Popup filtrable listant les commandes "/" (PATCH 25)."""\n\n    command_selected = Signal(str)  # émet l\'id de la commande choisie\n\n    def __init__(self, parent=None) -> None:\n        super().__init__(parent, Qt.Popup)\n        self.setAttribute(Qt.WA_DeleteOnClose)\n\n        layout = QVBoxLayout(self)\n        layout.setContentsMargins(4, 4, 4, 4)\n\n        self._search = QLineEdit(self)\n        self._search.setPlaceholderText("Rechercher une commande...")\n        self._search.textChanged.connect(self._on_search_changed)\n        self._search.returnPressed.connect(self._on_return_pressed)\n        layout.addWidget(self._search)\n\n        self._list = QListWidget(self)\n        self._list.itemClicked.connect(self._on_item_clicked)\n        layout.addWidget(self._list)\n\n        self.setFixedSize(220, 220)\n        self._populate("")\n        self._search.setFocus()\n\n    def _populate(self, query: str) -> None:\n        self._list.clear()\n        for command in filter_commands(query):\n            item = QListWidgetItem(f"/{command[\'label\']}")\n            item.setData(Qt.UserRole, command["id"])\n            self._list.addItem(item)\n        if self._list.count():\n            self._list.setCurrentRow(0)\n\n    def _on_search_changed(self, text: str) -> None:\n        self._populate(text)\n\n    def _on_item_clicked(self, item: QListWidgetItem) -> None:\n        self.command_selected.emit(item.data(Qt.UserRole))\n        self.close()\n\n    def _on_return_pressed(self) -> None:\n        item = self._list.currentItem()\n        if item is not None:\n            self.command_selected.emit(item.data(Qt.UserRole))\n        self.close()\n\n    def keyPressEvent(self, event) -> None:  # noqa: N802\n        if event.key() == Qt.Key_Escape:\n            self.close()\n            return\n        if event.key() in (Qt.Key_Down, Qt.Key_Up):\n            row = self._list.currentRow()\n            delta = 1 if event.key() == Qt.Key_Down else -1\n            new_row = max(0, min(row + delta, self._list.count() - 1))\n            self._list.setCurrentRow(new_row)\n            return\n        super().keyPressEvent(event)\n'
_SOURCES['ui.command_registry'] = '"""\nSystème de commandes "/" (PATCH 25).\n\nListe centralisée des commandes disponibles via le menu "/" façon\nNotion. Chaque commande a un identifiant (matché sur `main_window`),\nun nom affiché et un mot-clé de recherche.\n"""\nfrom __future__ import annotations\n\nCOMMANDS: list[dict[str, str]] = [\n    {"id": "text", "label": "Texte", "keyword": "texte"},\n    {"id": "heading1", "label": "Titre 1", "keyword": "titre1"},\n    {"id": "heading2", "label": "Titre 2", "keyword": "titre2"},\n    {"id": "heading3", "label": "Titre 3", "keyword": "titre3"},\n    {"id": "checklist", "label": "Checklist", "keyword": "checklist"},\n    {"id": "linked_checklist", "label": "Checklists liées", "keyword": "checklistsliees"},\n    {"id": "table", "label": "Tableau", "keyword": "tableau"},\n    {"id": "simple_table", "label": "Tableau simple", "keyword": "tableausimple"},\n    {"id": "gantt", "label": "Gantt", "keyword": "gantt"},\n    {"id": "dependency_gantt", "label": "Planning par dépendances", "keyword": "planningdependances"},\n    {"id": "line_chart", "label": "Courbes", "keyword": "courbes"},\n    {"id": "bar_chart", "label": "Bâtonnets", "keyword": "batonnets"},\n    {"id": "formula", "label": "Résultat calculé", "keyword": "resultat"},\n    {"id": "image", "label": "Image", "keyword": "image"},\n    {"id": "separator", "label": "Séparateur", "keyword": "separateur"},\n    {"id": "quote", "label": "Citation", "keyword": "citation"},\n    {"id": "code", "label": "Code", "keyword": "code"},\n    {"id": "list", "label": "Liste", "keyword": "liste"},\n]\n\n\ndef filter_commands(query: str) -> list[dict[str, str]]:\n    """Filtre les commandes dont le libellé ou le mot-clé contient `query`."""\n    query = (query or "").strip().lower()\n    if not query:\n        return list(COMMANDS)\n    return [\n        command\n        for command in COMMANDS\n        if query in command["keyword"] or query in command["label"].lower()\n    ]\n'
_SOURCES['ui.design_notes'] = '"""\nNotes d\'architecture et choix de design.\n\nChaque patch peut ajouter une entrée ici. Le contenu est affiché\ndans la popup d\'information accessible depuis l\'icône (i) en haut\nà droite de la fenêtre.\n"""\n\nDESIGN_NOTES: list[tuple[str, str]] = [\n    (\n        "Architecture générale",\n        "Le Document est l\'unique source de vérité. Chaque bloc "\n        "possède un identifiant UUID, un type et des données "\n        "(<i>data</i>). Les vues n\'affichent que ce que contient "\n        "le document.",\n    ),\n    (\n        "PATCH 3 — Bloc Texte",\n        "Basé sur QTextEdit : édition libre, retour à la ligne, "\n        "sélection et copier/coller sont natifs à Qt, pas de code "\n        "supplémentaire nécessaire.",\n    ),\n    (\n        "PATCH 4 — Titres",\n        "H1/H2/H3 sont des blocs distincts (QLineEdit), avec une "\n        "taille de police qui dépend du niveau.",\n    ),\n    (\n        "PATCH 5 — Barre d\'outils",\n        "Un bug a été corrigé : le bouton « Nouveau bloc » passait "\n        "involontairement un booléen comme contenu (le signal Qt "\n        "<i>triggered(bool)</i>). Corrigé via une lambda sans "\n        "argument.",\n    ),\n    (\n        "PATCH 6 — Mise en forme",\n        "Le contenu est sauvegardé en HTML (en plus du texte brut) "\n        "pour préserver la mise en forme. Citation et code restent "\n        "simplifiés (pas de bordure visuelle) pour l\'instant.",\n    ),\n    (\n        "PATCH 7 — Gestion du curseur",\n        "Maj+Entrée sépare le bloc en deux ; Entrée seule fait un "\n        "retour à la ligne dans le même bloc (inversé par rapport au "\n        "comportement Notion d\'origine, sur demande explicite). "\n        "Retour arrière en début de bloc vide supprime le bloc, "\n        "sinon il fusionne avec le bloc texte précédent (la fusion "\n        "avec un titre n\'est pas encore supportée).",\n    ),\n    (\n        "PATCH 8 — Sauvegarde",\n        "Format JSON versionné (<i>version</i> + <i>blocks</i>). Un "\n        "registre (<i>blocks/registry.py</i>) reconstruit la bonne "\n        "classe de bloc à partir du type stocké, pour que Nouveau, "\n        "Ouvrir, Sauvegarder et Sauvegarder sous partagent le même "\n        "rendu générique du document.",\n    ),\n    (\n        "PATCH 9 — Chargement",\n        "La reconstruction (id, type, données complètes) était déjà "\n        "assurée par <i>Document.from_dict</i> (PATCH 8) ; ce patch "\n        "ajoute la validation stricte (clé <i>blocks</i> manquante, "\n        "version de fichier trop récente, type de bloc inconnu) et "\n        "un test de non-régression qui prouve que chaque champ "\n        "survit à l\'aller-retour sauvegarde/chargement.",\n    ),\n    (\n        "PATCH 10 — Bloc Checklist",\n        "Chaque élément est {texte, coché} dans <i>data[\'items\']</i>. "\n        "Enregistré dans <i>blocks/registry.py</i> comme prévu, donc "\n        "compatible sauvegarde/chargement sans modification du "\n        "PATCH 8/9.",\n    ),\n    (\n        "PATCH 11 — Checklist « À faire / Déjà fait »",\n        "<i>ChecklistBlock.sort_by_status</i> trie (tri stable) les "\n        "tâches non cochées avant les cochées. Le widget appelle ce "\n        "tri à la construction (donc aussi après un chargement) et "\n        "après chaque coche, puis reconstruit ses lignes dans le "\n        "nouvel ordre : l\'utilisateur ne déplace jamais rien "\n        "manuellement.",\n    ),\n    (\n        "PATCH 12 — Bloc Image",\n        "Image encodée en base64 directement dans <i>data</i> : "\n        "aucun fichier annexe, donc compatible tel quel avec la "\n        "sauvegarde JSON (PATCH 8/9) et les tests de round-trip. "\n        "Redimensionnement via une largeur (hauteur recalculée au "\n        "ratio d\'origine par Qt). Déplacement/suppression réutilisent "\n        "<i>Document.move_block</i> et <i>remove_block</i> (PATCH 2), "\n        "exposés ici par deux boutons ↑/↓ ; le drag & drop générique "\n        "arrive au PATCH 13.",\n    ),\n    (\n        "PATCH 13 — Drag & Drop",\n        "<i>BlockContainer</i> ajoute une poignée « ⠿ » à chaque bloc "\n        "et démarre un <i>QDrag</i> (mime-type privé transportant "\n        "l\'ID du bloc). <i>BlocksArea</i>, désormais le widget "\n        "central, accepte le dépôt et calcule l\'index d\'insertion "\n        "depuis la position Y. Le tout passe par "\n        "<i>Document.move_block</i> (PATCH 2) : générique, donc "\n        "valable pour tous les types de blocs (texte, titres, "\n        "checklists, images, et tableaux au PATCH 14). Les boutons "\n        "↑/↓ de l\'image (PATCH 12) restent en complément accessible.",\n    ),\n    (\n        "Correctif — API ChecklistBlock",\n        "Les tests du PATCH 10 attendaient une API par id d\'élément "\n        "(<i>add_item</i> retourne l\'item, <i>remove_item</i>/"\n        "<i>set_item_text</i>/<i>set_item_checked</i> prennent un id) "\n        "alors que l\'implémentation était basée sur l\'index. Corrigé "\n        "en généralisant les id, avec rétrocompatibilité : un id est "\n        "généré à la volée pour les checklists sauvegardées avant ce "\n        "correctif. Le widget (PATCH 10/11) suit désormais le même id "\n        "par ligne plutôt que sa position.",\n    ),\n    (\n        "PATCH 26 — Menu contextuel",\n        "Clic droit complet, en deux temps. Sur un bloc : "\n        "<i>BlockContainer.contextMenuEvent</i> délègue à "\n        "<i>MainWindow._show_block_context_menu</i>, qui propose "\n        "Dupliquer (via <i>blocks.registry.block_from_dict</i> avec "\n        "un nouvel id), Supprimer, Déplacer ↑/↓, et Convertir en "\n        "(uniquement entre blocs à <i>content</i> texte simple : "\n        "texte, titres, citation, code — la conversion préserve le "\n        "contenu). Sur une zone vide : <i>BlocksArea</i> propose "\n        "d\'ajouter n\'importe quel type de bloc en fin de document, "\n        "via la même fabrique que le menu « / » (PATCH 25), désormais "\n        "partagée (<i>_block_factory</i>) pour éviter toute "\n        "divergence entre les deux menus.",\n    ),\n    (\n        "PATCH 27 — Undo / Redo",\n        "Une seule pile d\'historique (<i>core/history.UndoHistory</i>), "\n        "agnostique du type de bloc : chaque point d\'annulation est un "\n        "snapshot JSON complet du document (même sérialisation que la "\n        "sauvegarde du PATCH 8/9), comparé à l\'état courant par un "\n        "<i>QTimer</i> qui sonde toutes les 600 ms — ce qui regroupe "\n        "les frappes rapides en un seul « undo » par pause, sans "\n        "instrumenter chaque widget de bloc individuellement. Ctrl+Z "\n        "force de toute façon un flush immédiat, donc annuler "\n        "fonctionne même juste après une frappe. Un filtre d\'événements "\n        "au niveau de l\'application intercepte Ctrl+Z/Ctrl+Y avant "\n        "l\'undo natif de QTextEdit/QLineEdit (désactivé sur le bloc "\n        "texte) pour garantir un historique unique et cohérent.",\n    ),\n    (\n        "PATCH 28 — Recherche",\n        "<i>core/search.py</i> : fonction pure "\n        "(<i>search_document</i>), testable sans Qt, qui parcourt "\n        "texte/titres/citation/code, checklists, listes et les deux "\n        "moteurs de tableau (PATCH 14 typé et PATCH 24 simple). "\n        "<i>SearchDialog</i> (Ctrl+F) relance la recherche à chaque "\n        "frappe et fait défiler jusqu\'au résultat choisi. Cela a "\n        "révélé l\'absence de <i>QScrollArea</i> autour des blocs : "\n        "ajoutée ici (prérequis pour qu\'« aller au résultat » ait un "\n        "sens), sans changer la logique de drag & drop (coordonnées "\n        "toujours relatives à <i>BlocksArea</i>).",\n    ),\n    (\n        "PATCH 29 — Remplacement",\n        "<i>core/replace.py</i> (<i>replace_all</i>) suit les mêmes "\n        "catégories de blocs que la recherche, avec une exception "\n        "volontaire : dans le tableau typé (PATCH 15), seules les "\n        "colonnes textuelles (texte, nombre, liste déroulante, liste "\n        "multiple, éléments d\'une checklist imbriquée) sont "\n        "concernées — les colonnes Personne sont exclues (un "\n        "renommage doit passer par le PATCH 16 pour rester "\n        "synchronisé avec le registre), et Date/Durée/Booléen ne "\n        "sont pas du texte. Remplacer un texte riche (PATCH 6) efface "\n        "son HTML devenu incohérent avec le nouveau contenu. "\n        "« Tout remplacer », dans <i>SearchDialog</i>, est une "\n        "mutation du document comme une autre : elle est donc "\n        "annulable via l\'historique générique du PATCH 27, sans code "\n        "supplémentaire.",\n    ),\n    (\n        "PATCH 30 — Liens internes",\n        "Un lien interne est une ancre HTML "\n        "<code>&lt;a href=\\"block://ID\\"&gt;</code> insérée dans le "\n        "texte riche (PATCH 6) : il profite donc gratuitement de la "\n        "sauvegarde JSON (le HTML du bloc le contient déjà) sans "\n        "nouveau format. Le sélecteur de bloc (<i>BlockPickerDialog</i>, "\n        "ouvert via le bouton « Lien interne » de la toolbar) réutilise "\n        "<i>core/block_preview.py</i> (aperçu textuel générique, testé "\n        "seul) pour afficher chaque bloc candidat. Ctrl+Clic sur le "\n        "lien émet <i>link_activated</i>, branché sur "\n        "<i>_scroll_to_block</i> (PATCH 28) : navigation et recherche "\n        "partagent le même mécanisme de défilement.",\n    ),\n    (\n        "PATCH 41 — Documentation",\n        "<code>README.md</code> à la racine : installation, "\n        "commande de tests correcte (<code>pytest</code>, pas "\n        "<code>unittest discover</code> — voir le correctif du "\n        "PATCH 13), architecture en trois couches "\n        "(<code>core</code>/<code>blocks</code>/<code>ui</code>), API "\n        "interne des points d\'entrée les plus réutilisés "\n        "(<i>Document</i>, <i>block_from_dict</i>, <i>UndoHistory</i>, "\n        "recherche/remplacement, export/import), format de sauvegarde "\n        "JSON complet avec un exemple généré depuis le code (pas "\n        "inventé à la main), et un guide en cinq étapes pour ajouter "\n        "un nouveau type de bloc. <code>requirements.txt</code> / "\n        "<code>requirements-dev.txt</code> ajoutés : absents jusqu\'ici, "\n        "alors que le README doit pouvoir s\'appuyer dessus.",\n    ),\n    (\n        "PATCH 42 — Version 1.0",\n        "Stabilisation : nettoyage des imports inutilisés repérés par "\n        "analyse statique (<code>pyflakes</code>, 0 avertissement "\n        "restant sur <code>core/</code>, <code>blocks/</code>, "\n        "<code>ui/</code>), et un test d\'intégration bout-en-bout "\n        "(<code>tests/test_full_document_integration.py</code>) : un "\n        "document avec un bloc de chaque type, cycle complet "\n        "sauvegarde/rechargement disque, recherche et remplacement "\n        "transverses, puis un smoke-test <i>MainWindow</i> réel "\n        "(ajout de neuf types de blocs, annulé puis rétabli en un "\n        "seul geste). Gel des fonctionnalités et publication : "\n        "<code>core/version.py</code> (source unique de la version, "\n        "affichée dans le titre de fenêtre et « À propos ») et "\n        "<code>CHANGELOG.md</code> résumant les 42 patches.",\n    ),\n]\n'
_SOURCES['ui.emoji_picker'] = '"""\nPopup sélecteur d\'emojis (PATCH 35).\n\nFenêtre flottante sans bordure (Qt.Popup), même famille d\'interaction\nque le menu de commandes "/" (PATCH 25) : recherche filtrable,\nsélection à la souris ou au clavier.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtCore import Qt, Signal\nfrom PySide6.QtWidgets import QLineEdit, QListWidget, QListWidgetItem, QVBoxLayout, QWidget\n\nfrom core.emoji_data import search_emojis\n\n\nclass EmojiPicker(QWidget):\n    """Popup filtrable listant les emojis (PATCH 35)."""\n\n    emoji_selected = Signal(str)  # émet l\'emoji choisi (ex. "😄")\n\n    def __init__(self, parent=None) -> None:\n        super().__init__(parent, Qt.Popup)\n        self.setAttribute(Qt.WA_DeleteOnClose)\n\n        layout = QVBoxLayout(self)\n        layout.setContentsMargins(4, 4, 4, 4)\n\n        self._search = QLineEdit(self)\n        self._search.setPlaceholderText("Rechercher un emoji (ex. smile)...")\n        self._search.textChanged.connect(self._on_search_changed)\n        self._search.returnPressed.connect(self._on_return_pressed)\n        layout.addWidget(self._search)\n\n        self._list = QListWidget(self)\n        self._list.itemClicked.connect(self._on_item_clicked)\n        layout.addWidget(self._list)\n\n        self.setFixedSize(240, 260)\n        self._populate("")\n        self._search.setFocus()\n\n    def _populate(self, query: str) -> None:\n        self._list.clear()\n        for emoji, shortcode, _category in search_emojis(query):\n            item = QListWidgetItem(f"{emoji}  :{shortcode}:")\n            item.setData(Qt.UserRole, emoji)\n            self._list.addItem(item)\n        if self._list.count():\n            self._list.setCurrentRow(0)\n\n    def _on_search_changed(self, text: str) -> None:\n        self._populate(text)\n\n    def _on_item_clicked(self, item: QListWidgetItem) -> None:\n        self.emoji_selected.emit(item.data(Qt.UserRole))\n        self.close()\n\n    def _on_return_pressed(self) -> None:\n        item = self._list.currentItem()\n        if item is not None:\n            self.emoji_selected.emit(item.data(Qt.UserRole))\n        self.close()\n\n    def keyPressEvent(self, event) -> None:  # noqa: N802\n        if event.key() == Qt.Key_Escape:\n            self.close()\n            return\n        if event.key() in (Qt.Key_Down, Qt.Key_Up):\n            row = self._list.currentRow()\n            delta = 1 if event.key() == Qt.Key_Down else -1\n            new_row = max(0, min(row + delta, self._list.count() - 1))\n            self._list.setCurrentRow(new_row)\n            return\n        super().keyPressEvent(event)\n'
_SOURCES['ui.export_pdf'] = '"""\nExport PDF (PATCH 36).\n\nRéutilise `core.document_html_export.document_to_html` (rendu HTML\npur du document), l\'injecte dans un QTextDocument, puis l\'imprime\ndans un fichier PDF via QPrinter — la même approche que l\'aperçu\navant impression natif de Qt, donc fiable et sans dépendance externe.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtGui import QPageLayout, QPageSize, QTextDocument\nfrom PySide6.QtPrintSupport import QPrinter\n\nfrom core.document_html_export import document_to_html\n\n\ndef export_document_to_pdf(document, filepath: str) -> None:\n    """Génère un PDF du document courant à `filepath`."""\n    html = document_to_html(document)\n\n    text_document = QTextDocument()\n    text_document.setHtml(html)\n\n    printer = QPrinter(QPrinter.HighResolution)\n    printer.setOutputFormat(QPrinter.PdfFormat)\n    printer.setPageSize(QPageSize(QPageSize.A4))\n    printer.setPageOrientation(QPageLayout.Portrait)\n    printer.setOutputFileName(filepath)\n\n    text_document.print_(printer)\n'
_SOURCES['ui.info_dialog'] = '"""\nPopup d\'information : explications et choix de design du projet.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtWidgets import QDialog, QTextBrowser, QVBoxLayout\n\nfrom ui.design_notes import DESIGN_NOTES\nfrom core.version import __version__\n\n\nclass InfoDialog(QDialog):\n    """Fenêtre modale listant les choix de design faits jusqu\'ici."""\n\n    def __init__(self, parent=None) -> None:\n        super().__init__(parent)\n        self.setWindowTitle("À propos de ce projet")\n        self.resize(520, 420)\n\n        layout = QVBoxLayout(self)\n\n        browser = QTextBrowser(self)\n        browser.setOpenExternalLinks(False)\n        browser.setHtml(self._build_html())\n        layout.addWidget(browser)\n\n    @staticmethod\n    def _build_html() -> str:\n        parts = [f"<h3>Notion Lite {__version__}</h3>", "<h4>Explications et choix de design</h4>"]\n        for title, text in DESIGN_NOTES:\n            parts.append(f"<p><b>{title}</b><br>{text}</p>")\n        return "".join(parts)\n'
_SOURCES['ui.main_window'] = '"""\nFenêtre principale de Notion Lite.\n"""\nfrom __future__ import annotations\n\nimport base64\nimport json\nimport uuid\nfrom pathlib import Path\n\nfrom PySide6.QtCore import QEvent, QPoint, Qt, QTimer\nfrom PySide6.QtGui import QAction, QActionGroup, QColor, QKeySequence, QTextCursor\nfrom PySide6.QtWidgets import (\n    QApplication,\n    QColorDialog,\n    QFileDialog,\n    QLineEdit,\n    QMainWindow,\n    QMenu,\n    QMessageBox,\n    QScrollArea,\n    QTextEdit,\n    QWidget,\n)\n\nfrom blocks.checklist_block import ChecklistBlock\nfrom blocks.code_block import CodeBlock\nfrom blocks.formula_block import FormulaBlock\nfrom blocks.heading_block import HeadingBlock\nfrom blocks.image_block import ImageBlock\nfrom blocks.bar_chart_block import BarChartBlock\nfrom blocks.dependency_gantt_block import DependencyGanttBlock\nfrom blocks.line_chart_block import LineChartBlock\nfrom blocks.gantt_block import GanttBlock\nfrom blocks.linked_checklist_block import LinkedChecklistBlock\nfrom blocks.list_block import ListBlock\nfrom blocks.quote_block import QuoteBlock\nfrom blocks.separator_block import SeparatorBlock\nfrom blocks.simple_table_block import SimpleTableBlock\nfrom blocks.table_block import TableBlock\nfrom blocks.registry import block_from_dict\nfrom blocks.text_block import TextBlock\nfrom core.block_icons import icon_for_block\nfrom core.block_preview import preview_for_block\nfrom core.document_html_export import document_to_full_html\nfrom core.document_html_import import html_to_document\nfrom core.document_markdown_export import document_to_markdown\nfrom core.document_markdown_import import markdown_to_document\nfrom core.document import Document\nfrom core.history import UndoHistory\nfrom core.momo_template import build_momo_template\nfrom core.version import __version__\nfrom ui.blocks.block_container import BlockContainer\nfrom ui.blocks.checklist_block_widget import ChecklistBlockWidget\nfrom ui.blocks.code_block_widget import CodeBlockWidget\nfrom ui.blocks.formula_block_widget import FormulaBlockWidget\nfrom ui.blocks.bar_chart_block_widget import BarChartBlockWidget\nfrom ui.blocks.dependency_gantt_block_widget import DependencyGanttBlockWidget\nfrom ui.blocks.line_chart_block_widget import LineChartBlockWidget\nfrom ui.blocks.gantt_block_widget import GanttBlockWidget\nfrom ui.blocks.heading_block_widget import HeadingBlockWidget\nfrom ui.blocks.image_block_widget import ImageBlockWidget\nfrom ui.blocks.linked_checklist_block_widget import LinkedChecklistBlockWidget\nfrom ui.blocks.list_block_widget import ListBlockWidget\nfrom ui.blocks.quote_block_widget import QuoteBlockWidget\nfrom ui.blocks.separator_block_widget import SeparatorBlockWidget\nfrom ui.blocks.simple_table_block_widget import SimpleTableBlockWidget\nfrom ui.blocks.table_block_widget import TableBlockWidget\nfrom ui.blocks.text_block_widget import TextBlockWidget\nfrom ui.block_picker_dialog import BlockPickerDialog\nfrom ui.blocks_area import BlocksArea\nfrom ui.command_menu import CommandMenu\nfrom ui.command_registry import COMMANDS\nfrom ui.emoji_picker import EmojiPicker\nfrom ui.export_pdf import export_document_to_pdf\nfrom ui.info_dialog import InfoDialog\nfrom ui.people_manager_dialog import PeopleManagerDialog\nfrom ui.search_dialog import SearchDialog\nfrom ui.themes.theme import (\n    THEME_DARK,\n    THEME_LABELS,\n    THEMES,\n    apply_theme,\n    current_theme,\n    toggle_theme,\n)\nfrom ui.settings import (\n    get_autosave_enabled,\n    get_block_spacing,\n    set_autosave_enabled,\n    set_block_spacing,\n)\nfrom ui.toolbar import MainToolBar\n\n# Racine du projet (deux niveaux au-dessus de ce fichier : ui/main_window.py).\nimport atexit as _atexit\nimport base64 as _base64\nimport os as _os\nimport tempfile as _tempfile\n_ICON_INFO_SVG_B64 = \'\'\n_icon_tmp = _tempfile.NamedTemporaryFile(suffix=\'.svg\', delete=False)\n_icon_tmp.write(_base64.b64decode(_ICON_INFO_SVG_B64))\n_icon_tmp.close()\n_atexit.register(lambda: _os.unlink(_icon_tmp.name))\n_INFO_ICON_PATH = _icon_tmp.name\n\n# PATCH 27 — Intervalle (ms) du sondage qui regroupe les frappes rapides\n# (édition de texte) en un seul point d\'annulation ("undo" par pause,\n# pas par caractère). Ctrl+Z force de toute façon un flush immédiat.\n_UNDO_POLL_INTERVAL_MS = 600\n\n# PATCH 26 — Cibles de conversion proposées dans le menu contextuel :\n# uniquement les blocs à contenu texte simple (voir _create_content_widget_for_block).\n_CONVERT_TARGETS: list[tuple[str, str]] = [\n    ("text", "Texte"),\n    ("heading1", "Titre 1"),\n    ("heading2", "Titre 2"),\n    ("heading3", "Titre 3"),\n    ("quote", "Citation"),\n    ("code", "Code"),\n]\n\n\nclass MainWindow(QMainWindow):\n    """Fenêtre principale de l\'application.\n\n    Affiche le document sous forme d\'une colonne de blocs, expose une\n    toolbar de mise en forme (PATCH 5 et 6), gère une expérience de\n    curseur multi-blocs façon Notion (PATCH 7) et permet de réordonner\n    n\'importe quel bloc par glisser-déposer (PATCH 13).\n    """\n\n    def __init__(self) -> None:\n        super().__init__()\n\n        self.setWindowTitle(f"Notion Lite {__version__}")\n        self.resize(1000, 700)\n\n        self._document = build_momo_template()\n        self._active_text_widget: TextBlockWidget | None = None\n        self._current_file: Path | None = None\n\n        self._setup_ui()\n\n    def _setup_ui(self) -> None:\n        """Prépare la toolbar, la zone de contenu et affiche le document."""\n        toolbar = MainToolBar(\n            actions={\n                "new_block": lambda: self._add_text_block(),\n                "new_checklist": self._add_checklist_block,\n                "new_image": self._add_image_block,\n                "new_table": self._add_table_block,\n                "new_simple_table": self._add_simple_table_block,\n                "new_gantt": self._add_gantt_block,\n                "new_separator": self._add_separator_block,\n                "new_quote": self._add_quote_block,\n                "new_code": self._add_code_block,\n                "new_list": self._add_list_block,\n                "bold": self._with_active(TextBlockWidget.toggle_bold),\n                "italic": self._with_active(TextBlockWidget.toggle_italic),\n                "underline": self._with_active(TextBlockWidget.toggle_underline),\n                "strikethrough": self._with_active(TextBlockWidget.toggle_strikethrough),\n                "align_left": self._with_active(lambda w: w.set_alignment(Qt.AlignLeft)),\n                "align_center": self._with_active(lambda w: w.set_alignment(Qt.AlignCenter)),\n                "align_right": self._with_active(lambda w: w.set_alignment(Qt.AlignRight)),\n                "align_justify": self._with_active(lambda w: w.set_alignment(Qt.AlignJustify)),\n                "bullet_list": self._with_active(TextBlockWidget.toggle_bullet_list),\n                "numbered_list": self._with_active(TextBlockWidget.toggle_numbered_list),\n                "quote": self._with_active(TextBlockWidget.toggle_quote),\n                "code": self._with_active(TextBlockWidget.toggle_code),\n                "color": self._apply_color,\n                "insert_link": self._insert_internal_link,\n                "insert_emoji": self._show_emoji_picker,\n            },\n            on_size_changed=self._apply_size,\n            on_info=self._show_info_dialog,\n            info_icon_path=_INFO_ICON_PATH,\n        )\n        self.addToolBar(toolbar)\n        self._setup_file_menu()\n\n        central = BlocksArea(\n            on_block_dropped=self._on_block_dropped,\n            on_empty_context_menu=self._show_empty_context_menu,\n        )\n        self._blocks_layout = central.blocks_layout\n\n        # PATCH 28 : zone de défilement, nécessaire pour pouvoir amener\n        # un résultat de recherche à l\'écran (`_scroll_to_block`).\n        self._scroll_area = QScrollArea(self)\n        self._scroll_area.setWidgetResizable(True)\n        self._scroll_area.setWidget(central)\n        self.setCentralWidget(self._scroll_area)\n\n        # PATCH 48 — le document initial vient désormais du template\n        # "Méthodo Momo" (voir __init__), plus besoin de contenu de démo ici.\n        self._render_document(focus_last=True)\n\n        # -- Undo/Redo (PATCH 27) ------------------------------------\n        self._undo_history = UndoHistory(self._document_snapshot())\n        self._undo_timer = QTimer(self)\n        self._undo_timer.setInterval(_UNDO_POLL_INTERVAL_MS)\n        self._undo_timer.timeout.connect(self._poll_undo_snapshot)\n        self._undo_timer.start()\n        # Intercepte Ctrl+Z/Ctrl+Y avant que QTextEdit/QLineEdit ne les\n        # traitent eux-mêmes (undo natif local, non désiré ici).\n        QApplication.instance().installEventFilter(self)\n\n    def _setup_file_menu(self) -> None:\n        """Menu Fichier : Nouveau / Ouvrir / Sauvegarder / Sauvegarder sous (PATCH 8)."""\n        file_menu = self.menuBar().addMenu("&Fichier")\n\n        new_action = QAction("Nouveau (Méthodo Momo)", self)\n        new_action.setShortcut(QKeySequence.New)\n        new_action.triggered.connect(self._new_document)\n        file_menu.addAction(new_action)\n\n        new_blank_action = QAction("Nouveau document vide", self)\n        new_blank_action.triggered.connect(self._new_blank_document)\n        file_menu.addAction(new_blank_action)\n\n        open_action = QAction("Ouvrir...", self)\n        open_action.setShortcut(QKeySequence.Open)\n        open_action.triggered.connect(self._open_document)\n        file_menu.addAction(open_action)\n\n        save_action = QAction("Sauvegarder", self)\n        save_action.setShortcut(QKeySequence.Save)\n        save_action.triggered.connect(self._save_document)\n        file_menu.addAction(save_action)\n\n        save_as_action = QAction("Sauvegarder sous...", self)\n        save_as_action.setShortcut(QKeySequence.SaveAs)\n        save_as_action.triggered.connect(self._save_document_as)\n        file_menu.addAction(save_as_action)\n\n        export_pdf_action = QAction("Exporter en PDF...", self)\n        export_pdf_action.triggered.connect(self._export_pdf)\n        file_menu.addAction(export_pdf_action)\n\n        export_md_action = QAction("Exporter en Markdown...", self)\n        export_md_action.triggered.connect(self._export_markdown)\n        file_menu.addAction(export_md_action)\n\n        export_html_action = QAction("Exporter en HTML...", self)\n        export_html_action.triggered.connect(self._export_html)\n        file_menu.addAction(export_html_action)\n\n        import_md_action = QAction("Importer un Markdown...", self)\n        import_md_action.triggered.connect(self._import_markdown)\n        file_menu.addAction(import_md_action)\n\n        import_html_action = QAction("Importer un HTML...", self)\n        import_html_action.triggered.connect(self._import_html)\n        file_menu.addAction(import_html_action)\n\n        edit_menu = self.menuBar().addMenu("&Édition")\n\n        undo_action = QAction("Annuler", self)\n        undo_action.setShortcut(QKeySequence("Ctrl+Z"))\n        undo_action.triggered.connect(self._undo)\n        edit_menu.addAction(undo_action)\n\n        redo_action = QAction("Rétablir", self)\n        redo_action.setShortcut(QKeySequence("Ctrl+Y"))\n        redo_action.triggered.connect(self._redo)\n        edit_menu.addAction(redo_action)\n\n        edit_menu.addSeparator()\n        people_action = QAction("Gestionnaire de personnes...", self)\n        people_action.triggered.connect(self._show_people_manager)\n        edit_menu.addAction(people_action)\n\n        search_action = QAction("Rechercher...", self)\n        search_action.setShortcut(QKeySequence("Ctrl+F"))\n        search_action.triggered.connect(self._show_search_dialog)\n        edit_menu.addAction(search_action)\n\n        replace_action = QAction("Remplacer...", self)\n        replace_action.setShortcut(QKeySequence("Ctrl+H"))\n        replace_action.triggered.connect(self._show_search_dialog)\n        edit_menu.addAction(replace_action)\n\n        self._favorites_menu = self.menuBar().addMenu("&Favoris")\n        self._favorites_menu.aboutToShow.connect(self._populate_favorites_menu)\n\n        view_menu = self.menuBar().addMenu("&Affichage")\n        self._dark_mode_action = QAction("Mode sombre", self)\n        self._dark_mode_action.setCheckable(True)\n        self._dark_mode_action.setChecked(current_theme(QApplication.instance()) == THEME_DARK)\n        self._dark_mode_action.setShortcut(QKeySequence("Ctrl+Shift+D"))\n        self._dark_mode_action.triggered.connect(self._toggle_dark_mode)\n        view_menu.addAction(self._dark_mode_action)\n\n        theme_menu = view_menu.addMenu("Thème")\n        theme_group = QActionGroup(self)\n        theme_group.setExclusive(True)\n        self._theme_actions: dict[str, QAction] = {}\n        for theme_name in THEMES:\n            action = QAction(THEME_LABELS[theme_name], self)\n            action.setCheckable(True)\n            action.setChecked(current_theme(QApplication.instance()) == theme_name)\n            action.triggered.connect(lambda _, t=theme_name: self._set_theme(t))\n            theme_group.addAction(action)\n            theme_menu.addAction(action)\n            self._theme_actions[theme_name] = action\n\n        view_menu.addSeparator()\n        self._block_spacing_action = QAction("Espacer les titres, tableaux et graphiques", self)\n        self._block_spacing_action.setCheckable(True)\n        self._block_spacing_action.setChecked(get_block_spacing())\n        self._block_spacing_action.triggered.connect(self._toggle_block_spacing)\n        view_menu.addAction(self._block_spacing_action)\n\n        self._autosave_action = QAction("Sauvegarde automatique", self)\n        self._autosave_action.setCheckable(True)\n        self._autosave_action.setChecked(get_autosave_enabled())\n        self._autosave_action.triggered.connect(self._toggle_autosave)\n        view_menu.addAction(self._autosave_action)\n    # -- Mise en forme (PATCH 5 / 6) -------------------------------------\n\n    def _with_active(self, method):\n        """Enveloppe une méthode de TextBlockWidget pour l\'appliquer\n        au bloc texte actuellement focus, s\'il y en a un."""\n\n        def handler() -> None:\n            if self._active_text_widget is not None:\n                method(self._active_text_widget)\n\n        return handler\n\n    def _on_text_widget_focused(self, widget: TextBlockWidget) -> None:\n        self._active_text_widget = widget\n\n    def _apply_color(self) -> None:\n        if self._active_text_widget is None:\n            return\n        color = QColorDialog.getColor(QColor("black"), self, "Choisir une couleur")\n        if color.isValid():\n            self._active_text_widget.set_text_color(color)\n\n    def _insert_internal_link(self) -> None:\n        """PATCH 30 — Insère, dans le bloc texte actif, un lien vers un\n        autre bloc du document (Ctrl+Clic dessus pour y naviguer)."""\n        if self._active_text_widget is None:\n            return\n        source_block_id = self._active_text_widget.block.id\n        picker = BlockPickerDialog(self._document, exclude_block_id=source_block_id, parent=self)\n        picker.exec()\n        if picker.selected_block_id is None:\n            return\n\n        target = next(\n            (b for b in self._document.blocks if b.id == picker.selected_block_id), None\n        )\n        if target is None:\n            return\n        label = preview_for_block(target)\n        self._active_text_widget.insert_internal_link(picker.selected_block_id, label)\n\n    def _show_emoji_picker(self) -> None:\n        """PATCH 35 — Ouvre le sélecteur d\'emoji, insère au curseur du\n        bloc texte actif."""\n        if self._active_text_widget is None:\n            return\n        widget = self._active_text_widget\n        picker = EmojiPicker(self)\n        picker.emoji_selected.connect(widget.insert_emoji)\n        cursor_rect = widget.cursorRect()\n        anchor = widget.mapToGlobal(cursor_rect.bottomLeft())\n        picker.move(anchor)\n        picker.show()\n\n    def _apply_size(self, size: int) -> None:\n        if self._active_text_widget is not None:\n            self._active_text_widget.set_font_size(size)\n\n    def _show_info_dialog(self) -> None:\n        """Ouvre la popup listant les explications et choix de design."""\n        InfoDialog(self).exec()\n\n    def _show_people_manager(self) -> None:\n        """PATCH 16 — Ouvre le gestionnaire du registre partagé de personnes."""\n        PeopleManagerDialog(self._document, self).exec()\n        self._render_document()\n\n    # -- Recherche globale (PATCH 28) --------------------------------------\n\n    def _show_search_dialog(self) -> None:\n        """CTRL+F/CTRL+H — Recherche (et remplacement, PATCH 29) globaux."""\n        SearchDialog(\n            self._document,\n            on_result_activated=self._scroll_to_block,\n            on_document_changed=self._render_document,\n            parent=self,\n        ).exec()\n\n    def _scroll_to_block(self, block_id: str) -> None:\n        """Fait défiler jusqu\'au bloc et le met en surbrillance brièvement."""\n        for i in range(self._blocks_layout.count()):\n            item = self._blocks_layout.itemAt(i)\n            widget = item.widget() if item else None\n            if isinstance(widget, BlockContainer) and widget.block_id == block_id:\n                self._scroll_area.ensureWidgetVisible(widget)\n                widget.content.setFocus()\n                return\n\n    # -- Favoris (PATCH 31) ------------------------------------------------\n\n    def _populate_favorites_menu(self) -> None:\n        """Reconstruit le menu "Favoris" juste avant son ouverture, pour\n        toujours refléter l\'état courant du document."""\n        self._favorites_menu.clear()\n        favorites = self._document.favorite_blocks()\n        if not favorites:\n            empty_action = self._favorites_menu.addAction("(aucun favori)")\n            empty_action.setEnabled(False)\n            return\n        for block in favorites:\n            label = preview_for_block(block)\n            action = self._favorites_menu.addAction(label)\n            action.triggered.connect(lambda _, bid=block.id: self._scroll_to_block(bid))\n\n    # -- Mode sombre (PATCH 32) ---------------------------------------------\n\n    def _toggle_dark_mode(self) -> None:\n        new_theme = toggle_theme(QApplication.instance())\n        self._dark_mode_action.setChecked(new_theme == THEME_DARK)\n        self._sync_theme_menu(new_theme)\n\n    def _toggle_block_spacing(self) -> None:\n        """PATCH 51 — bascule l\'espacement supplémentaire au-dessus des\n        titres/sous-titres, tableaux et graphiques, et redessine le\n        document pour l\'appliquer."""\n        set_block_spacing(self._block_spacing_action.isChecked())\n        self._render_document()\n\n    def _toggle_autosave(self) -> None:\n        set_autosave_enabled(self._autosave_action.isChecked())\n\n    def _set_theme(self, theme_name: str) -> None:\n        """PATCH 33 — Applique un thème choisi dans le sous-menu "Thème"."""\n        apply_theme(QApplication.instance(), theme_name)\n        self._dark_mode_action.setChecked(theme_name == THEME_DARK)\n        self._sync_theme_menu(theme_name)\n\n    def _sync_theme_menu(self, theme_name: str) -> None:\n        action = self._theme_actions.get(theme_name)\n        if action is not None:\n            action.setChecked(True)\n\n    # -- Undo / Redo (PATCH 27) --------------------------------------------\n\n    def _document_snapshot(self) -> str:\n        """Sérialise l\'état courant du document (indépendant, réutilise\n        le format de sauvegarde JSON du PATCH 8/9)."""\n        return json.dumps(self._document.to_dict(), sort_keys=True)\n\n    def _poll_undo_snapshot(self) -> None:\n        """Sondage périodique : regroupe les frappes rapides d\'une même\n        pause en un seul point d\'annulation."""\n        if self._undo_history.check(self._document_snapshot()):\n            self._maybe_autosave()\n\n    def _maybe_autosave(self) -> None:\n        """PATCH 51 — Sauvegarde automatique : dès qu\'un document a été\n        sauvegardé une première fois (self._current_file défini), toute\n        modification ultérieure détectée par le sondage undo (donc déjà\n        "posée" un court instant, pas frappe par frappe) réécrit\n        silencieusement le même fichier, si l\'option est activée\n        (activée par défaut, réglable dans le menu Affichage)."""\n        if not get_autosave_enabled() or self._current_file is None:\n            return\n        self._write_document(self._current_file)\n\n    def _restore_snapshot(self, raw_snapshot: str) -> None:\n        self._document = Document.from_dict(json.loads(raw_snapshot))\n        self._render_document()\n\n    def _undo(self) -> None:\n        """CTRL+Z — Annule la dernière action (toute action est\n        annulable : ajout, suppression, déplacement, conversion,\n        édition de texte, de checklist, de tableau, ...)."""\n        snapshot = self._undo_history.undo(self._document_snapshot())\n        if snapshot is not None:\n            self._restore_snapshot(snapshot)\n\n    def _redo(self) -> None:\n        """CTRL+Y — Rétablit la dernière action annulée."""\n        snapshot = self._undo_history.redo()\n        if snapshot is not None:\n            self._restore_snapshot(snapshot)\n\n    def eventFilter(self, obj, event) -> bool:  # noqa: N802\n        """Intercepte Ctrl+Z/Ctrl+Y avant les widgets d\'édition natifs\n        (QTextEdit/QLineEdit ont sinon leur propre undo local)."""\n        if event.type() == QEvent.KeyPress and event.modifiers() == Qt.ControlModifier:\n            if event.key() == Qt.Key_Z:\n                self._undo()\n                return True\n            if event.key() == Qt.Key_Y:\n                self._redo()\n                return True\n        return super().eventFilter(obj, event)\n\n    # -- Rendu générique des blocs / drag & drop (PATCH 8, 13) ------------\n\n    def _create_content_widget_for_block(self, block) -> QWidget:\n        """Crée le widget métier adapté au type d\'un bloc (sans poignée)."""\n        if isinstance(block, TextBlock):\n            return self._create_text_widget(block)\n        if isinstance(block, HeadingBlock):\n            return HeadingBlockWidget(block)\n        if isinstance(block, ChecklistBlock):\n            return ChecklistBlockWidget(block)\n        if isinstance(block, LinkedChecklistBlock):\n            return LinkedChecklistBlockWidget(block)\n        if isinstance(block, TableBlock):\n            return TableBlockWidget(block, self._document)\n        if isinstance(block, SimpleTableBlock):\n            return SimpleTableBlockWidget(block)\n        if isinstance(block, GanttBlock):\n            return GanttBlockWidget(block, self._document)\n        if isinstance(block, DependencyGanttBlock):\n            return DependencyGanttBlockWidget(block, self._document)\n        if isinstance(block, LineChartBlock):\n            return LineChartBlockWidget(block, self._document)\n        if isinstance(block, BarChartBlock):\n            return BarChartBlockWidget(block)\n        if isinstance(block, FormulaBlock):\n            return FormulaBlockWidget(block, self._document)\n        if isinstance(block, SeparatorBlock):\n            return SeparatorBlockWidget(block)\n        if isinstance(block, QuoteBlock):\n            return QuoteBlockWidget(block)\n        if isinstance(block, CodeBlock):\n            return CodeBlockWidget(block)\n        if isinstance(block, ListBlock):\n            return ListBlockWidget(block)\n        if isinstance(block, ImageBlock):\n            return ImageBlockWidget(\n                block,\n                on_move_up=lambda block_id=block.id: self._move_block(block_id, -1),\n                on_move_down=lambda block_id=block.id: self._move_block(block_id, 1),\n                on_delete=lambda block_id=block.id: self._delete_block(block_id),\n            )\n        raise ValueError(f"Type de bloc non pris en charge à l\'affichage : {block.type}")\n\n    # PATCH 51 — types de blocs devant "respirer" (marge au-dessus) quand\n    # l\'option d\'espacement est activée : titres, tableaux et graphiques.\n    _SPACED_BLOCK_TYPES = (\n        HeadingBlock,\n        TableBlock,\n        SimpleTableBlock,\n        GanttBlock,\n        DependencyGanttBlock,\n        LineChartBlock,\n        BarChartBlock,\n    )\n    _EXTRA_TOP_MARGIN_PX = 22\n\n    def _wrap(self, content: QWidget, block_id: str) -> BlockContainer:\n        """PATCH 13 — Ajoute la poignée de glisser-déposer à un widget de\n        bloc, PATCH 34 — ainsi que son icône de type, PATCH 51 — et\n        l\'espacement optionnel au-dessus des titres/tableaux/graphiques."""\n        block = self._document.find_block(block_id)\n        extra_top_margin = 0\n        if get_block_spacing() and isinstance(block, self._SPACED_BLOCK_TYPES):\n            extra_top_margin = self._EXTRA_TOP_MARGIN_PX\n        return BlockContainer(\n            content,\n            block_id,\n            on_context_menu_requested=self._show_block_context_menu,\n            icon=icon_for_block(block) if block is not None else "",\n            extra_top_margin=extra_top_margin,\n        )\n\n    def _find_container(self, content_widget: QWidget) -> tuple[int, BlockContainer | None]:\n        """Retrouve (index dans le layout, BlockContainer) d\'un widget de contenu."""\n        for i in range(self._blocks_layout.count()):\n            item = self._blocks_layout.itemAt(i)\n            widget = item.widget() if item else None\n            if isinstance(widget, BlockContainer) and widget.content is content_widget:\n                return i, widget\n        return -1, None\n\n    def _layout_index_of_content(self, content_widget: QWidget) -> int:\n        return self._find_container(content_widget)[0]\n\n    def _content_widget_at(self, layout_index: int) -> QWidget | None:\n        item = self._blocks_layout.itemAt(layout_index)\n        widget = item.widget() if item else None\n        return widget.content if isinstance(widget, BlockContainer) else None\n\n    def _render_document(self, focus_last: bool = False) -> None:\n        """(Re)construit entièrement l\'affichage à partir de self._document."""\n        self._active_text_widget = None\n        while self._blocks_layout.count():\n            item = self._blocks_layout.takeAt(0)\n            widget = item.widget()\n            if widget is not None:\n                widget.deleteLater()\n\n        last_content: QWidget | None = None\n        for block in self._document.blocks:\n            last_content = self._create_content_widget_for_block(block)\n            self._blocks_layout.addWidget(self._wrap(last_content, block.id))\n\n        if focus_last and last_content is not None:\n            last_content.setFocus()\n\n    def _on_block_dropped(self, block_id: str, target_index: int) -> None:\n        """PATCH 13 — Réordonne le document après un glisser-déposer."""\n        current_index = next(\n            (i for i, b in enumerate(self._document.blocks) if b.id == block_id), None\n        )\n        if current_index is None:\n            return\n        if target_index > current_index:\n            target_index -= 1  # le bloc quitte sa position avant d\'être réinséré\n        if target_index == current_index:\n            return\n        self._document.move_block(block_id, target_index)\n        self._render_document()\n\n    # -- Menu contextuel (PATCH 26) ----------------------------------------\n\n    def _show_block_context_menu(self, block_id: str, global_pos: QPoint) -> None:\n        """Clic droit complet sur un bloc : dupliquer, supprimer,\n        déplacer, convertir."""\n        index = next(\n            (i for i, b in enumerate(self._document.blocks) if b.id == block_id), None\n        )\n        if index is None:\n            return\n        block = self._document.blocks[index]\n\n        menu = QMenu(self)\n        duplicate_action = menu.addAction("Dupliquer")\n        delete_action = menu.addAction("Supprimer")\n        menu.addSeparator()\n\n        favorite_label = "Retirer des favoris" if self._document.is_favorite(block_id) else "Ajouter aux favoris"\n        favorite_action = menu.addAction(favorite_label)\n        menu.addSeparator()\n\n        move_up_action = menu.addAction("Déplacer vers le haut")\n        move_up_action.setEnabled(index > 0)\n        move_down_action = menu.addAction("Déplacer vers le bas")\n        move_down_action.setEnabled(index < len(self._document.blocks) - 1)\n\n        convert_actions: dict[QAction, str] = {}\n        if hasattr(block, "content"):\n            # Conversion uniquement entre blocs à contenu texte simple.\n            menu.addSeparator()\n            convert_menu = menu.addMenu("Convertir en")\n            for target_id, label in _CONVERT_TARGETS:\n                action = convert_menu.addAction(label)\n                action.setEnabled(block.type != target_id)\n                convert_actions[action] = target_id\n\n        chosen = menu.exec(global_pos)\n        if chosen is None:\n            return\n        if chosen is duplicate_action:\n            self._duplicate_block(block_id)\n        elif chosen is delete_action:\n            self._delete_block(block_id)\n        elif chosen is favorite_action:\n            self._document.toggle_favorite(block_id)\n        elif chosen is move_up_action:\n            self._move_block(block_id, -1)\n        elif chosen is move_down_action:\n            self._move_block(block_id, 1)\n        elif chosen in convert_actions:\n            self._convert_block(block_id, convert_actions[chosen])\n\n    def _show_empty_context_menu(self, global_pos: QPoint) -> None:\n        """Clic droit sur une zone vide : propose d\'ajouter un bloc en fin\n        de document (mêmes cibles que le menu "/")."""\n        menu = QMenu(self)\n        actions: dict[QAction, str] = {}\n        for command in COMMANDS:\n            action = menu.addAction(command["label"])\n            actions[action] = command["id"]\n\n        chosen = menu.exec(global_pos)\n        if chosen is None:\n            return\n        self._append_block_from_command(actions[chosen])\n\n    def _duplicate_block(self, block_id: str) -> None:\n        """PATCH 26 — Duplique un bloc et l\'insère juste après l\'original."""\n        index = next(\n            (i for i, b in enumerate(self._document.blocks) if b.id == block_id), None\n        )\n        if index is None:\n            return\n        raw = self._document.blocks[index].to_dict()\n        raw["id"] = str(uuid.uuid4())\n        duplicate = block_from_dict(raw)\n        self._document.add_block(duplicate, index=index + 1)\n        self._render_document()\n\n    def _convert_block(self, block_id: str, target_id: str) -> None:\n        """PATCH 26 — Remplace un bloc par un autre type, contenu conservé."""\n        factory = self._block_factory(target_id)\n        if factory is None:\n            return\n        index = next(\n            (i for i, b in enumerate(self._document.blocks) if b.id == block_id), None\n        )\n        if index is None:\n            return\n\n        old_block = self._document.blocks[index]\n        new_block = factory()\n        if hasattr(new_block, "content"):\n            new_block.content = getattr(old_block, "content", "")\n\n        self._document.remove_block(block_id)\n        self._document.add_block(new_block, index=index)\n        self._render_document()\n\n    def _append_block_from_command(self, command_id: str) -> None:\n        """PATCH 26 — Ajoute en fin de document le bloc associé à `command_id`."""\n        if command_id == "image":\n            self._add_image_block()\n            return\n\n        factory = self._block_factory(command_id)\n        if factory is None:\n            return\n        block = factory()\n        self._document.add_block(block)\n        widget = self._create_content_widget_for_block(block)\n        self._blocks_layout.addWidget(self._wrap(widget, block.id))\n\n    def _block_factory(self, command_id: str):\n        """Fabrique de bloc partagée entre le menu "/" (PATCH 25) et le\n        menu contextuel (PATCH 26)."""\n        return {\n            "text": lambda: TextBlock(),\n            "heading1": lambda: HeadingBlock(level=1),\n            "heading2": lambda: HeadingBlock(level=2),\n            "heading3": lambda: HeadingBlock(level=3),\n            "checklist": lambda: ChecklistBlock(),\n            "linked_checklist": lambda: LinkedChecklistBlock(),\n            "table": self._new_default_table_block,\n            "simple_table": lambda: SimpleTableBlock(),\n            "gantt": lambda: GanttBlock(),\n            "dependency_gantt": lambda: DependencyGanttBlock(),\n            "line_chart": lambda: LineChartBlock(),\n            "bar_chart": lambda: BarChartBlock(),\n            "formula": lambda: FormulaBlock(),\n            "separator": lambda: SeparatorBlock(),\n            "quote": lambda: QuoteBlock(),\n            "code": lambda: CodeBlock(),\n            "list": self._new_default_list_block,\n        }.get(command_id)\n\n    # -- Sauvegarde / chargement (PATCH 8) --------------------------------\n\n    def _set_current_file(self, path: Path | None) -> None:\n        self._current_file = path\n        title = f"Notion Lite {__version__}"\n        self.setWindowTitle(title + (f" — {path.name}" if path else ""))\n\n    def _new_document(self) -> None:\n        """PATCH 48 — Nouveau : repart du template par défaut "Méthodo Momo"."""\n        self._document = build_momo_template()\n        self._set_current_file(None)\n        self._render_document()\n\n    def _new_blank_document(self) -> None:\n        """PATCH 8 — Nouveau document vide (sans template)."""\n        self._document = Document()\n        self._set_current_file(None)\n        self._render_document()\n\n    def _open_document(self) -> None:\n        """PATCH 8 — Ouvrir : charge un document depuis un fichier JSON."""\n        path_str, _ = QFileDialog.getOpenFileName(\n            self, "Ouvrir un document", "", "Notion Lite (*.json)"\n        )\n        if not path_str:\n            return\n\n        try:\n            raw = json.loads(Path(path_str).read_text(encoding="utf-8"))\n            document = Document.from_dict(raw)\n        except (OSError, ValueError, KeyError) as exc:\n            QMessageBox.critical(\n                self, "Erreur d\'ouverture", f"Impossible d\'ouvrir le fichier :\\n{exc}"\n            )\n            return\n\n        self._document = document\n        self._set_current_file(Path(path_str))\n        self._render_document()\n\n    def _import_markdown(self) -> None:\n        """PATCH 39 — Importe un fichier Markdown, remplace le document\n        courant (comme "Ouvrir", mais sans fichier de sauvegarde associé\n        : un import Markdown n\'a pas de round-trip garanti vers .json)."""\n        path_str, _ = QFileDialog.getOpenFileName(\n            self, "Importer un Markdown", "", "Markdown (*.md)"\n        )\n        if not path_str:\n            return\n\n        try:\n            text = Path(path_str).read_text(encoding="utf-8")\n            document = markdown_to_document(text)\n        except OSError as exc:\n            QMessageBox.critical(\n                self, "Erreur d\'import", f"Impossible de lire le fichier :\\n{exc}"\n            )\n            return\n\n        self._document = document\n        self._set_current_file(None)\n        self._render_document()\n\n    def _import_html(self) -> None:\n        """PATCH 40 — Importe un fichier HTML, remplace le document courant\n        (comme l\'import Markdown : pas de fichier de sauvegarde associé)."""\n        path_str, _ = QFileDialog.getOpenFileName(\n            self, "Importer un HTML", "", "HTML (*.html *.htm)"\n        )\n        if not path_str:\n            return\n\n        try:\n            text = Path(path_str).read_text(encoding="utf-8")\n            document = html_to_document(text)\n        except OSError as exc:\n            QMessageBox.critical(\n                self, "Erreur d\'import", f"Impossible de lire le fichier :\\n{exc}"\n            )\n            return\n\n        self._document = document\n        self._set_current_file(None)\n        self._render_document()\n\n    def _write_document(self, path: Path) -> None:\n        try:\n            path.write_text(\n                json.dumps(self._document.to_dict(), ensure_ascii=False, indent=2),\n                encoding="utf-8",\n            )\n        except OSError as exc:\n            QMessageBox.critical(\n                self, "Erreur de sauvegarde", f"Impossible d\'enregistrer le fichier :\\n{exc}"\n            )\n            return\n        self._set_current_file(path)\n\n    def _save_document(self) -> None:\n        """PATCH 8 — Sauvegarder : réutilise le fichier courant, sinon demande où."""\n        if self._current_file is None:\n            self._save_document_as()\n            return\n        self._write_document(self._current_file)\n\n    def _save_document_as(self) -> None:\n        """PATCH 8 — Sauvegarder sous : demande toujours un nouveau fichier."""\n        path_str, _ = QFileDialog.getSaveFileName(\n            self, "Sauvegarder sous", "", "Notion Lite (*.json)"\n        )\n        if not path_str:\n            return\n        path = Path(path_str)\n        if path.suffix != ".json":\n            path = path.with_suffix(".json")\n        self._write_document(path)\n\n    def _export_pdf(self) -> None:\n        """PATCH 36 — Exporte le document courant en PDF."""\n        path_str, _ = QFileDialog.getSaveFileName(self, "Exporter en PDF", "", "PDF (*.pdf)")\n        if not path_str:\n            return\n        path = Path(path_str)\n        if path.suffix != ".pdf":\n            path = path.with_suffix(".pdf")\n        export_document_to_pdf(self._document, str(path))\n\n    def _export_markdown(self) -> None:\n        """PATCH 37 — Exporte le document courant en Markdown."""\n        path_str, _ = QFileDialog.getSaveFileName(self, "Exporter en Markdown", "", "Markdown (*.md)")\n        if not path_str:\n            return\n        path = Path(path_str)\n        if path.suffix != ".md":\n            path = path.with_suffix(".md")\n        path.write_text(document_to_markdown(self._document), encoding="utf-8")\n\n    def _export_html(self) -> None:\n        """PATCH 38 — Exporte le document courant en HTML autonome."""\n        path_str, _ = QFileDialog.getSaveFileName(self, "Exporter en HTML", "", "HTML (*.html)")\n        if not path_str:\n            return\n        path = Path(path_str)\n        if path.suffix != ".html":\n            path = path.with_suffix(".html")\n        title = path.stem\n        path.write_text(document_to_full_html(self._document, title=title), encoding="utf-8")\n\n    # -- Gestion des blocs texte -----------------------------------------\n\n    def _create_text_widget(self, block: TextBlock) -> TextBlockWidget:\n        """Crée un TextBlockWidget entièrement connecté."""\n        widget = TextBlockWidget(block)\n        widget.focused.connect(self._on_text_widget_focused)\n        widget.split_requested.connect(self._on_split_requested)\n        widget.merge_requested.connect(self._on_merge_requested)\n        widget.delete_requested.connect(self._on_delete_requested)\n        widget.command_requested.connect(self._on_command_requested)\n        widget.link_activated.connect(self._scroll_to_block)\n        return widget\n\n    def _add_text_block(self, content: str = "") -> None:\n        """Ajoute un nouveau bloc texte au document et à l\'affichage."""\n        block = TextBlock(content=content)\n        self._document.add_block(block)\n\n        widget = self._create_text_widget(block)\n        self._blocks_layout.addWidget(self._wrap(widget, block.id))\n        widget.setFocus()\n\n    def _add_checklist_block(self) -> None:\n        """Ajoute un nouveau bloc checklist (PATCH 10), avec un premier élément vide."""\n        block = ChecklistBlock()\n        block.add_item()\n        self._document.add_block(block)\n\n        widget = ChecklistBlockWidget(block)\n        self._blocks_layout.addWidget(self._wrap(widget, block.id))\n\n    def _add_simple_table_block(self) -> None:\n        """PATCH 24 — Ajoute un tableau simple (grille de texte 2×2)."""\n        block = SimpleTableBlock()\n        self._document.add_block(block)\n\n        widget = SimpleTableBlockWidget(block)\n        self._blocks_layout.addWidget(self._wrap(widget, block.id))\n\n    def _add_table_block(self) -> None:\n        """PATCH 14 — Ajoute un nouveau bloc tableau (2 colonnes, 1 ligne)."""\n        block = TableBlock()\n        block.add_column(name="Colonne 1")\n        block.add_column(name="Colonne 2")\n        block.add_row()\n        self._document.add_block(block)\n\n        widget = TableBlockWidget(block, self._document)\n        self._blocks_layout.addWidget(self._wrap(widget, block.id))\n\n    def _add_list_block(self) -> None:\n        """PATCH 23 — Ajoute un bloc liste (une puce vide)."""\n        block = ListBlock()\n        block.add_item("")\n        self._document.add_block(block)\n\n        widget = ListBlockWidget(block)\n        self._blocks_layout.addWidget(self._wrap(widget, block.id))\n\n    def _add_code_block(self) -> None:\n        """PATCH 22 — Ajoute un bloc de code (police monospace)."""\n        block = CodeBlock()\n        self._document.add_block(block)\n\n        widget = CodeBlockWidget(block)\n        self._blocks_layout.addWidget(self._wrap(widget, block.id))\n\n    def _add_quote_block(self) -> None:\n        """PATCH 21 — Ajoute un bloc citation."""\n        block = QuoteBlock()\n        self._document.add_block(block)\n\n        widget = QuoteBlockWidget(block)\n        self._blocks_layout.addWidget(self._wrap(widget, block.id))\n\n    def _add_separator_block(self) -> None:\n        """PATCH 20 — Ajoute un séparateur (ligne horizontale)."""\n        block = SeparatorBlock()\n        self._document.add_block(block)\n\n        widget = SeparatorBlockWidget(block)\n        self._blocks_layout.addWidget(self._wrap(widget, block.id))\n\n    def _add_gantt_block(self) -> None:\n        """PATCH 19 — Ajoute un bloc Gantt vide (à configurer via ses sélecteurs)."""\n        block = GanttBlock()\n        self._document.add_block(block)\n\n        widget = GanttBlockWidget(block, self._document)\n        self._blocks_layout.addWidget(self._wrap(widget, block.id))\n\n    def _add_image_block(self) -> None:\n        """PATCH 12 — Insère une image choisie sur le disque, en fin de document."""\n        path_str, _ = QFileDialog.getOpenFileName(\n            self,\n            "Insérer une image",\n            "",\n            "Images (*.png *.jpg *.jpeg *.gif *.bmp *.webp)",\n        )\n        if not path_str:\n            return\n\n        path = Path(path_str)\n        try:\n            raw_bytes = path.read_bytes()\n        except OSError as exc:\n            QMessageBox.critical(\n                self, "Erreur d\'insertion", f"Impossible de lire l\'image :\\n{exc}"\n            )\n            return\n\n        block = ImageBlock(\n            image_base64=base64.b64encode(raw_bytes).decode("ascii"),\n            image_format=path.suffix.lstrip(".").lower() or "png",\n        )\n        self._document.add_block(block)\n        content = self._create_content_widget_for_block(block)\n        self._blocks_layout.addWidget(self._wrap(content, block.id))\n\n    def _move_block(self, block_id: str, delta: int) -> None:\n        """PATCH 12 — Déplace un bloc (image, checklist, ...) d\'une position."""\n        index = next(\n            (i for i, b in enumerate(self._document.blocks) if b.id == block_id), None\n        )\n        if index is None:\n            return\n        self._document.move_block(block_id, index + delta)\n        self._render_document()\n\n    def _delete_block(self, block_id: str) -> None:\n        """PATCH 12 — Supprime un bloc (image, ...) du document."""\n        self._document.remove_block(block_id)\n        self._render_document()\n\n    @staticmethod\n    def _focus_widget_at_end(widget: QWidget) -> None:\n        """Donne le focus à un widget de bloc et place le curseur à la fin."""\n        widget.setFocus()\n        if isinstance(widget, QTextEdit):\n            cursor = widget.textCursor()\n            cursor.movePosition(QTextCursor.End)\n            widget.setTextCursor(cursor)\n        elif isinstance(widget, QLineEdit):\n            widget.end(False)\n\n    # -- Gestion du curseur multi-blocs (PATCH 7) -------------------------\n\n    def _on_split_requested(self, widget: TextBlockWidget, before: str, after: str) -> None:\n        """Sépare un bloc en deux à la position du curseur."""\n        widget.setPlainText(before)\n\n        new_block = TextBlock(content=after)\n        doc_index = self._document.blocks.index(widget.block)\n        self._document.add_block(new_block, index=doc_index + 1)\n\n        layout_index = self._layout_index_of_content(widget)\n        new_widget = self._create_text_widget(new_block)\n        self._blocks_layout.insertWidget(layout_index + 1, self._wrap(new_widget, new_block.id))\n\n        new_widget.setFocus()\n        cursor = new_widget.textCursor()\n        cursor.movePosition(QTextCursor.Start)\n        new_widget.setTextCursor(cursor)\n\n    def _on_merge_requested(self, widget: TextBlockWidget) -> None:\n        """Fusionne un bloc texte non vide avec le bloc texte précédent."""\n        layout_index = self._layout_index_of_content(widget)\n        if layout_index <= 0:\n            return\n\n        previous_widget = self._content_widget_at(layout_index - 1)\n        if not isinstance(previous_widget, TextBlockWidget):\n            return  # fusion uniquement entre deux blocs texte pour l\'instant\n\n        merge_position = len(previous_widget.toPlainText())\n        previous_widget.setPlainText(previous_widget.toPlainText() + widget.toPlainText())\n\n        self._remove_text_block(widget)\n\n        previous_widget.setFocus()\n        cursor = previous_widget.textCursor()\n        cursor.setPosition(merge_position)\n        previous_widget.setTextCursor(cursor)\n\n    def _on_delete_requested(self, widget: TextBlockWidget) -> None:\n        """Supprime un bloc texte vide et redonne le focus au précédent."""\n        layout_index = self._layout_index_of_content(widget)\n        if layout_index <= 0:\n            return\n\n        previous_widget = self._content_widget_at(layout_index - 1)\n\n        self._remove_text_block(widget)\n\n        if previous_widget is not None:\n            self._focus_widget_at_end(previous_widget)\n\n    def _remove_text_block(self, widget: TextBlockWidget) -> None:\n        """Retire un bloc texte du document et de l\'affichage."""\n        self._document.remove_block(widget.block.id)\n        _, container = self._find_container(widget)\n        if container is not None:\n            self._blocks_layout.removeWidget(container)\n            container.deleteLater()\n        if self._active_text_widget is widget:\n            self._active_text_widget = None\n\n    # -- Menu de commandes "/" (PATCH 25) ----------------------------------\n\n    def _on_command_requested(self, widget: TextBlockWidget) -> None:\n        """Ouvre le menu "/" ancré sous le curseur du bloc texte vide."""\n        menu = CommandMenu(self)\n        menu.command_selected.connect(lambda command_id, w=widget: self._run_command(w, command_id))\n        cursor_rect = widget.cursorRect()\n        anchor = widget.mapToGlobal(cursor_rect.bottomLeft())\n        menu.move(anchor)\n        menu.show()\n\n    def _run_command(self, widget: TextBlockWidget, command_id: str) -> None:\n        """Remplace le bloc texte (contenant juste "/") par le bloc choisi."""\n        if command_id == "image":\n            # L\'insertion d\'image passe par un sélecteur de fichier ;\n            # on se contente de vider le "/" puis de laisser le flux\n            # habituel ajouter l\'image (en fin de document).\n            widget.setPlainText("")\n            self._add_image_block()\n            return\n\n        factory = self._block_factory(command_id)\n        if factory is None:\n            return\n\n        new_block = factory()\n        doc_index = self._document.blocks.index(widget.block)\n        layout_index = self._layout_index_of_content(widget)\n\n        self._document.remove_block(widget.block.id)\n        self._document.add_block(new_block, index=doc_index)\n\n        _, old_container = self._find_container(widget)\n        if old_container is not None:\n            self._blocks_layout.removeWidget(old_container)\n            old_container.deleteLater()\n\n        if isinstance(new_block, TextBlock):\n            new_widget = self._create_text_widget(new_block)\n        else:\n            new_widget = self._create_content_widget_for_block(new_block)\n        self._blocks_layout.insertWidget(layout_index, self._wrap(new_widget, new_block.id))\n        new_widget.setFocus()\n\n    def _new_default_table_block(self) -> TableBlock:\n        block = TableBlock()\n        block.add_column(name="Colonne 1")\n        block.add_column(name="Colonne 2")\n        block.add_row()\n        return block\n\n    def _new_default_list_block(self) -> ListBlock:\n        block = ListBlock()\n        block.add_item("")\n        return block'
_SOURCES['ui.people_manager_dialog'] = '"""\nGestionnaire de personnes (PATCH 16).\n\nFenêtre listant toutes les personnes du registre partagé du document,\navec ajout, renommage et suppression. La suppression purge aussi\ntoutes les références à cette personne dans les colonnes "Personne"\ndes blocs Tableau (voir Document.remove_person).\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtCore import Qt\nfrom PySide6.QtGui import QColor\nfrom PySide6.QtWidgets import (\n    QColorDialog,\n    QDialog,\n    QHBoxLayout,\n    QInputDialog,\n    QListWidget,\n    QListWidgetItem,\n    QMessageBox,\n    QPushButton,\n    QVBoxLayout,\n)\n\nfrom core.document import Document\n\n\nclass PeopleManagerDialog(QDialog):\n    """Boîte de dialogue de gestion du registre de personnes du document."""\n\n    def __init__(self, document: Document, parent=None) -> None:\n        super().__init__(parent)\n        self._document = document\n        self.setWindowTitle("Gestionnaire de personnes")\n        self.resize(360, 400)\n\n        layout = QVBoxLayout(self)\n\n        self._list = QListWidget(self)\n        layout.addWidget(self._list)\n\n        add_row = QHBoxLayout()\n        add_button = QPushButton("Ajouter...", self)\n        add_button.clicked.connect(self._on_add)\n        add_row.addWidget(add_button)\n\n        rename_button = QPushButton("Renommer...", self)\n        rename_button.clicked.connect(self._on_rename)\n        add_row.addWidget(rename_button)\n\n        color_button = QPushButton("Couleur...", self)\n        color_button.clicked.connect(self._on_change_color)\n        add_row.addWidget(color_button)\n\n        remove_button = QPushButton("Supprimer", self)\n        remove_button.clicked.connect(self._on_remove)\n        add_row.addWidget(remove_button)\n        layout.addLayout(add_row)\n\n        close_button = QPushButton("Fermer", self)\n        close_button.clicked.connect(self.accept)\n        layout.addWidget(close_button)\n\n        self._refresh()\n\n    def _refresh(self) -> None:\n        self._list.clear()\n        for person in self._document.people:\n            item = QListWidgetItem(person["name"])\n            item.setData(Qt.UserRole, person["id"])\n            item.setForeground(QColor(person.get("color", "#000000")))\n            self._list.addItem(item)\n\n    def _current_person_id(self) -> str | None:\n        item = self._list.currentItem()\n        return item.data(Qt.UserRole) if item else None\n\n    def _on_add(self) -> None:\n        name, ok = QInputDialog.getText(self, "Nouvelle personne", "Nom :")\n        if ok and name.strip():\n            self._document.add_person(name.strip())\n            self._refresh()\n\n    def _on_rename(self) -> None:\n        person_id = self._current_person_id()\n        if person_id is None:\n            return\n        person = self._document.find_person(person_id)\n        name, ok = QInputDialog.getText(\n            self, "Renommer la personne", "Nom :", text=person["name"] if person else ""\n        )\n        if ok and name.strip():\n            self._document.rename_person(person_id, name.strip())\n            self._refresh()\n\n    def _on_change_color(self) -> None:\n        person_id = self._current_person_id()\n        if person_id is None:\n            return\n        person = self._document.find_person(person_id)\n        current = QColor(person.get("color", "#000000")) if person else QColor("black")\n        color = QColorDialog.getColor(current, self, "Choisir une couleur")\n        if color.isValid():\n            self._document.set_person_color(person_id, color.name())\n            self._refresh()\n\n    def _on_remove(self) -> None:\n        person_id = self._current_person_id()\n        if person_id is None:\n            return\n        person = self._document.find_person(person_id)\n        confirm = QMessageBox.question(\n            self,\n            "Supprimer la personne",\n            f"Supprimer « {person[\'name\'] if person else \'\'} » et la retirer de "\n            "toutes les cellules qui la référencent ?",\n        )\n        if confirm == QMessageBox.Yes:\n            self._document.remove_person(person_id)\n            self._refresh()\n'
_SOURCES['ui.search_dialog'] = '"""\nBoîte de dialogue de recherche et remplacement (PATCH 28 / PATCH 29).\n\nRecherche en direct (à chaque frappe) sur tout le document via\n`core.search.search_document`. Double-cliquer (ou Entrée) sur un\nrésultat ferme la boîte et fait défiler jusqu\'au bloc correspondant.\n\n« Tout remplacer » (PATCH 29) délègue à `core.replace.replace_all` et\nnotifie la fenêtre principale pour qu\'elle rafraîchisse l\'affichage ;\nl\'action reste annulable comme toute autre (historique générique du\nPATCH 27, basé sur des snapshots du document).\n"""\nfrom __future__ import annotations\n\nfrom typing import Callable, Optional\n\nfrom PySide6.QtCore import Qt\nfrom PySide6.QtWidgets import (\n    QDialog,\n    QHBoxLayout,\n    QLabel,\n    QLineEdit,\n    QListWidget,\n    QListWidgetItem,\n    QPushButton,\n    QVBoxLayout,\n)\n\nfrom core.document import Document\nfrom core.replace import replace_all\nfrom core.search import search_document\n\n\nclass SearchDialog(QDialog):\n    """Fenêtre de recherche et remplacement globaux."""\n\n    def __init__(\n        self,\n        document: Document,\n        on_result_activated: Optional[Callable[[str], None]] = None,\n        on_document_changed: Optional[Callable[[], None]] = None,\n        parent=None,\n    ) -> None:\n        super().__init__(parent)\n        self._document = document\n        self._on_result_activated = on_result_activated\n        self._on_document_changed = on_document_changed\n\n        self.setWindowTitle("Rechercher et remplacer")\n        self.resize(480, 460)\n\n        layout = QVBoxLayout(self)\n\n        self._input = QLineEdit(self)\n        self._input.setPlaceholderText("Rechercher dans le document...")\n        self._input.textChanged.connect(self._on_query_changed)\n        layout.addWidget(self._input)\n\n        replace_row = QHBoxLayout()\n        self._replacement_input = QLineEdit(self)\n        self._replacement_input.setPlaceholderText("Remplacer par...")\n        replace_row.addWidget(self._replacement_input, 1)\n\n        self._replace_all_button = QPushButton("Tout remplacer", self)\n        self._replace_all_button.clicked.connect(self._on_replace_all_clicked)\n        replace_row.addWidget(self._replace_all_button)\n        layout.addLayout(replace_row)\n\n        self._status_label = QLabel("", self)\n        layout.addWidget(self._status_label)\n\n        self._results_list = QListWidget(self)\n        self._results_list.itemActivated.connect(self._on_item_activated)\n        layout.addWidget(self._results_list)\n\n        self._input.setFocus()\n\n    def _on_query_changed(self, query: str) -> None:\n        self._results_list.clear()\n        results = search_document(self._document, query)\n\n        if not query.strip():\n            self._status_label.setText("")\n        elif not results:\n            self._status_label.setText("Aucun résultat.")\n        else:\n            plural = "s" if len(results) > 1 else ""\n            self._status_label.setText(f"{len(results)} résultat{plural}")\n\n        for result in results:\n            item = QListWidgetItem(f"[{result.location}] {result.snippet}")\n            item.setData(Qt.UserRole, result.block_id)\n            self._results_list.addItem(item)\n\n    def _on_item_activated(self, item: QListWidgetItem) -> None:\n        block_id = item.data(Qt.UserRole)\n        if block_id is None:\n            return\n        if self._on_result_activated is not None:\n            self._on_result_activated(block_id)\n        self.accept()\n\n    def _on_replace_all_clicked(self) -> None:\n        """PATCH 29 — Remplace toutes les occurrences de la recherche."""\n        query = self._input.text()\n        replacement = self._replacement_input.text()\n        count = replace_all(self._document, query, replacement)\n\n        if count == 0:\n            self._status_label.setText("Aucun remplacement effectué.")\n            return\n\n        if self._on_document_changed is not None:\n            self._on_document_changed()\n\n        plural = "s" if count > 1 else ""\n        self._status_label.setText(f"{count} remplacement{plural} effectué{plural}.")\n        self._on_query_changed(self._input.text())\n'
_SOURCES['ui.settings'] = '"""\nRéglages globaux de l\'application (PATCH 49, révisé PATCH 51).\n\nStockage simple en mémoire pour la durée de la session (même\napproche que le thème courant dans ui.themes.theme, mais ces\nréglages-ci sont indépendants de l\'instance QApplication).\n"""\nfrom __future__ import annotations\n\n# PATCH 51 — renommé (portée élargie aux tableaux/graphiques) et activé\n# par défaut, suite au retour utilisateur.\n_block_spacing = True\n\n# PATCH 51 — sauvegarde automatique, activée par défaut dès qu\'un\n# document a été sauvegardé une première fois (voir main_window._maybe_autosave).\n_autosave_enabled = True\n\n\ndef get_block_spacing() -> bool:\n    """Espace supplémentaire au-dessus des titres/sous-titres, tableaux\n    et graphiques, pour "laisser respirer" le document. Activable\n    depuis le menu Affichage."""\n    return _block_spacing\n\n\ndef set_block_spacing(value: bool) -> None:\n    global _block_spacing\n    _block_spacing = bool(value)\n\n\ndef get_autosave_enabled() -> bool:\n    return _autosave_enabled\n\n\ndef set_autosave_enabled(value: bool) -> None:\n    global _autosave_enabled\n    _autosave_enabled = bool(value)\n'
_SOURCES['ui.themes'] = ''
_PACKAGES.add('ui.themes')
_SOURCES['ui.themes.theme'] = '"""\nSystème de thèmes (préparé au PATCH 1, implémenté ici) et mode sombre\ncomplet (PATCH 32).\n\nApproche retenue : style Qt "Fusion" + QPalette dédiée par thème.\nFusion est le seul style Qt qui respecte fidèlement la QPalette pour\nTOUS les widgets standards (boutons, cases à cocher, listes, tables,\nmenus, champs de texte...), y compris ceux utilisés par les blocs\npersonnalisés (checklist, tableau, code, citation...) sans qu\'il soit\nnécessaire de maintenir une feuille de style QSS séparée par widget.\nBasculer de thème revient donc simplement à changer la QPalette de\nl\'application, un point unique pour tout le programme.\n"""\nfrom __future__ import annotations\n\nfrom PySide6.QtCore import Qt\nfrom PySide6.QtGui import QColor, QGuiApplication, QPalette\nfrom PySide6.QtWidgets import QApplication\n\nTHEME_LIGHT = "light"\nTHEME_DARK = "dark"\nTHEME_SEPIA = "sepia"\nTHEME_HIGH_CONTRAST = "high_contrast"\n\n# Ordre d\'affichage dans le sous-menu "Thème" (PATCH 33) et de rotation\n# de `cycle_theme`. `toggle_theme` (PATCH 32) reste un simple binaire\n# clair/sombre, inchangé, pour ne pas casser son contrat existant.\nTHEMES: list[str] = [THEME_LIGHT, THEME_DARK, THEME_SEPIA, THEME_HIGH_CONTRAST]\n\nTHEME_LABELS: dict[str, str] = {\n    THEME_LIGHT: "Clair",\n    THEME_DARK: "Sombre",\n    THEME_SEPIA: "Sépia",\n    THEME_HIGH_CONTRAST: "Contraste élevé",\n}\n\n_QSS_STYLE_NAME = "Fusion"\n\n\ndef _light_palette() -> QPalette:\n    """Palette claire explicite (PATCH 32 correctif).\n\n    Volontairement codée en dur plutôt que `QPalette()` : sur certains\n    systèmes (ou IDE, ex. PyCharm) la palette Qt par défaut suit déjà\n    le thème sombre de l\'OS, ce qui rendait le thème "clair" à peine\n    différent du thème sombre lors du basculement.\n    """\n    palette = QPalette()\n\n    window = QColor(240, 240, 240)\n    base = QColor(255, 255, 255)\n    alternate_base = QColor(233, 233, 233)\n    text = QColor(20, 20, 20)\n    disabled_text = QColor(150, 150, 150)\n    highlight = QColor(61, 132, 199)\n\n    palette.setColor(QPalette.Window, window)\n    palette.setColor(QPalette.WindowText, text)\n    palette.setColor(QPalette.Base, base)\n    palette.setColor(QPalette.AlternateBase, alternate_base)\n    palette.setColor(QPalette.ToolTipBase, base)\n    palette.setColor(QPalette.ToolTipText, text)\n    palette.setColor(QPalette.Text, text)\n    palette.setColor(QPalette.Button, window)\n    palette.setColor(QPalette.ButtonText, text)\n    palette.setColor(QPalette.BrightText, QColor(200, 0, 0))\n    palette.setColor(QPalette.Link, highlight)\n    palette.setColor(QPalette.Highlight, highlight)\n    palette.setColor(QPalette.HighlightedText, QColor(255, 255, 255))\n\n    palette.setColor(QPalette.Disabled, QPalette.WindowText, disabled_text)\n    palette.setColor(QPalette.Disabled, QPalette.Text, disabled_text)\n    palette.setColor(QPalette.Disabled, QPalette.ButtonText, disabled_text)\n\n    return palette\n\n\ndef _dark_palette() -> QPalette:\n    """Palette sombre complète : fond, texte, champs de saisie, sélection,\n    infobulles, et états désactivés."""\n    palette = QPalette()\n\n    window = QColor(45, 45, 45)\n    base = QColor(35, 35, 35)\n    alternate_base = QColor(53, 53, 53)\n    text = QColor(220, 220, 220)\n    disabled_text = QColor(127, 127, 127)\n    highlight = QColor(61, 132, 199)\n\n    palette.setColor(QPalette.Window, window)\n    palette.setColor(QPalette.WindowText, text)\n    palette.setColor(QPalette.Base, base)\n    palette.setColor(QPalette.AlternateBase, alternate_base)\n    palette.setColor(QPalette.ToolTipBase, window)\n    palette.setColor(QPalette.ToolTipText, text)\n    palette.setColor(QPalette.Text, text)\n    palette.setColor(QPalette.Button, window)\n    palette.setColor(QPalette.ButtonText, text)\n    palette.setColor(QPalette.BrightText, QColor(255, 80, 80))\n    palette.setColor(QPalette.Link, highlight)\n    palette.setColor(QPalette.Highlight, highlight)\n    palette.setColor(QPalette.HighlightedText, QColor(255, 255, 255))\n\n    palette.setColor(QPalette.Disabled, QPalette.WindowText, disabled_text)\n    palette.setColor(QPalette.Disabled, QPalette.Text, disabled_text)\n    palette.setColor(QPalette.Disabled, QPalette.ButtonText, disabled_text)\n\n    return palette\n\n\ndef _sepia_palette() -> QPalette:\n    """Thème "Sépia" (PATCH 33) : fond chaud beige, confortable en\n    lecture prolongée, à mi-chemin entre clair et sombre."""\n    palette = QPalette()\n\n    window = QColor(238, 227, 203)\n    base = QColor(250, 243, 227)\n    alternate_base = QColor(230, 216, 188)\n    text = QColor(59, 44, 28)\n    disabled_text = QColor(150, 135, 110)\n    highlight = QColor(176, 122, 46)\n\n    palette.setColor(QPalette.Window, window)\n    palette.setColor(QPalette.WindowText, text)\n    palette.setColor(QPalette.Base, base)\n    palette.setColor(QPalette.AlternateBase, alternate_base)\n    palette.setColor(QPalette.ToolTipBase, base)\n    palette.setColor(QPalette.ToolTipText, text)\n    palette.setColor(QPalette.Text, text)\n    palette.setColor(QPalette.Button, window)\n    palette.setColor(QPalette.ButtonText, text)\n    palette.setColor(QPalette.BrightText, QColor(160, 40, 20))\n    palette.setColor(QPalette.Link, highlight)\n    palette.setColor(QPalette.Highlight, highlight)\n    palette.setColor(QPalette.HighlightedText, QColor(255, 255, 255))\n\n    palette.setColor(QPalette.Disabled, QPalette.WindowText, disabled_text)\n    palette.setColor(QPalette.Disabled, QPalette.Text, disabled_text)\n    palette.setColor(QPalette.Disabled, QPalette.ButtonText, disabled_text)\n\n    return palette\n\n\ndef _high_contrast_palette() -> QPalette:\n    """Thème "Contraste élevé" (PATCH 33) : noir/blanc pur et accent\n    saturé, pour l\'accessibilité (faible vision, luminosité ambiante\n    difficile)."""\n    palette = QPalette()\n\n    window = QColor(0, 0, 0)\n    base = QColor(0, 0, 0)\n    alternate_base = QColor(30, 30, 30)\n    text = QColor(255, 255, 255)\n    disabled_text = QColor(160, 160, 160)\n    highlight = QColor(255, 210, 0)\n\n    palette.setColor(QPalette.Window, window)\n    palette.setColor(QPalette.WindowText, text)\n    palette.setColor(QPalette.Base, base)\n    palette.setColor(QPalette.AlternateBase, alternate_base)\n    palette.setColor(QPalette.ToolTipBase, window)\n    palette.setColor(QPalette.ToolTipText, text)\n    palette.setColor(QPalette.Text, text)\n    palette.setColor(QPalette.Button, window)\n    palette.setColor(QPalette.ButtonText, text)\n    palette.setColor(QPalette.BrightText, QColor(255, 60, 60))\n    palette.setColor(QPalette.Link, highlight)\n    palette.setColor(QPalette.Highlight, highlight)\n    palette.setColor(QPalette.HighlightedText, QColor(0, 0, 0))\n\n    palette.setColor(QPalette.Disabled, QPalette.WindowText, disabled_text)\n    palette.setColor(QPalette.Disabled, QPalette.Text, disabled_text)\n    palette.setColor(QPalette.Disabled, QPalette.ButtonText, disabled_text)\n\n    return palette\n\n\n_PALETTE_BUILDERS: dict[str, "callable"] = {\n    THEME_LIGHT: _light_palette,\n    THEME_DARK: _dark_palette,\n    THEME_SEPIA: _sepia_palette,\n    THEME_HIGH_CONTRAST: _high_contrast_palette,\n}\n\n\ndef build_palette(theme_name: str) -> QPalette:\n    """Construit la QPalette correspondant à `theme_name` (fonction pure,\n    testable sans boucle d\'événements). Repli sur le thème clair si\n    `theme_name` est inconnu."""\n    builder = _PALETTE_BUILDERS.get(theme_name, _light_palette)\n    return builder()\n\n\ndef detect_system_theme() -> str:\n    """Détecte le thème clair/sombre de l\'OS via QStyleHints (Qt >= 6.5).\n\n    Retourne THEME_DARK si l\'OS est en mode sombre, THEME_LIGHT sinon\n    (y compris si la détection est indisponible/inconnue : repli sûr).\n    """\n    try:\n        color_scheme = QGuiApplication.styleHints().colorScheme()\n    except Exception:\n        return THEME_LIGHT\n    if color_scheme == Qt.ColorScheme.Dark:\n        return THEME_DARK\n    return THEME_LIGHT\n\n\ndef apply_theme(app: QApplication, theme_name: str) -> None:\n    """Applique le thème à toute l\'application (un seul point d\'entrée)."""\n    if theme_name not in THEMES:\n        theme_name = THEME_LIGHT\n    app.setStyle(_QSS_STYLE_NAME)\n    app.setPalette(build_palette(theme_name))\n    app.setProperty("notion_lite_theme", theme_name)\n\n\ndef current_theme(app: QApplication) -> str:\n    """Thème actuellement appliqué (clair par défaut si jamais défini)."""\n    return app.property("notion_lite_theme") or THEME_LIGHT\n\n\ndef toggle_theme(app: QApplication) -> str:\n    """Bascule clair <-> sombre et retourne le nouveau thème (PATCH 32,\n    contrat conservé tel quel : toujours binaire, indépendant des\n    thèmes supplémentaires du PATCH 33)."""\n    new_theme = THEME_DARK if current_theme(app) == THEME_LIGHT else THEME_LIGHT\n    apply_theme(app, new_theme)\n    return new_theme\n\n\ndef cycle_theme(app: QApplication) -> str:\n    """PATCH 33 — Passe au thème suivant dans `THEMES` (boucle), pour\n    parcourir l\'ensemble des thèmes disponibles (pas seulement\n    clair/sombre)."""\n    current = current_theme(app)\n    index = THEMES.index(current) if current in THEMES else 0\n    new_theme = THEMES[(index + 1) % len(THEMES)]\n    apply_theme(app, new_theme)\n    return new_theme\n'
_SOURCES['ui.toolbar'] = '"""\nBarre d\'outils principale.\n\nPATCH 5 : actions de base (nouveau bloc, mise en forme simple).\nPATCH 6 : mise en forme complète (barré, alignement, listes,\ncitation, code).\n\nLa toolbar fait partie du cadre de QMainWindow (pas de la zone de\ncontenu défilable) : tout ce qu\'elle contient, y compris le bouton\nd\'information, reste donc fixe en haut, indépendamment du scroll.\n"""\nfrom __future__ import annotations\n\nfrom typing import Callable, Optional\n\nfrom PySide6.QtGui import QAction, QIcon\nfrom PySide6.QtWidgets import QSizePolicy, QSpinBox, QToolBar, QWidget\n\n# (clé d\'action, libellé affiché). label=None -> séparateur.\n_ACTIONS: list[tuple[str, Optional[str]]] = [\n    ("new_block", "Nouveau bloc"),\n    ("new_checklist", "Nouvelle checklist"),\n    ("new_image", "Insérer une image"),\n    ("new_table", "Nouveau tableau"),\n    ("new_simple_table", "Nouveau tableau simple"),\n    ("new_gantt", "Nouveau Gantt"),\n    ("new_separator", "Insérer un séparateur"),\n    ("new_quote", "Insérer une citation"),\n    ("new_code", "Insérer un bloc de code"),\n    ("new_list", "Insérer une liste"),\n    ("sep1", None),\n    ("bold", "Gras"),\n    ("italic", "Italique"),\n    ("underline", "Souligné"),\n    ("strikethrough", "Barré"),\n    ("sep2", None),\n    ("align_left", "Aligner à gauche"),\n    ("align_center", "Centrer"),\n    ("align_right", "Aligner à droite"),\n    ("align_justify", "Justifier"),\n    ("sep3", None),\n    ("bullet_list", "Liste à puces"),\n    ("numbered_list", "Liste numérotée"),\n    ("quote", "Citation"),\n    ("code", "Code"),\n    ("sep4", None),\n    ("color", "Couleur"),\n    ("sep5", None),\n    ("insert_link", "Lien interne..."),\n    ("insert_emoji", "Emoji..."),\n]\n\n\nclass MainToolBar(QToolBar):\n    """Barre d\'outils exposant les actions de mise en forme de l\'éditeur.\n\n    Args:\n        actions: dictionnaire {clé_action: callback sans argument},\n            une entrée par clé listée dans _ACTIONS (hors séparateurs).\n        on_size_changed: callback appelé avec la nouvelle taille en pt.\n        on_info: callback appelé au clic sur l\'icône d\'information.\n        info_icon_path: chemin vers l\'icône (i) affichée à droite.\n    """\n\n    def __init__(\n        self,\n        actions: dict[str, Callable[[], None]],\n        on_size_changed: Callable[[int], None],\n        on_info: Callable[[], None],\n        info_icon_path: str,\n        parent=None,\n    ) -> None:\n        super().__init__("Barre d\'outils", parent)\n        self.setMovable(False)\n\n        for key, label in _ACTIONS:\n            if label is None:\n                self.addSeparator()\n                continue\n            action = QAction(label, self)\n            action.triggered.connect(actions[key])\n            self.addAction(action)\n\n        self._size_spin = QSpinBox(self)\n        self._size_spin.setRange(8, 72)\n        self._size_spin.setValue(14)\n        self._size_spin.setSuffix(" pt")\n        self._size_spin.valueChanged.connect(on_size_changed)\n        self.addWidget(self._size_spin)\n\n        # Pousse ce qui suit (l\'icône d\'info) tout à droite de la barre.\n        spacer = QWidget(self)\n        spacer.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)\n        self.addWidget(spacer)\n\n        info_action = QAction(QIcon(info_icon_path), "", self)\n        info_action.setToolTip("Informations et choix de design")\n        info_action.triggered.connect(on_info)\n        self.addAction(info_action)\n'


class _EmbeddedLoader(importlib.abc.Loader):
    def __init__(self, name):
        self._name = name

    def create_module(self, spec):
        module = types.ModuleType(spec.name)
        module.__file__ = f'<embedded:{spec.name}>'
        module.__loader__ = self
        module.__spec__ = spec
        if spec.submodule_search_locations is not None:
            module.__path__ = []
            module.__package__ = spec.name
        else:
            module.__package__ = spec.name.rpartition('.')[0]
        return module

    def exec_module(self, module):
        exec(compile(_SOURCES[self._name], module.__file__, 'exec'), module.__dict__)


class _EmbeddedFinder(importlib.abc.MetaPathFinder):
    def find_spec(self, name, path, target=None):
        if name not in _SOURCES:
            return None
        is_pkg = name in _PACKAGES
        spec = importlib.util.spec_from_loader(name, _EmbeddedLoader(name), is_package=is_pkg)
        return spec


sys.meta_path.insert(0, _EmbeddedFinder())


"""
Notion Lite - Point d'entrée de l'application.
"""
import sys

from PySide6.QtWidgets import QApplication

from ui.main_window import MainWindow
from ui.themes.theme import apply_theme, detect_system_theme


def main() -> None:
    app = QApplication(sys.argv)
    app.setApplicationName("Notion Lite")
    apply_theme(app, detect_system_theme())

    window = MainWindow()
    window.showMaximized()

    sys.exit(app.exec())




if __name__ == "__main__":
    main()
